window.PHASES = [{"n":1,"t":"Devenir comme Jésus","sub":"Comprendre la vie chrétienne"},{"n":2,"t":"Former des disciples","sub":"La formation des mentors"},{"n":3,"t":"Demeurer et porter du fruit","sub":"Concepts approfondis"}];
window.LESSONS = [{"n":"1-1","ph":1,"etape":"Étape 1 · Les fondements","t":"Vue d'ensemble de la vie chrétienne","fil":"L'image sur la boîte du puzzle","hook":"Et si tu avais toutes les pièces du puzzle… sans l'image sur la boîte ?","lire":"Jean 5.24 ; 1 Corinthiens 3.10-15","sup":{"phrase":"La vie chrétienne est comme l'image sur la boîte d'un puzzle : chaque vérité biblique est une pièce, et cette leçon te montre l'image entière.","dec":["Pourquoi tant de chrétiens se découragent sans « l'image de la boîte ».","Les sept étapes de la vie chrétienne, de la naissance jusqu'à l'éternité.","La différence entre le tribunal de Christ et le jugement des incroyants."],"pts":[["Le problème : des pièces sans image","J'accumule des informations (Bible, sermons, livres, amis) sans savoir où elles vont dans ma vie. Résultat : je retourne en arrière, je me fais une liste de règles, ou je sépare ma « vie d'église » de ma « vie de tous les jours ». La réponse : voir ma vie comme un tout et y impliquer Dieu partout, 24 h sur 24.",""],["Avant Christ : esclave et « mort »","Chacun de nous a traversé cette période : éloigné de Dieu, dans les ténèbres, sans espérance. Celui qui rejette Christ bâtit sa maison sur le sable et ira au jugement des incroyants.","Matthieu 7.24-27 ; Apocalypse 20.11-15"],["La croix : l'événement le plus important de ma vie","En croyant, je suis passé de la mort à la vie : le Seigneur habite en moi. La vie éternelle commence maintenant, pas à ma mort.","Jean 5.24"],["La vie nouvelle : une entrée, pas une arrivée","Le salut n'est que le commencement. Comme une plante (semis, jeune arbre, arbre) ou un enfant (bébé, adolescent, adulte), je dois grandir. Pour cela, tout nouveau croyant a besoin d'un parent spirituel qui l'accompagne.","1 Thessaloniciens 2.7-13"],["Le but : mûrir, porter du fruit, me reproduire","Dieu veut faire de moi un chrétien mûr, qui porte du fruit et qui aide d'autres à naître et à grandir.","Romains 7.4"],["Un seul fondement, mais je choisis comment bâtir","Le fondement, c'est Christ : il est le même pour tous les croyants. Ce qui change, c'est ce que je bâtis dessus avec mon temps, mon énergie et mes biens. Ce que je laisse le Saint-Esprit utiliser devient or, argent, pierres précieuses ; ce que je lui refuse devient bois, foin, chaume.","1 Corinthiens 3.10-15"],["Le tribunal de Christ : la cérémonie des récompenses","Chaque croyant comparaîtra devant Jésus pour être récompensé de ce qu'il a laissé l'Esprit faire à travers lui. Pas de punition, pas de peur : mais une perte de récompenses est possible. Aucun incroyant n'y sera.","2 Corinthiens 5.9-10 ; Matthieu 6.20-21"]],"schema":{"type":"flow","titre":"Le schéma à retenir : les 7 étapes","items":[["1","Avant Christ","esclave, « mort »"],["2","Sur le sable","sans fondement"],["3","La croix","de la mort à la vie"],["4","La vie nouvelle","grandir, accompagné"],["5","Le but","mûrir, fruit, reproduction"],["6","Le roc","bâtir sur Christ"],["7","Le tribunal","les récompenses"]]},"table":{"titre":"À ne pas confondre","head":["","Le tribunal de Christ","Le jugement des incroyants"],"rows":[["Qui ?","Tous les croyants, un par un","Ceux qui ont rejeté Christ"],["Pour quoi ?","Récompenses ou perte de récompenses ; pas de punition","Jugés selon leurs œuvres"],["Ensuite ?","Le ciel","L'existence éternelle sans Dieu"]]},"piege":[["La vie éternelle commence à la mort.","Celui qui croit « a » la vie éternelle, dès maintenant (Jean 5.24)."],["Au tribunal de Christ, Dieu décide si je suis sauvé.","Le tribunal de Christ ne concerne que les croyants : il s'agit de récompenses, non de salut."]],"astuce":"Écris Jean 5.24 sur une carte et lis-la chaque matin pendant une semaine : « de la mort à la vie ».","jesus":"Jésus n'avait pas une vie « spirituelle » et une vie « ordinaire » : tout était vécu devant le Père. « Je fais toujours les choses qui lui plaisent » (Jean 8.29).","royaume":"Jésus n'a pas prêché une religion mais un Royaume (Matthieu 4.17). Le plan de Dieu : étendre son règne sur la terre à travers l'homme (Genèse 1.26).","mediter":"Dieu ne veut pas une part de ma semaine : il veut être le centre de toute ma vie. Ce que je lui refuse brûlera ; ce que je lui remets demeure.","mots":[["Fondement","Jésus-Christ, la base unique sur laquelle chaque croyant bâtit sa vie."],["Tribunal de Christ","La cérémonie où chaque croyant reçoit (ou perd) des récompenses éternelles."],["Parent spirituel","Un croyant plus mûr qui accompagne un nouveau croyant pour qu'il grandisse."]]},"wb":{"but":"Voir toute la vie chrétienne sur une seule image, comme l'image sur la boîte d'un puzzle, et savoir où j'en suis.","ref":"Jean 5.24","verse":"En vérité, en vérité, je vous dis que celui qui entend ma parole, et qui croit celui qui m’a envoyé, a la vie éternelle et ne vient pas en jugement; mais il est passé de la mort à la vie.","q":["Pourquoi le manuel compare-t-il la vie chrétienne à l'image sur la boîte d'un puzzle ?","Écris dans l'ordre les sept éléments de la vue d'ensemble.","Selon Jean 5.24, que possède déjà celui qui croit ? De quoi est-il passé, et vers quoi ?","Quel est le seul fondement de ma vie, et qu'est-ce qui dépend de moi quand je bâtis dessus (1 Corinthiens 3.11-15) ?","Quelle différence y a-t-il entre le jugement des incroyants et le tribunal de Christ ?","Quel est le triple but de la vie nouvelle ?"],"vf":["La vie éternelle commence au moment de la mort.","Au tribunal de Christ, les croyants sont jugés pour savoir s'ils seront sauvés.","Un nouveau croyant a besoin d'un parent spirituel pour grandir.","Accumuler des connaissances bibliques suffit pour grandir."],"vfKey":[false,false,true,false],"ex":[{"k":"C1","q":"Redessine de mémoire le schéma des sept éléments, puis marque d'une croix l'endroit où tu es aujourd'hui.","type":"text","rows":6,"hint":"En ligne : décris ou résume ton schéma avec tes mots (tu peux aussi le dessiner sur papier et le montrer à ton mentor)."},{"k":"C2","q":"Note trois choses que tu sais de la Bible mais que tu n'arrives pas à relier à ta vie. Place chacune sur ton schéma.","type":"text","rows":6}],"d":["Mes 15 minutes avec Dieu","Chaque soir : « Seigneur, étais-tu le bienvenu là ? »","Expliquer le schéma à une personne","Remettre au Saint-Esprit mon temps, mon énergie ou mes biens","Je répète mon verset"],"j":"Où suis-je sur le schéma, et quel est le prochain pas que Dieu me demande ?","go":"Tu as maintenant la carte de tout le voyage. Tu sais d'où tu viens et où tu vas : avance !"},"quiz":[{"type":"tf","q":"La vie éternelle commence au moment de la mort.","a":false},{"type":"tf","q":"Au tribunal de Christ, les croyants sont jugés pour savoir s'ils seront sauvés.","a":false},{"type":"tf","q":"Un nouveau croyant a besoin d'un parent spirituel pour grandir.","a":true},{"type":"tf","q":"Accumuler des connaissances bibliques suffit pour grandir.","a":false},{"type":"mcq","q":"Quel mot correspond à cette définition ? « Jésus-Christ, la base unique sur laquelle chaque croyant bâtit sa vie. »","opts":["Question ouverte","Matériaux","Germe","Fondement"],"a":3},{"type":"mcq","q":"Quel mot correspond à cette définition ? « La cérémonie où chaque croyant reçoit (ou perd) des récompenses éternelles. »","opts":["Vieil homme","Tribunal de Christ","Pardon familial","Désert"],"a":1},{"type":"mcq","q":"Quel mot correspond à cette définition ? « Un croyant plus mûr qui accompagne un nouveau croyant pour qu'il grandisse. »","opts":["La haie","Processus","Fondement","Parent spirituel"],"a":3},{"type":"mcq","q":"Quelle est la référence du verset de la semaine : « En vérité, en vérité, je vous dis que celui qui entend ma parole, et qui croit celui qui m’a envoyé, a la vie … »","opts":["Jean 15.9","Jean 5.24","Deutéronome 6.23","2 Corinthiens 3.18"],"a":1},{"type":"tf","q":"La vie éternelle commence à la mort.","a":false,"why":"Celui qui croit « a » la vie éternelle, dès maintenant (Jean 5.24)."},{"type":"tf","q":"Au tribunal de Christ, Dieu décide si je suis sauvé.","a":false,"why":"Le tribunal de Christ ne concerne que les croyants : il s'agit de récompenses, non de salut."}]},{"n":"1-2","ph":1,"etape":"Étape 1 · Les fondements","t":"Connaître Dieu","fil":"Plus que des connaissances : une relation","hook":"Connais-tu Dieu… ou seulement des choses sur lui ?","lire":"Psaume 73 ; Romains 12.1-2","sup":{"phrase":"Dieu veut que je le connaisse intimement, et pas seulement que je connaisse des choses à son sujet : sa manière de voir la vie doit devenir la mienne.","dec":["Comment Dieu transforme : la pensée, puis l'attitude, puis la conduite.","La Parole : ma nourriture, ma lumière, ma vérité.","La prière comme une conversation, et la place des autres croyants."],"pts":[["Sa perspective doit devenir la mienne","De ma naissance à ma conversion, j'ai pris des habitudes de pensée selon le monde. Dieu veut maintenant transformer ma compréhension, pour que je voie la vie comme lui. Il n'est pas satisfait si je change seulement ma conduite extérieure : il regarde au cœur.","Romains 12.2 ; 1 Samuel 16.7"],["Mon attitude : ouvert, honnête, enseignable","Comme un mariage, la relation avec Dieu doit être entretenue. Je choisis de le chercher de tout mon cœur et de le laisser changer ma manière de penser. Le but le plus élevé de tout apprentissage, c'est de connaître Dieu !","Jérémie 9.23-24 ; Psaume 63.2 ; Matthieu 7.7-8"],["La Parole de Dieu : la vérité qui me nourrit","Toute « vérité » doit être vérifiée par la Bible. Sa Parole est digne de confiance, aussi essentielle que la nourriture ; elle est une lampe qui éclaire mon chemin et révèle mon cœur. Dieu seul m'en donne l'intelligence, si je suis honnête avec lui.","Psaume 119.105 ; Matthieu 4.4 ; 2 Timothée 3.16-17"],["Mémoriser et méditer","Trois astuces : enregistrer un verset sur mon téléphone et le réécouter ; l'écrire sur une carte ou sur mon miroir ; le méditer tout au long de la journée. Bons livres pour commencer : Jean, Luc, Actes, Genèse.","Psaume 1.1-3"],["La prière : une conversation avec mon Créateur","Je parle à Dieu avec respect, conscient que j'ai accès à lui grâce à son Fils. Et j'écoute : parfois, mon temps avec lui sera surtout de l'écouter. Je lui donne le meilleur de mon temps, pas les restes.","Hébreux 4.15-16 ; Luc 10.38-42"],["Les parties de la prière","Adoration et louange ; confession et pardon accordé aux autres ; demandes pour mes besoins ; intercession pour les autres. Le combat se livre dans le « lieu secret » : « fermer la porte », c'est faire taire mes pensées vagabondes. Un carnet à portée de main aide contre les distractions.","Matthieu 6.6 ; 1 Thessaloniciens 5.17"],["Me réunir avec d'autres croyants","Pour l'enseignement, la prière, l'étude, la redevabilité et l'encouragement. Si je le demande, Dieu me conduit vers l'assemblée où il veut se servir de moi.","Matthieu 18.20 ; Actes 2.42"]],"schema":{"type":"flow","titre":"Le schéma à retenir : comment Dieu me transforme","items":[["1","La pensée","ma compréhension"],["2","L'attitude","mes valeurs, mes convictions"],["3","La conduite","mes actions"]]},"table":{"titre":"Ma prière en quatre parties","head":["Partie","Ce que je fais","Un verset"],"rows":[["Adoration","Je loue Dieu pour qui il est","Psaume 145.2-3"],["Confession","Je reconnais mes fautes et je pardonne","Psaume 32.5 ; Marc 11.25"],["Demandes","Je lui confie mes besoins","Jacques 1.5"],["Intercession","Je prie pour les autres","Éphésiens 6.18"]]},"piege":[["Connaître Dieu, c'est connaître beaucoup de choses sur lui.","On peut savoir beaucoup sur Dieu et lui rester étranger. Connaître Dieu, c'est une relation."],["Prier, c'est donner à Dieu une liste de demandes.","La prière est une conversation : écouter compte autant que parler."]],"astuce":"Enregistre Romains 12.2 avec ta voix et réécoute-le en marchant ou en faisant tes tâches.","jesus":"Le Fils de Dieu se levait avant le jour pour prier dans un lieu désert (Marc 1.35), et il répondait à la tentation par l'Écriture : « Il est écrit » (Matthieu 4.4).","royaume":"La Bible est comme la constitution du Royaume : un citoyen doit la connaître. Par la prière, je demande que le règne du Roi vienne sur la terre : « Que ton règne vienne » (Matthieu 6.10).","mediter":"Est-ce que je donne à Dieu le meilleur moment de ma journée, ou les restes ?","mots":[["Méditer","Répéter un verset et le laisser parler à ma vie, tout au long de la journée."],["Intercéder","Prier pour les besoins des autres."],["Perspective","Ma manière de voir la vie ; Dieu veut qu'elle devienne la sienne."]]},"wb":{"but":"Que la perspective de Dieu devienne la mienne, par la Parole, la prière et la communion avec d'autres croyants.","ref":"Romains 12.2","verse":"Et ne vous conformez pas à ce siècle; mais soyez transformés par le renouvellement de votre entendement, pour que vous discerniez quelle est la volonté de Dieu, bonne et agréable et parfaite.","q":["Selon Romains 12.2, dans quel ordre la transformation se fait-elle : la pensée, l'attitude, la conduite ?","Quelles attitudes du cœur m'aident à connaître Dieu ?","Donne trois images de la Parole de Dieu vues dans la leçon, et explique l'une d'elles.","Pourquoi la prière est-elle une conversation, et pas seulement une liste de demandes ? Nomme ses quatre parties.","Pourquoi est-il important de me réunir régulièrement avec d'autres croyants ?","Que nous apprend le Psaume 73.23-26 sur l'amour de Dieu ?"],"vf":["Connaître Dieu, c'est surtout connaître beaucoup de choses sur lui.","Dans la prière, écouter Dieu est aussi important que lui parler.","Un chrétien peut grandir normalement en restant seul, sans assemblée locale.","Méditer un verset, c'est le répéter et le laisser parler à ma vie."],"vfKey":[false,true,false,true],"ex":[{"k":"C1","q":"Écris une prière de dix lignes en quatre parties : adoration, confession, demandes, intercession.","type":"text","rows":10},{"k":"C2","q":"Choisis une habitude de pensée de « ce siècle » que tu as encore. Écris à côté ce que Dieu en pense, avec un verset.","type":"text","rows":5}],"d":["Mes 15 minutes avec Dieu","Mon rendez-vous quotidien avec Dieu (lieu, heure, carnet)","Lire et méditer le Psaume 73","Donner à Dieu le meilleur moment de ma journée","Je répète mon verset"],"j":"Qu'est-ce que j'ai découvert de Dieu cette semaine, que je ne savais pas ou que je ne vivais pas ?","go":"Tu ne connais plus seulement des choses sur Dieu : tu apprends à le connaître, lui. C'est le plus beau trésor."},"quiz":[{"type":"tf","q":"Connaître Dieu, c'est surtout connaître beaucoup de choses sur lui.","a":false},{"type":"tf","q":"Dans la prière, écouter Dieu est aussi important que lui parler.","a":true},{"type":"tf","q":"Un chrétien peut grandir normalement en restant seul, sans assemblée locale.","a":false},{"type":"tf","q":"Méditer un verset, c'est le répéter et le laisser parler à ma vie.","a":true},{"type":"mcq","q":"Quel mot correspond à cette définition ? « Répéter un verset et le laisser parler à ma vie, tout au long de la journée. »","opts":["Converti / disciple","Sceau","Méditer","Émonder"],"a":2},{"type":"mcq","q":"Quel mot correspond à cette définition ? « Prier pour les besoins des autres. »","opts":["Intercéder","Demeurer","Sanctification","Comptes courts"],"a":0},{"type":"mcq","q":"Quel mot correspond à cette définition ? « Ma manière de voir la vie ; Dieu veut qu'elle devienne la sienne. »","opts":["Converti / disciple","Romains 7","Photocopie","Perspective"],"a":3},{"type":"mcq","q":"Quelle est la référence du verset de la semaine : « Et ne vous conformez pas à ce siècle; mais soyez transformés par le renouvellement de votre entendement, pour … »","opts":["Romains 12.2","1 Jean 2.6","Luc 6.12-13","1 Corinthiens 3.9"],"a":0},{"type":"tf","q":"Connaître Dieu, c'est connaître beaucoup de choses sur lui.","a":false,"why":"On peut savoir beaucoup sur Dieu et lui rester étranger. Connaître Dieu, c'est une relation."},{"type":"tf","q":"Prier, c'est donner à Dieu une liste de demandes.","a":false,"why":"La prière est une conversation : écouter compte autant que parler."}]},{"n":"1-3","ph":1,"etape":"Étape 1 · Les fondements","t":"Les principes du salut","fil":"Ce qui m'est arrivé le jour où j'ai cru","hook":"Le juge a prononcé la sentence… puis il a payé l'amende lui-même. Pourquoi ?","lire":"Éphésiens 2.1-10 ; Exode 12.1-13","sup":{"phrase":"Mon salut est l'œuvre de Dieu du début à la fin : Christ a pris ma place. Il ne repose ni sur mes efforts, ni sur mes sentiments.","dec":["La différence entre la miséricorde et la grâce.","Le principe de substitution, d'Éden à la croix.","Pourquoi la religion dit « fais », et l'Évangile « c'est fait »."],"pts":[["Miséricorde et grâce","La miséricorde : je ne reçois pas ce que je mérite. La grâce : je reçois ce que je ne mérite pas. Comme un agent de police qui donne l'amende… et la paie lui-même.",""],["Ce que j'étais, ce que Dieu a fait","J'étais mort dans mes fautes, sans espérance, sans Dieu, ennemi de Dieu. « Mais Dieu » : Christ est mort pour moi ; je suis justifié par son sang, réconcilié, rendu vivant avec Christ. Dieu ne nous juge pas « à la moyenne » de la classe : il nous compare à lui-même.","Romains 3.10-12 ; 5.6-10 ; Éphésiens 2.1-9"],["La substitution en Éden","Adam et Ève ont désobéi, puis ont essayé de se couvrir de feuilles de figuier : se rendre acceptables eux-mêmes. Dieu leur a donné des vêtements de peau : un animal innocent est mort à leur place. Une image de la croix.","Genèse 3.6-7, 21"],["La substitution à la Pâque","En Égypte, partout où le sang de l'agneau était sur la porte, le jugement passait par-dessus. Dieu pouvait dire : « Le jugement est déjà passé ici. »","Exode 12.12-13"],["Christ, notre substitut","Jésus a porté nos péchés : le juste pour les injustes, afin de nous amener à Dieu. Il est devenu malédiction pour nous, pour que nous devenions justice de Dieu en lui.","Ésaïe 53.4-6 ; 2 Corinthiens 5.21 ; 1 Pierre 3.18"],["Sauvé par son amour, non par mérite","C'est Dieu qui attire, qui justifie, qui sauve. Le résultat : un cœur reconnaissant, et une force face à l'accusateur qui veut me faire douter de mon salut.","Jean 6.37, 44 ; Tite 3.3-8"],["Religion ou christianisme ?","La religion dit : « Fais quelque chose pour devenir acceptable. » Le vrai christianisme dit : « Christ a tout fait à ta place. » Il n'y a qu'un seul chemin, un seul nom.","Jean 14.6 ; Actes 4.12"]],"schema":{"type":"table","titre":"Le schéma à retenir : l'amende pour excès de vitesse","head":["Ce qui arrive","Comment on l'appelle"],"rows":[["Vous n'êtes pas pris","La chance"],["Vous êtes pris et payez l'amende","La justice"],["Vous êtes pris, mais pas d'amende","La miséricorde"],["Vous êtes pris, l'amende est donnée… et l'agent la paie","La grâce"]]},"table":{"titre":"Avant et après « Mais Dieu » (Éphésiens 2)","head":["Ce que j'étais","Ce que Dieu a fait"],"rows":[["Mort dans mes fautes","Rendu vivant avec Christ"],["Sans espérance et sans Dieu","Réconcilié avec Dieu"],["Enfant de colère","Sauvé par la grâce, par la foi"]]},"piege":[["Mes bonnes œuvres ajoutent quelque chose à mon salut.","Le salut est un don de Dieu, « non pas sur le principe des œuvres » (Éphésiens 2.9)."],["Si je ne me sens pas sauvé, je ne le suis peut-être pas.","Mon salut repose sur l'œuvre de Christ, non sur mes sentiments."]],"astuce":"Coupe Éphésiens 2.8-9 en trois morceaux : « sauvés par la grâce » / « par la foi » / « non pas par les œuvres ». Apprends un morceau par jour.","jesus":"Sachant que le Père avait tout remis entre ses mains, il s'est agenouillé pour laver les pieds de ses disciples (Jean 13.3-5), puis il a porté nos péchés (Ésaïe 53.5-6).","royaume":"La nouvelle naissance est l'entrée dans le Royaume (Jean 3.3, 5). Ma citoyenneté est restaurée : je suis de nouveau en règle avec le gouvernement du Roi.","mediter":"Celui à qui on a beaucoup pardonné aime beaucoup (Luc 7.47). Ai-je envers les autres la miséricorde que Dieu a eue envers moi ?","mots":[["Grâce","Recevoir ce que je ne mérite pas."],["Miséricorde","Ne pas recevoir ce que je mérite."],["Substitution","Un innocent prend la place du coupable : Christ à ma place."],["Justifié","Déclaré juste devant Dieu, grâce à Christ."]]},"wb":{"but":"Comprendre ce qui m'est arrivé à la conversion, et reposer sur l'œuvre de Christ, non sur ce que je ressens.","ref":"Éphésiens 2.8-9","verse":"Car vous êtes sauvés par la grâce, par la foi, et cela ne vient pas de vous, c’est le don de Dieu; non pas sur le principe des œuvres, afin que personne ne se glorifie.","q":["Quelle est la différence entre la miséricorde et la grâce ?","Comment Éphésiens 2 décrit-il ma situation avant de connaître Christ ?","Raconte l'illustration de l'amende pour excès de vitesse. Que montre-t-elle ?","Donne les trois exemples de substitution vus dans la leçon (Éden, la Pâque, la croix).","Quelle est la différence entre la religion et le christianisme ?","Pourquoi mon salut dépend-il de Dieu du début à la fin ? Quelle assurance cela me donne-t-il ?"],"vf":["Mes bonnes œuvres ajoutent quelque chose à mon salut.","La grâce, c'est recevoir ce que je ne mérite pas.","Il existe plusieurs chemins pour aller à Dieu.","Je peux savoir maintenant que j'ai la vie éternelle."],"vfKey":[false,true,false,true],"ex":[{"k":"C1","q":"Écris ton témoignage en trois paragraphes : ma vie avant Christ, comment je l'ai rencontré, ce qui a changé.","type":"text","rows":12},{"k":"C2","q":"Complète : « La religion dit … ; l'Évangile dit … ». Puis écris la phrase la plus juste pour l'expliquer à un ami.","type":"text","rows":4}],"d":["Mes 15 minutes avec Dieu","Faire grâce à quelqu'un, sans le dire à personne","Remercier Dieu par écrit pour la croix","Raconter mon témoignage à une personne","Je répète mon verset"],"j":"Qu'est-ce qui me fait encore douter de mon salut, et que me répond la Parole ?","go":"Ton salut ne dépend pas de tes sentiments : il repose sur l'œuvre parfaite de Christ. Tu es en sécurité."},"quiz":[{"type":"tf","q":"Mes bonnes œuvres ajoutent quelque chose à mon salut.","a":false},{"type":"tf","q":"La grâce, c'est recevoir ce que je ne mérite pas.","a":true},{"type":"tf","q":"Il existe plusieurs chemins pour aller à Dieu.","a":false},{"type":"tf","q":"Je peux savoir maintenant que j'ai la vie éternelle.","a":true},{"type":"mcq","q":"Quel mot correspond à cette définition ? « Recevoir ce que je ne mérite pas. »","opts":["Comme","Âme","Vase utilisable","Grâce"],"a":3},{"type":"mcq","q":"Quel mot correspond à cette définition ? « Ne pas recevoir ce que je mérite. »","opts":["Miséricorde","Vase utilisable","Nature humaine","Mentor"],"a":0},{"type":"mcq","q":"Quel mot correspond à cette définition ? « Un innocent prend la place du coupable : Christ à ma place. »","opts":["Comptes courts","Second Adam","Substitution","Manipulation du comportement"],"a":2},{"type":"mcq","q":"Quelle est la référence du verset de la semaine : « Car vous êtes sauvés par la grâce, par la foi, et cela ne vient pas de vous, c’est le don de Dieu; non pas sur… »","opts":["Galates 5.16","Matthieu 11.28-30","1 Jean 2.28","Éphésiens 2.8-9"],"a":3},{"type":"tf","q":"Mes bonnes œuvres ajoutent quelque chose à mon salut.","a":false,"why":"Le salut est un don de Dieu, « non pas sur le principe des œuvres » (Éphésiens 2.9)."},{"type":"tf","q":"Si je ne me sens pas sauvé, je ne le suis peut-être pas.","a":false,"why":"Mon salut repose sur l'œuvre de Christ, non sur mes sentiments."}]},{"n":"1-4","ph":1,"etape":"Étape 1 · Les fondements","t":"L'anatomie spirituelle","fil":"Comment Dieu m'a fait","hook":"Tu as un corps, une âme… et quoi d'autre que l'animal n'a pas ?","lire":"Genèse 2.7 ; 1 Thessaloniciens 5.23","sup":{"phrase":"Dieu a fait l'être humain esprit, âme et corps ; lui seul a reçu un esprit, par lequel il peut connaître Dieu.","dec":["Ce qui fait de l'être humain une création unique.","Le rôle de l'esprit, de l'âme et du corps.","Ce qui distingue l'homme de l'animal."],"pts":[["Une création unique","Dieu a formé l'homme de la poussière et a soufflé en lui une respiration de vie. C'est dans l'homme seul que Dieu a soufflé.","Genèse 2.7"],["L'esprit : la conscience de Dieu","C'est par mon esprit que je suis en relation avec Dieu. C'est le lieu de la communion avec lui.","Jean 4.24"],["L'âme : la conscience de soi","Ma personnalité, mon raisonnement, mes émotions, ma pensée, ma volonté.",""],["Le corps : la conscience du monde","Par les sens de mon corps, je suis en relation avec le monde physique.",""],["Dieu veut garder mon être tout entier","Paul prie pour que notre esprit, notre âme et notre corps soient conservés sans reproche. Rien de moi n'est indifférent à Dieu.","1 Thessaloniciens 5.23"],["Le règne animal : une âme et un corps","Dieu a créé les animaux et il en prend soin. Ils ont un corps et une âme (instinct, émotions, à des degrés variables), mais pas d'esprit.","Genèse 1.20-25 ; Matthieu 6.26"]],"schema":{"type":"table","titre":"Le schéma à retenir : trois dimensions d'une même personne","head":["","Ce que c'est","Ce que cela me permet"],"rows":[["L'esprit","La conscience de Dieu","Être en relation avec Dieu"],["L'âme","La conscience de soi","Penser, sentir, vouloir"],["Le corps","La conscience du monde","Agir dans le monde par mes sens"]]},"table":{"titre":"L'être humain et l'animal","head":["","L'être humain","L'animal"],"rows":[["Esprit","Oui : il peut connaître Dieu","Non"],["Âme","Personnalité, raison, émotions, volonté","Instinct, émotions, à des degrés variables"],["Corps","Relation au monde par les sens","Relation au monde par les sens"]]},"piege":[["Dieu ne s'intéresse qu'à mon esprit.","Dieu veut garder « l'esprit, l'âme et le corps » tout entiers (1 Thessaloniciens 5.23)."]],"astuce":"Récite 1 Thessaloniciens 5.23 en touchant ton cœur (l'esprit), ta tête (l'âme) et tes mains (le corps).","jesus":"Jésus avançait en sagesse et en stature, et en faveur auprès de Dieu (Luc 2.52). À la fin, il a remis son esprit entre les mains du Père (Luc 23.46).","royaume":"L'homme est un esprit, il a une âme et il habite un corps. Le corps lui permet d'agir sur la terre : je le présente au Roi en sacrifice vivant (Romains 12.1).","mediter":"Si mon esprit n'est pas nourri, tout le reste se dérègle. Qu'est-ce que je nourris le plus : mon corps, ma tête, ou mon esprit ?","mots":[["Esprit","La partie de moi par laquelle je connais Dieu."],["Âme","Ma personnalité : pensée, émotions, volonté."],["Corps","Ma relation avec le monde physique, par mes sens."]]},"wb":{"but":"Comprendre comment Dieu m'a fait, esprit, âme et corps, et où il agit en moi.","ref":"1 Thessaloniciens 5.23","verse":"Or le Dieu de paix lui-même vous sanctifie entièrement; et que votre esprit, et votre âme, et votre corps tout entiers, soient conservés sans reproche en la venue de notre seigneur Jésus Christ.","q":["Qu'est-ce qui fait de l'être humain une création unique (Genèse 2.7) ?","À quoi correspond chacune des trois parties : l'esprit, l'âme, le corps ?","Qu'est-ce qui distingue l'être humain de l'animal ?","Que demande Paul pour notre être entier en 1 Thessaloniciens 5.23 ?","Par quelle partie de mon être suis-je en relation avec Dieu ?"],"vf":["L'âme est la conscience du monde.","Les animaux ont une âme et un corps, mais pas d'esprit.","Dieu s'intéresse seulement à mon esprit, pas à mon corps.","L'esprit est la partie de moi qui connaît Dieu."],"vfKey":[false,true,false,true],"ex":[{"k":"C1","q":"Dessine trois cercles (esprit, âme, corps). Dans chacun, écris ce que tu as nourri cette semaine et ce que tu as négligé.","type":"text","rows":6,"hint":"En ligne : décris ou résume ton schéma avec tes mots (tu peux aussi le dessiner sur papier et le montrer à ton mentor)."},{"k":"C2","q":"Pour chaque partie, écris une chose concrète à présenter à Dieu cette semaine.","type":"text","rows":4}],"d":["Mes 15 minutes avec Dieu","Présenter à Dieu mon esprit, mon âme et mon corps","Prier pour mon esprit avant chaque repas","La Parole et la prière avant le téléphone","Je répète mon verset"],"j":"Quelle partie de mon être ai-je le plus négligée, et que vais-je changer ?","go":"Dieu veut ton être tout entier, et il en prend soin tout entier. Rien de toi ne lui est indifférent."},"quiz":[{"type":"tf","q":"L'âme est la conscience du monde.","a":false},{"type":"tf","q":"Les animaux ont une âme et un corps, mais pas d'esprit.","a":true},{"type":"tf","q":"Dieu s'intéresse seulement à mon esprit, pas à mon corps.","a":false},{"type":"tf","q":"L'esprit est la partie de moi qui connaît Dieu.","a":true},{"type":"mcq","q":"Quel mot correspond à cette définition ? « La partie de moi par laquelle je connais Dieu. »","opts":["Désert spirituel","Obéissance partielle","Problème de conduite","Esprit"],"a":3},{"type":"mcq","q":"Quel mot correspond à cette définition ? « Ma personnalité : pensée, émotions, volonté. »","opts":["Âme","Sarment","Vision du monde","Discipulat"],"a":0},{"type":"mcq","q":"Quel mot correspond à cette définition ? « Ma relation avec le monde physique, par mes sens. »","opts":["Obéissance partielle","Groupe cible","Corps","Faciliter"],"a":2},{"type":"mcq","q":"Quelle est la référence du verset de la semaine : « Or le Dieu de paix lui-même vous sanctifie entièrement; et que votre esprit, et votre âme, et votre corps tout… »","opts":["1 Thessaloniciens 5.23","Matthieu 11.28-30","2 Pierre 3.18","2 Corinthiens 3.18"],"a":0},{"type":"tf","q":"Dieu ne s'intéresse qu'à mon esprit.","a":false,"why":"Dieu veut garder « l'esprit, l'âme et le corps » tout entiers (1 Thessaloniciens 5.23)."}]},{"n":"1-5","ph":1,"etape":"Étape 2 · La vie nouvelle","t":"Nature divine et nature humaine","fil":"D'où viennent mes deux natures","hook":"Quel mensonge Satan murmure-t-il depuis le jardin d'Éden ?","lire":"Genèse 3.1-7 ; Luc 4.1-13","sup":{"phrase":"Si Dieu est tel que la Bible le décrit, il est parfaitement logique de lui faire confiance ; le problème de l'humanité, depuis Adam, c'est le choix de l'indépendance.","dec":["Six traits du caractère de Dieu qui rendent la confiance logique.","La stratégie de Satan, et le choix d'Adam et Ève.","Jésus, le second Adam, et la nature divine que j'ai reçue."],"pts":[["Le caractère de Dieu","Dieu est amour, souverain, juste et saint (il ne peut mentir ni mal faire), parfait, immuable, fidèle. Le but de ces versets : montrer combien il est raisonnable de lui faire confiance. Je me méfie souvent de Dieu parce que je lui prête mon propre caractère.","1 Jean 4.16 ; Deutéronome 32.4 ; 2 Timothée 2.13"],["La stratégie de Satan","Miner ma confiance dans le caractère de Dieu. En Éden, il a insinué que Dieu ment, qu'il ne veut pas leur bien, qu'il les prive de quelque chose de bon.","Genèse 3.1-5 ; Jean 8.44"],["Le choix de l'indépendance","Adam et Ève ont cru le mensonge et cherché leur satisfaction sans Dieu, dans trois domaines : l'intelligence (« désirable pour rendre intelligent »), le corps (« bon à manger »), les possessions (« un plaisir pour les yeux »). C'est le problème racine de l'humanité.","Genèse 3.6"],["Une nature transmise à tous","Tout être humain hérite de la nature pécheresse d'Adam : il naît avec une disposition à résister à Dieu.","Romains 5.12 ; Galates 5.17"],["Jésus, le second Adam","Né sans père humain pécheur, Jésus avait la nature humaine sans péché qu'Adam avait avant la chute. Tenté dans les trois mêmes domaines, il a choisi de dépendre de Dieu : « Il est écrit ».","1 Corinthiens 15.45 ; Luc 4.1-12"],["Ce que j'ai reçu en croyant","Je suis né dans une race nouvelle : j'ai reçu la nature divine, le Saint-Esprit. Mais la vieille nature ne s'améliore jamais : la victoire, c'est de marcher par l'Esprit.","Jean 3.6 ; Galates 5.16-23"]],"schema":{"type":"table","titre":"Le schéma à retenir : deux Adam, deux choix","head":["Domaine","Adam et Ève (Genèse 3.6)","Jésus (Luc 4.1-12)"],"rows":[["L'intelligence","« Désirable pour rendre intelligent »","Se jeter du haut du temple"],["Le corps","« Bon à manger »","Changer la pierre en pain"],["Les possessions","« Un plaisir pour les yeux »","Tous les royaumes du monde"],["Le choix","L'indépendance","La dépendance : « Il est écrit »"]]},"table":null,"piege":[["Après la conversion, ma vieille nature s'améliore peu à peu.","La nature humaine ne s'améliore jamais ; Dieu m'a donné une nature nouvelle."],["Le croyant n'a plus de lutte intérieure.","« La chair convoite contre l'Esprit » (Galates 5.17) : la lutte existe, mais l'Esprit est plus fort."]],"astuce":"Chaque fois que tu penses « je me débrouille seul », récite Galates 5.16.","jesus":"Adam a choisi l'indépendance dans un jardin où il avait tout. Jésus a choisi la dépendance dans un désert où il n'avait rien : « Il est écrit » (Luc 4.4, 8, 12).","royaume":"La chute fut une déclaration d'indépendance : l'homme a perdu un Royaume, pas une religion. Le Roi est bon : on peut se soumettre à lui sans crainte (Matthieu 6.33).","mediter":"Quel trait du caractère de Dieu ai-je le plus de mal à croire quand la vie fait mal ?","mots":[["Nature humaine","La nature héritée d'Adam, tournée vers l'indépendance ; on l'appelle aussi « la chair »."],["Nature divine","La vie de Dieu en moi, en la Personne du Saint-Esprit."],["Second Adam","Jésus, qui a vécu la vie humaine que Dieu avait voulue pour Adam."]]},"wb":{"but":"Comprendre pourquoi, comme croyant, j'ai deux natures, et pourquoi il est logique de faire confiance à Dieu.","ref":"Galates 5.16","verse":"Marchez par l’Esprit, et vous n’accomplirez point la convoitise de la chair.","q":["Cite quatre traits du caractère de Dieu qui rendent logique de lui faire confiance.","Comment le serpent a-t-il attaqué la confiance d'Ève en Dieu (Genèse 3) ?","Dans quels trois domaines Adam et Ève ont-ils choisi l'indépendance ?","Comment le péché et la mort sont-ils passés à tous les hommes (Romains 5.12) ?","En quoi Jésus, le dernier Adam, a-t-il fait le choix inverse d'Adam ? Que montre sa tentation au désert ?","Qu'ai-je reçu en croyant, et que devient ma vieille nature ?"],"vf":["Après la conversion, la vieille nature s'améliore peu à peu.","Satan attaque d'abord le caractère de Dieu pour miner ma confiance.","Jésus a résisté à la tentation en répondant par la Parole : « Il est écrit ».","Le croyant n'a plus aucune lutte intérieure."],"vfKey":[false,true,true,false],"ex":[{"k":"C1","q":"Trace deux colonnes : « le premier Adam » et « le dernier Adam ». Compare leurs choix et leurs résultats.","type":"table","cols":["Le premier Adam","Le dernier Adam"],"rows":5},{"k":"C2","q":"Note une situation de la semaine où tu as agi « indépendamment » de Dieu. Qu'aurait changé la confiance ?","type":"text","rows":5}],"d":["Mes 15 minutes avec Dieu","Lire un groupe de versets sur le caractère de Dieu","Noter chaque « je me débrouille seul »","Répondre à une tentation par « Il est écrit »","Je répète mon verset"],"j":"Dans quel domaine ai-je le plus de mal à faire confiance à Dieu, et pourquoi ?","go":"Tu as en toi la nature divine. La victoire n'est pas d'améliorer l'ancien, mais de marcher par l'Esprit."},"quiz":[{"type":"tf","q":"Après la conversion, la vieille nature s'améliore peu à peu.","a":false},{"type":"tf","q":"Satan attaque d'abord le caractère de Dieu pour miner ma confiance.","a":true},{"type":"tf","q":"Jésus a résisté à la tentation en répondant par la Parole : « Il est écrit ».","a":true},{"type":"tf","q":"Le croyant n'a plus aucune lutte intérieure.","a":false},{"type":"mcq","q":"Quel mot correspond à cette définition ? « La nature héritée d'Adam, tournée vers l'indépendance ; on l'appelle aussi « la chair ». »","opts":["Abandon","Discipulat","Épreuve","Nature humaine"],"a":3},{"type":"mcq","q":"Quel mot correspond à cette définition ? « La vie de Dieu en moi, en la Personne du Saint-Esprit. »","opts":["Nature divine","Terre promise","Tribunal de Christ","Matériaux"],"a":0},{"type":"mcq","q":"Quel mot correspond à cette définition ? « Jésus, qui a vécu la vie humaine que Dieu avait voulue pour Adam. »","opts":["Second Adam","Vallée d'Acor","Fruit","Seigneurie"],"a":0},{"type":"mcq","q":"Quelle est la référence du verset de la semaine : « Marchez par l’Esprit, et vous n’accomplirez point la convoitise de la chair. »","opts":["1 Thessaloniciens 5.23","Galates 5.16","Jean 15.4","Jean 15.8"],"a":1},{"type":"tf","q":"Après la conversion, ma vieille nature s'améliore peu à peu.","a":false,"why":"La nature humaine ne s'améliore jamais ; Dieu m'a donné une nature nouvelle."},{"type":"tf","q":"Le croyant n'a plus de lutte intérieure.","a":false,"why":"« La chair convoite contre l'Esprit » (Galates 5.17) : la lutte existe, mais l'Esprit est plus fort."}]},{"n":"1-6","ph":1,"etape":"Étape 2 · La vie nouvelle","t":"Ma relation avec le Saint-Esprit","fil":"Dieu lui-même vit en moi","hook":"Le Saint-Esprit : une force que tu « branches »… ou une Personne qui peut être attristée ?","lire":"Jean 14.16-17 ; Éphésiens 4.30","sup":{"phrase":"Le Saint-Esprit n'est pas une force ni une inspiration : c'est une Personne, Dieu lui-même, qui vit en moi et a un plan pour chacune de mes journées.","dec":["Neuf vérités sur le Saint-Esprit et moi.","Ce que veut dire être son temple et porter son sceau.","Pourquoi il me donne des dons."],"pts":[["Une Personne, Dieu lui-même","On peut lui mentir, l'attrister, avoir communion avec lui : on ne fait pas cela avec une force. Ma relation avec lui ressemble à celle d'un bon mariage : respect, communication, soin.","Actes 5.3-4 ; Éphésiens 4.30"],["Il vit en moi, son temple ; il me possède","Sa propriété sur moi est un fait, que je le croie ou non. Je ne la lui accorde pas : je la reconnais.","1 Corinthiens 3.16 ; 6.19-20"],["Le sceau de mon adoption","Il est la garantie, la preuve que je suis enfant de Dieu. Comme disciple, je deviens de plus en plus dépendant de lui, et de moins en moins de mon mentor.","Romains 8.14-16 ; Éphésiens 1.13-14"],["Un plan pour chaque jour","Il ne suit pas mon plan : il veut que je suive le sien. Je peux faire des projets, en sachant qu'il peut les changer.","Psaume 139.16 ; Jean 14.16-17"],["Il prie pour moi et m'apprend à prier","Quand je ne sais pas quoi demander, l'Esprit intercède pour moi.","Romains 8.26-27 ; Jude 20"],["Baptisé dans le corps de Christ","Il m'a uni à tous les vrais croyants. Le baptême d'eau, lui, est le témoignage extérieur de ce que Dieu a déjà fait à l'intérieur.","1 Corinthiens 12.13 ; Matthieu 28.19"],["Témoigner, servir, porter du fruit","Il veut témoigner de Jésus par mes paroles et ma vie ; il me donne des dons pour servir les autres, et non pour me mettre en valeur. Lui seul produit la vie spirituelle : tout ce qui a une valeur éternelle vient de lui.","Actes 1.8 ; 1 Corinthiens 12.4-7 ; Jean 6.63"]],"schema":{"type":"grid","titre":"Le schéma à retenir : neuf vérités sur le Saint-Esprit","items":["Une Personne, Dieu lui-même","Il vit en moi, son temple","Le sceau : je suis enfant de Dieu","Un plan pour chaque jour","Il prie pour moi","Baptisé dans le corps de Christ","Témoigner de Jésus","Des dons pour les autres","Lui seul produit la vie"]},"table":null,"piege":[["Le Saint-Esprit vient et repart selon ma conduite.","Il est le sceau : il demeure en moi éternellement (Jean 14.16)."],["Mes dons servent à me mettre en valeur.","Chaque membre sert le corps, et non le corps chaque membre."]],"astuce":"Lis 1 Corinthiens 6.19-20 devant un miroir : « Mon corps est son temple. Je ne suis pas à moi-même. »","jesus":"Jésus était plein de l'Esprit, mené par l'Esprit, et agissait dans la puissance de l'Esprit (Luc 4.1, 14, 18). Le même Esprit habite en nous (Romains 8.11).","royaume":"Le Saint-Esprit est comme le gouverneur du Royaume : il apporte sur la terre la culture du ciel. Le Royaume est « justice, paix et joie dans l'Esprit Saint » (Romains 14.17).","mediter":"Est-ce que je traite le Saint-Esprit comme une Personne qui m'aime, ou comme une force dont je me sers ?","mots":[["Temple","Le lieu où Dieu habite : mon corps de croyant."],["Sceau","La marque, la garantie que j'appartiens à Dieu."],["Don spirituel","Une capacité donnée par l'Esprit pour servir les autres."]]},"wb":{"but":"Connaître le Saint-Esprit comme une Personne qui vit en moi, et apprendre à le suivre chaque jour.","ref":"1 Corinthiens 6.19-20","verse":"Ne savez-vous pas que votre corps est le temple du Saint Esprit qui est en vous, et que vous avez de Dieu? Et vous n’êtes pas à vous-mêmes; car vous avez été achetés à prix. Glorifiez donc Dieu dans votre corps.","q":["Pourquoi est-il important de savoir que le Saint-Esprit est une Personne, et non une force ?","Que signifie être « le temple » du Saint-Esprit ? Qui me possède ?","Que veut dire que le Saint-Esprit est un « sceau » ?","Que fait le Saint-Esprit quand je ne sais pas comment prier ?","Quelle est la différence entre le baptême du Saint-Esprit dans le corps de Christ et le baptême d'eau ?","Pourquoi le Saint-Esprit me donne-t-il des dons ?"],"vf":["Le Saint-Esprit vient et repart selon ma conduite.","Lui seul peut produire la vie spirituelle.","Le baptême d'eau est un témoignage extérieur de ce qui s'est passé à l'intérieur.","Mes dons spirituels servent d'abord à me mettre en valeur."],"vfKey":[false,true,true,false],"ex":[{"k":"C1","q":"Pour trois des neuf vérités sur le Saint-Esprit, écris : « Si je ne comprends pas cela, alors… ».","type":"text","rows":6},{"k":"C2","q":"Décris ta journée type. Pour chaque moment, écris où le Saint-Esprit pourrait vouloir te conduire.","type":"text","rows":6}],"d":["Mes 15 minutes avec Dieu","Le matin : « Saint-Esprit, quel est ton plan ? »","Noter une impulsion de l'Esprit à laquelle j'ai obéi","Parler de Jésus ou servir avec mon don","Je répète mon verset"],"j":"À quel moment de la semaine ai-je senti que le Saint-Esprit me conduisait ?","go":"Tu n'es jamais seul : Dieu lui-même habite en toi. Écoute-le, il a un plan pour chacune de tes journées."},"quiz":[{"type":"tf","q":"Le Saint-Esprit vient et repart selon ma conduite.","a":false},{"type":"tf","q":"Lui seul peut produire la vie spirituelle.","a":true},{"type":"tf","q":"Le baptême d'eau est un témoignage extérieur de ce qui s'est passé à l'intérieur.","a":true},{"type":"tf","q":"Mes dons spirituels servent d'abord à me mettre en valeur.","a":false},{"type":"mcq","q":"Quel mot correspond à cette définition ? « Le lieu où Dieu habite : mon corps de croyant. »","opts":["Volonté permissive","Problème de conduite","Question ouverte","Temple"],"a":3},{"type":"mcq","q":"Quel mot correspond à cette définition ? « La marque, la garantie que j'appartiens à Dieu. »","opts":["Désert spirituel","Reproduction spirituelle","Jourdain","Sceau"],"a":3},{"type":"mcq","q":"Quel mot correspond à cette définition ? « Une capacité donnée par l'Esprit pour servir les autres. »","opts":["Événement","Manipulation du comportement","Romains 7","Don spirituel"],"a":3},{"type":"mcq","q":"Quelle est la référence du verset de la semaine : « Ne savez-vous pas que votre corps est le temple du Saint Esprit qui est en vous, et que vous avez de Dieu? Et … »","opts":["Galates 5.16","1 Corinthiens 6.19-20","Galates 5.16","Galates 5.16"],"a":1},{"type":"tf","q":"Le Saint-Esprit vient et repart selon ma conduite.","a":false,"why":"Il est le sceau : il demeure en moi éternellement (Jean 14.16)."},{"type":"tf","q":"Mes dons servent à me mettre en valeur.","a":false,"why":"Chaque membre sert le corps, et non le corps chaque membre."}]},{"n":"1-7","ph":1,"etape":"Étape 2 · La vie nouvelle","t":"Seigneurie et abandon","fil":"La décision qui change tout","hook":"Jésus a les clés de ta maison… toutes, vraiment ?","lire":"Matthieu 11.28-30 ; Matthieu 6.19-33","sup":{"phrase":"L'abandon est une décision, puis un processus : je reconnais une fois pour toutes que Jésus me possède, puis je le laisse changer chaque jour ce qu'il veut.","dec":["Les deux décisions du chrétien normal : le salut, puis la seigneurie.","L'erreur de l'abandon « progressif ».","L'histoire de deux croyants et des pièces de leur maison."],"pts":[["Deux décisions, puis la croissance","La première décision est le salut ; la seconde, la seigneurie : reconnaître que Dieu seul est capable de diriger ma vie. Idéalement prise à la conversion, elle l'est souvent plus tard. Ensuite, ma manière de penser change peu à peu : c'est la sanctification.","Romains 12.1-2"],["La volonté d'abord, la conduite ensuite","J'abandonne d'abord ma volonté, une fois pour toutes ; ma conduite change ensuite, progressivement. Comme un cheval sauvage : d'abord briser sa volonté, puis le dresser. Comme la chenille qui devient papillon : la transformation vient de l'intérieur.",""],["L'erreur de l'abandon « progressif »","Sans décision de seigneurie, je vis un partenariat : « la part de Dieu » (le dimanche, la dîme) et « ce que je gère » (le reste). Je fixe les limites moi-même, et cela mène à la frustration et au découragement.",""],["La vraie question : Dieu est-il digne de confiance ?","Mes peurs : que va-t-il me demander, m'interdire, me prendre ? Si Dieu était comme moi, j'aurais raison d'avoir peur. Mais il m'aime, il m'a créé, il sait ce qui est bon pour moi. Jésus ne dit pas « apprenez à me connaître, puis prenez mon joug » : il dit « prenez mon joug, et apprenez ».","Matthieu 11.28-30"],["Un royaume, non une démocratie","Il m'a acheté à grand prix : je ne suis pas à moi-même. Je vis dans un royaume, où le Roi possède tout et prend soin de ce qui lui appartient.","1 Corinthiens 6.19-20"],["Les pièces de ma maison","Deux croyants ont reçu Jésus. Le premier l'a laissé dans la chambre d'amis et la pièce « spirituelle ». Le second a raisonné : « S'il me possède, comment lui refuser une seule pièce ? » Lui seul décide ensuite de ce qui doit changer.","Apocalypse 3.20"]],"schema":{"type":"table","titre":"Le schéma à retenir : deux maisons","head":["Les pièces","Salut seulement","Salut ET seigneurie"],"rows":[["Chambre d'amis, pièce « spirituelle »","Jésus y a accès","Jésus y a accès"],["Finances, famille, travail, loisirs","Fermées","Jésus y a accès"],["Corps, temps, relations, pensées","Fermées","Jésus y a accès"],["Le « placard » caché","Fermé à clé","Ouvert"]]},"table":null,"piege":[["En le reconnaissant Seigneur, je lui donne quelque chose qui m'appartient.","Tout lui appartient déjà : je reconnais simplement un fait."],["Je suis responsable de produire ma croissance.","C'est l'Esprit qui transforme ; ma part est de lui laisser l'accès."]],"astuce":"Matthieu 11.28-30 a trois verbes : « Venez », « Prenez », « Apprenez ». Retiens-les d'abord, le reste suivra.","jesus":"À Gethsémané : « Que ce ne soit pas ma volonté, mais la tienne, qui soit faite » (Luc 22.42). Il ne nous demande rien qu'il n'ait fait le premier (Jean 5.30).","royaume":"« Seigneur » veut dire propriétaire. Un royaume n'est pas une démocratie : le Roi possède tout, et il prend soin de ce qui lui appartient (Luc 6.46).","mediter":"Quelle pièce de ma maison est encore fermée ? Quelle peur me retient de l'ouvrir ?","mots":[["Seigneurie","Reconnaître que Jésus est le propriétaire et le Maître de toute ma vie."],["Abandon","Céder ma volonté à Dieu (décision), puis mes domaines de vie (processus)."],["Sanctification","Le processus par lequel Dieu change ma manière de penser et de vivre."],["Joug","La pièce de bois qui attelle deux bœufs : marcher avec Jésus, sous sa direction."]]},"wb":{"but":"Prendre la décision de reconnaître Jésus comme Seigneur de tout, puis vivre cet abandon chaque jour.","ref":"Matthieu 11.28-30","verse":"Venez à moi, vous tous qui vous fatiguez et qui êtes chargés, et moi, je vous donnerai du repos. Prenez mon joug sur vous, et apprenez de moi, car je suis débonnaire et humble de cœur; et vous trouverez le repos de vos âmes. Car mon joug est aisé et mon fardeau est léger.","q":["Pourquoi l'abandon est-il à la fois une décision et un processus ?","Qu'est-ce qui vient en premier : le changement de conduite ou l'abandon de la volonté ? Pourquoi ?","Que se passe-t-il dans la vie d'un croyant qui n'a pas pris la décision de seigneurie ?","Quelle est la vraie question derrière la peur de s'abandonner, et quelle est la réponse ?","Pourquoi dit-on que je vis dans un royaume, et non dans une démocratie ?","Explique l'image des pièces de la maison."],"vf":["En reconnaissant Jésus comme Seigneur, je lui donne quelque chose qui m'appartient.","Je suis responsable de produire ma propre croissance spirituelle.","Dieu ne profitera jamais de mon abandon pour me faire du mal.","Une fois la décision prise, il n'y a plus jamais rien à abandonner."],"vfKey":[false,false,true,false],"ex":[{"k":"C1","q":"Dessine ta « maison » : une pièce par domaine de ta vie (argent, temps, relations, travail, loisirs, pensées). Colorie celles que tu as ouvertes à Jésus.","type":"text","rows":6,"hint":"En ligne : décris ou résume ton schéma avec tes mots (tu peux aussi le dessiner sur papier et le montrer à ton mentor)."},{"k":"C2","q":"Écris la prière de seigneurie que tu es prêt à dire, avec tes propres mots.","type":"text","rows":7}],"d":["Mes 15 minutes avec Dieu","Ouvrir à Dieu chaque pièce, même le placard fermé","Lui dire qu'il est Seigneur de tout, et le dire à mon mentor","Lire Matthieu 6.19-33","Je répète mon verset"],"j":"Quelle pièce était la plus difficile à ouvrir, et qu'est-ce qui a changé depuis ?","go":"C'est la décision qui change tout. Son joug est aisé : ce que tu lui donnes, il le garde mieux que toi."},"quiz":[{"type":"tf","q":"En reconnaissant Jésus comme Seigneur, je lui donne quelque chose qui m'appartient.","a":false},{"type":"tf","q":"Je suis responsable de produire ma propre croissance spirituelle.","a":false},{"type":"tf","q":"Dieu ne profitera jamais de mon abandon pour me faire du mal.","a":true},{"type":"tf","q":"Une fois la décision prise, il n'y a plus jamais rien à abandonner.","a":false},{"type":"mcq","q":"Quel mot correspond à cette définition ? « Reconnaître que Jésus est le propriétaire et le Maître de toute ma vie. »","opts":["Émonder","Méthode passive","Sarment","Seigneurie"],"a":3},{"type":"mcq","q":"Quel mot correspond à cette définition ? « Céder ma volonté à Dieu (décision), puis mes domaines de vie (processus). »","opts":["Épreuve","Abandon","Droit de naissance","Fidèle"],"a":1},{"type":"mcq","q":"Quel mot correspond à cette définition ? « Le processus par lequel Dieu change ma manière de penser et de vivre. »","opts":["Photocopie","Perspective","Vieil homme","Sanctification"],"a":3},{"type":"mcq","q":"Quelle est la référence du verset de la semaine : « Venez à moi, vous tous qui vous fatiguez et qui êtes chargés, et moi, je vous donnerai du repos. Prenez mon jo… »","opts":["1 Jean 1.9","Jean 15.5","Matthieu 11.28-30","1 Jean 2.6"],"a":2},{"type":"tf","q":"En le reconnaissant Seigneur, je lui donne quelque chose qui m'appartient.","a":false,"why":"Tout lui appartient déjà : je reconnais simplement un fait."},{"type":"tf","q":"Je suis responsable de produire ma croissance.","a":false,"why":"C'est l'Esprit qui transforme ; ma part est de lui laisser l'accès."}]},{"n":"1-8","ph":1,"etape":"Étape 2 · La vie nouvelle","t":"Mes deux natures","fil":"Deux arbres, deux sources","hook":"Peut-on rendre douce une eau salée en y ajoutant du sucre ?","lire":"Romains 6.1-14 ; Galates 5.16-23","sup":{"phrase":"Ma vieille nature est toujours là, mais elle n'a plus de pouvoir sur moi : je n'ai pas à l'améliorer, je dois marcher par l'Esprit.","dec":["Trois portraits : Adam avant le péché, l'incroyant, le croyant.","Deux arbres et deux sources qui produisent selon leur nature.","Ce que veut dire « mort au péché »."],"pts":[["A : Adam avant le péché, et Jésus","Une nature humaine sans péché, totalement compatible avec Dieu. Jésus, le second Adam, a vécu ainsi sur la terre.","Genèse 1.27 ; 1 Corinthiens 15.45-49"],["B : l'incroyant","L'esprit est sans la vie de Dieu ; la nature corrompue l'enchaîne. Ce qu'il produit n'a pas de vie éternelle : Dieu n'accepte que ce qui est parfait.","Romains 3.23"],["C : moi, croyant","Le Saint-Esprit habite mon esprit. La vieille nature est encore là, mais la chaîne est brisée : elle est sans pouvoir. Tout ce qui n'est pas motivé par l'Esprit reste temporel (bois, foin, chaume).","Galates 4.6 ; 5.16"],["Deux arbres","L'arbre planté près des eaux, feuillage vert, fruit en sa saison : celui qui se confie en l'Éternel. L'arbuste dans le désert, en terre salée : celui qui se confie en l'homme.","Jérémie 17.5-8"],["Deux sources","Une source ne donne pas à la fois l'eau salée et l'eau douce. La nature humaine est une source salée ; l'Esprit, une source d'eau vive.","Jacques 3.9-12 ; Jean 7.37-39"],["Mort au péché","Mourir, c'est être séparé, non disparaître. Au salut, j'ai été séparé du pouvoir du péché, même s'il est encore présent. Je suis « affranchi du péché » : pourquoi y vivrais-je encore ?","Romains 6.6-7, 18, 22"]],"schema":{"type":"table","titre":"Le schéma à retenir : trois conditions spirituelles","head":["","A. Adam avant le péché ; Jésus","B. L'incroyant","C. Le croyant"],"rows":[["L'esprit","En relation avec Dieu","Sans la vie de Dieu","Le Saint-Esprit y habite"],["La nature humaine","Sans péché","Corrompue ; elle enchaîne","Présente, mais sans pouvoir"],["Le fruit","Agréable à Dieu","Sans vie éternelle","Éternel si l'Esprit le produit"]]},"table":null,"piege":[["Avec des efforts, ma vieille nature produira du bon fruit.","Un arbre mauvais ne peut pas porter de bons fruits : seul l'Esprit produit le fruit."],["« Mort au péché » veut dire que je ne pèche plus jamais.","C'est être séparé du pouvoir du péché, non de sa présence."]],"astuce":"Galates 5.22-23 contient neuf fruits : compte-les sur tes doigts en les récitant.","jesus":"Jésus est une vie humaine en parfaite harmonie avec Dieu : tenté en toutes choses comme nous, à part le péché (Hébreux 4.15). Il est le modèle, et par son Esprit, la puissance.","royaume":"Dieu nous a délivrés du pouvoir des ténèbres et transportés dans le royaume du Fils de son amour (Colossiens 1.13) : un nouveau pays, une nouvelle culture à apprendre.","mediter":"Si la chaîne est brisée, pourquoi est-ce que je retourne parfois vers le vieil arbre ?","mots":[["Chair","Ma nature humaine, quand elle agit sans Dieu."],["Fruit de l'Esprit","Le caractère de Jésus que l'Esprit produit en moi (Galates 5.22-23)."],["Affranchi","Libéré de l'esclavage."]]},"wb":{"but":"Comprendre comment mes deux natures agissent, et apprendre à marcher par l'Esprit plutôt qu'à améliorer la chair.","ref":"Galates 5.22-23","verse":"Mais le fruit de l’Esprit est l’amour, la joie, la paix, la longanimité, la bienveillance, la bonté, la fidélité, la douceur, la tempérance: contre de telles choses, il n’y a pas de loi.","q":["Décris les trois personnages du schéma : A (Adam avant le péché, et Jésus), B (l'incroyant), C (le croyant).","Que produit la vieille nature, même quand elle paraît bonne ?","Explique les images des deux arbres et des deux sources.","Que veut dire « je suis mort au péché », alors que le péché est encore présent ?","Selon Galates 5.16, comment ne pas accomplir la convoitise de la chair ?"],"vf":["Avec des efforts, ma vieille nature finira par produire du bon fruit.","Le croyant est séparé du pouvoir du péché, même si le péché est encore présent.","Le fruit de l'Esprit est le résultat de ma bonne volonté.","Une source ne peut pas donner à la fois de l'eau salée et de l'eau douce."],"vfKey":[false,true,false,true],"ex":[{"k":"C1","q":"Trace deux colonnes : « œuvres de la chair » (Galates 5.19-21) et « fruit de l'Esprit » (5.22-23). Entoure ce que tu as vu dans ta vie cette semaine.","type":"table","cols":["Œuvres de la chair","Fruit de l'Esprit"],"rows":5},{"k":"C2","q":"Choisis une œuvre de la chair qui revient souvent. Écris ce que tu diras au Saint-Esprit la prochaine fois.","type":"text","rows":4}],"d":["Mes 15 minutes avec Dieu","« C'est l'ancien arbre. Saint-Esprit, je te cède. »","Compter le soir combien de fois je l'ai fait","Lire Romains 6","Je répète mon verset"],"j":"Quel fruit de l'Esprit ai-je vu grandir en moi cette semaine ?","go":"Tu n'as pas à fabriquer le fruit : l'Esprit le produit. Ta part, c'est de lui céder, encore et encore."},"quiz":[{"type":"tf","q":"Avec des efforts, ma vieille nature finira par produire du bon fruit.","a":false},{"type":"tf","q":"Le croyant est séparé du pouvoir du péché, même si le péché est encore présent.","a":true},{"type":"tf","q":"Le fruit de l'Esprit est le résultat de ma bonne volonté.","a":false},{"type":"tf","q":"Une source ne peut pas donner à la fois de l'eau salée et de l'eau douce.","a":true},{"type":"mcq","q":"Quel mot correspond à cette définition ? « Ma nature humaine, quand elle agit sans Dieu. »","opts":["Nature divine","Chair","Fondement","Être / faire"],"a":1},{"type":"mcq","q":"Quel mot correspond à cette définition ? « Le caractère de Jésus que l'Esprit produit en moi (Galates 5.22-23). »","opts":["Fruit","Fidèle","Interdit","Fruit de l'Esprit"],"a":3},{"type":"mcq","q":"Quel mot correspond à cette définition ? « Libéré de l'esclavage. »","opts":["Demeurer","Romains 8","Être / faire","Affranchi"],"a":3},{"type":"mcq","q":"Quelle est la référence du verset de la semaine : « Mais le fruit de l’Esprit est l’amour, la joie, la paix, la longanimité, la bienveillance, la bonté, la fidéli… »","opts":["Galates 5.16","Galates 5.22-23","1 Samuel 15.22","Jean 15.4"],"a":1},{"type":"tf","q":"Avec des efforts, ma vieille nature produira du bon fruit.","a":false,"why":"Un arbre mauvais ne peut pas porter de bons fruits : seul l'Esprit produit le fruit."},{"type":"tf","q":"« Mort au péché » veut dire que je ne pèche plus jamais.","a":false,"why":"C'est être séparé du pouvoir du péché, non de sa présence."}]},{"n":"1-9","ph":1,"etape":"Étape 3 · Demeurer","t":"Demeurer","fil":"Le secret de la vie chrétienne","hook":"Pourquoi ta batterie spirituelle se vide-t-elle si vite ?","lire":"Jean 15.1-11 ; 1 Jean 1.5-9","sup":{"phrase":"Demeurer, c'est marcher instant après instant en harmonie avec le Saint-Esprit, sans rien de non réglé entre lui et moi.","dec":["Pourquoi demeurer est si important : être, plutôt que faire.","Les trois dimensions : largeur, hauteur, profondeur.","Les symptômes qui montrent que je ne demeure pas, et cinq idées fausses."],"pts":[["Une relation conditionnelle","Le Saint-Esprit ne change pas. Mais moi, je peux choisir à tout moment de laisser une offense non réglée se placer entre lui et moi. Quand je demeure, ce que l'Esprit fait à travers moi est éternel ; quand je ne demeure pas, c'est temporel.","1 Corinthiens 3.10-15"],["Être, avant de faire","Dieu cherche des vases disponibles. La fonction d'un vase est d'être utilisable par son propriétaire, non d'agir de lui-même. Ce que je fais est le résultat de ce que je suis. Pense à ta relation avec ton conjoint ou un ami proche : c'est le modèle que Dieu nous donne.","Jean 15.5 ; Romains 6.13"],["La largeur : aujourd'hui","Ma communion avec Dieu ne couvre qu'aujourd'hui. Hier doit être réglé ; demain, sa grâce y pourvoira. Je tiens des « comptes courts » : je confesse vite. Prévoir l'avenir est sage ; m'inquiéter peut devenir un péché.","Luc 9.23 ; Éphésiens 4.26-27"],["La hauteur : instant après instant","Une ligne ouverte entre Dieu et moi, 24 h sur 24. « Priez sans cesse » : comme une toux persistante, la prière reprend chaque fois que possible. Attention au piège de l'activité : la négligence dit « tu n'es pas important ».","1 Thessaloniciens 5.16-18"],["La profondeur : une relation qui grandit","Comme un rayon de lumière révèle la poussière, Dieu me montre peu à peu ce qui lui déplaît, et il ne me tient responsable que de ce qu'il me montre aujourd'hui. Il m'émonde pour que je porte plus de fruit : mes « bonnes » choses ne doivent pas me voler son « meilleur ».","Jean 15.2 ; Psaume 103.14"],["Comment savoir si je ne demeure pas ?","Je demande au Saint-Esprit s'il y a quelque chose de non réglé. Je repère les symptômes : colère, impatience, absence de paix, inquiétude, plainte, critique, sentiment de défaite… La communion revient immédiatement dès que je confesse.","1 Jean 1.9"],["Cinq idées fausses","Je peux demeurer par mes efforts ; éviter le péché est le but principal ; demeurer est un niveau à atteindre ; mes limites m'empêchent de demeurer ; il suffit de suivre ma liste de choses à faire. En réalité, demeurer est le droit de naissance de tout enfant de Dieu.","2 Pierre 1.3"]],"schema":{"type":"grid","titre":"Le schéma à retenir : les trois dimensions","cols":3,"items":[["Largeur","Aujourd'hui : des comptes courts"],["Hauteur","Instant après instant : prier sans cesse"],["Profondeur","Une relation qui grandit : Dieu m'émonde"]]},"table":null,"piege":[["Quand Dieu m'émonde, c'est qu'il est fâché contre moi.","Il émonde le sarment qui porte du fruit, « afin qu'il porte plus de fruit » (Jean 15.2)."],["Lire la Bible est toujours une bonne chose.","Si je lis pendant qu'un enfant se noie devant moi… Ce qui plaît à Dieu se discerne instant après instant."]],"astuce":"Jean 15.5 : dessine un cep et un sarment sur ta carte, et écris le verset le long du sarment.","jesus":"Le Fils ne peut rien faire de lui-même, sinon ce qu'il voit faire au Père (Jean 5.19). Il demeurait dans l'amour de son Père, et nous invite à demeurer dans le sien (Jean 15.9-10).","royaume":"« Cherchez premièrement le royaume de Dieu et sa justice » (Matthieu 6.33). La justice, c'est rester aligné sur le Roi ; tout le reste est donné par-dessus.","mediter":"Quelle bonne chose risque de me voler le meilleur de Dieu en ce moment ?","mots":[["Demeurer","Rester en communion avec le Saint-Esprit, sans rien de non réglé."],["Comptes courts","Confesser rapidement, dès que l'Esprit me montre une offense."],["Émonder","Tailler une branche pour qu'elle porte plus de fruit."]]},"wb":{"but":"Comprendre ce que veut dire demeurer en Christ, et le pratiquer instant après instant.","ref":"Jean 15.5","verse":"Moi, je suis le cep, vous, les sarments. Celui qui demeure en moi, et moi en lui, celui-là porte beaucoup de fruit; car, séparés de moi, vous ne pouvez rien faire.","q":["Donne la définition de « demeurer » vue dans la leçon.","Pourquoi dit-on que demeurer est « conditionnel » ? De quoi cela dépend-il ?","Explique les trois dimensions : la largeur, la hauteur, la profondeur.","Que veut dire « tenir des comptes courts » avec Dieu ?","Comment la lecture de la Bible peut-elle devenir un péché ? (pense à l'enfant dans la rivière)","Que se passe-t-il dès que je confesse ce qui a rompu la communion ?"],"vf":["Demeurer, c'est d'abord faire beaucoup de choses pour Dieu.","Demeurer est le droit de naissance de tout enfant de Dieu.","Quand Dieu m'émonde, c'est un signe qu'il est fâché contre moi.","Je peux être sauvé et pourtant ne pas demeurer en ce moment."],"vfKey":[false,true,false,true],"ex":[{"k":"C1","q":"Dessine le même croyant à deux moments : quand il demeure et quand il ne demeure pas. Écris sous chaque dessin le résultat.","type":"text","rows":6,"hint":"En ligne : décris ou résume ton schéma avec tes mots (tu peux aussi le dessiner sur papier et le montrer à ton mentor)."},{"k":"C2","q":"Fais la liste de ce que Dieu « émonde » en toi en ce moment (Jean 15.2).","type":"text","rows":5}],"d":["Mes 15 minutes avec Dieu","Trois fois par jour : « Y a-t-il quelque chose de non réglé ? »","Confesser aussitôt, et noter le temps écoulé","Ne pas laisser le soleil se coucher sur ma colère","Je répète mon verset"],"j":"Combien de temps suis-je resté hors de la communion cette semaine, et qu'est-ce qui m'a ramené ?","go":"Le secret de la vie chrétienne tient en un mot : demeurer. Séparé de lui, rien ; avec lui, beaucoup de fruit."},"quiz":[{"type":"tf","q":"Demeurer, c'est d'abord faire beaucoup de choses pour Dieu.","a":false},{"type":"tf","q":"Demeurer est le droit de naissance de tout enfant de Dieu.","a":true},{"type":"tf","q":"Quand Dieu m'émonde, c'est un signe qu'il est fâché contre moi.","a":false},{"type":"tf","q":"Je peux être sauvé et pourtant ne pas demeurer en ce moment.","a":true},{"type":"mcq","q":"Quel mot correspond à cette définition ? « Rester en communion avec le Saint-Esprit, sans rien de non réglé. »","opts":["Envoi","Sanctification","Collaborateur de Dieu","Demeurer"],"a":3},{"type":"mcq","q":"Quel mot correspond à cette définition ? « Confesser rapidement, dès que l'Esprit me montre une offense. »","opts":["Abandon","Sarment","Comptes courts","La haie"],"a":2},{"type":"mcq","q":"Quel mot correspond à cette définition ? « Tailler une branche pour qu'elle porte plus de fruit. »","opts":["Obéissance partielle","Sarment","Émonder","Caleb"],"a":2},{"type":"mcq","q":"Quelle est la référence du verset de la semaine : « Moi, je suis le cep, vous, les sarments. Celui qui demeure en moi, et moi en lui, celui-là porte beaucoup de f… »","opts":["Proverbes 3.5-6","Jean 15.8","1 Corinthiens 6.19-20","Jean 15.5"],"a":3},{"type":"tf","q":"Quand Dieu m'émonde, c'est qu'il est fâché contre moi.","a":false,"why":"Il émonde le sarment qui porte du fruit, « afin qu'il porte plus de fruit » (Jean 15.2)."},{"type":"tf","q":"Lire la Bible est toujours une bonne chose.","a":false,"why":"Si je lis pendant qu'un enfant se noie devant moi… Ce qui plaît à Dieu se discerne instant après instant."}]},{"n":"1-10","ph":1,"etape":"Étape 3 · Demeurer","t":"Demeurer : versets et illustrations","fil":"Six images, une seule vérité","hook":"Le sarment ne force jamais pour porter du fruit. Quel est son secret ?","lire":"Jean 15.1-17","sup":{"phrase":"Le sarment ne produit pas le fruit : il porte la vie du cep. Ma part n'est pas de produire, mais de rester relié.","dec":["Le cep et le sarment (Jean 15).","Le vase, l'eau vive, la lampe, la lumière.","Le mariage, image de la communion avec Christ."],"pts":[["Le sarment","Jésus est le cep, je suis un sarment, l'Esprit produit son fruit. « Demeurez » est un ordre ; le fruit, lui, n'est jamais ordonné : il vient. Le Père est le vigneron : c'est lui qui émonde. Le résultat : la joie.","Jean 15.1-17"],["Le vase","Dans une grande maison, ce qui compte n'est pas la matière du vase mais sa propreté : un vase purifié est « utile au maître ». Le robinet : la pression de l'eau ne faiblit jamais ; si rien ne coule, c'est que j'ai fermé. Rouvrir demande une confession, pas un effort.","2 Timothée 2.20-21"],["L'eau vive","Une citerne garde ; une source donne. Les « citernes crevassées », c'est tout ce que je bâtis pour me satisfaire sans Dieu. Avant de couler à travers moi, l'eau doit d'abord être bue par moi.","Jérémie 2.13 ; Jean 7.37-39"],["La lampe","Le courant, c'est la vie de Dieu ; l'ampoule, c'est moi ; la lumière, c'est le fruit de l'Esprit ; l'interrupteur « allumé », c'est rester en harmonie avec lui. La lampe n'a pas à faire d'effort pour éclairer, et on ne regarde pas l'ampoule : on glorifie le Père.","Matthieu 5.14-16"],["Marcher dans la lumière","Ce n'est pas être sans péché, mais ne rien cacher : « si nous confessons nos péchés ». Le test est concret : celui qui hait son frère est dans les ténèbres.","1 Jean 1.5-10 ; 2.8-11"],["Le mariage","Une alliance (l'événement), puis une relation à entretenir (le processus). On n'est pas « plus ou moins » marié ; mais on peut être marié et ne plus se parler. Ainsi du salut et de la communion.","Éphésiens 5.21-33 ; Malachie 2.14"]],"schema":{"type":"table","titre":"Le schéma à retenir : six images, une même vérité","head":["L'image","Dieu","Moi","Ce qui m'est demandé"],"rows":[["Le cep","La vie du cep","Le sarment","Rester attaché"],["Le vase","Le Maître","Le vase","Être pur et disponible"],["L'eau vive","La source","Le canal","Boire, et laisser couler"],["La lampe","Le courant","L'ampoule","Rester « allumé »"],["La lumière","Dieu est lumière","Celui qui marche","Ne rien cacher"],["Le mariage","L'Époux","L'épouse","Entretenir la relation"]]},"table":null,"piege":[["Une lampe débranchée peut briller si elle fait assez d'efforts.","Sans le courant, même une ampoule parfaite reste froide et sombre."],["Une fois l'alliance conclue, la relation n'a plus besoin d'être entretenue.","Toute relation se détériore si on ne la nourrit pas."]],"astuce":"Jean 15.4 : pose une branche coupée sur ta table toute la semaine. Elle te rappellera ce qui arrive au sarment séparé du cep.","jesus":"« Le Père qui demeure en moi, c'est lui qui fait les œuvres » (Jean 14.10). Jésus a vécu comme un sarment de son Père avant de nous demander de vivre comme les siens.","royaume":"Le fruit de l'Esprit, c'est la culture du Royaume rendue visible. « Vous êtes le sel de la terre… la lumière du monde » (Matthieu 5.13-16) : des ambassadeurs qui montrent le Roi.","mediter":"Quelles sont mes « citernes crevassées » ? Mon robinet est-il ouvert en ce moment ?","mots":[["Cep","Le pied de vigne : Jésus, la source de la vie."],["Sarment","La branche de la vigne : moi, relié à Jésus."],["Citerne crevassée","Une source de satisfaction sans Dieu, qui ne retient rien."]]},"wb":{"but":"Comprendre « demeurer » à travers six images bibliques qui disent la même vérité.","ref":"Jean 15.4","verse":"Demeurez en moi, et moi en vous. Comme le sarment ne peut pas porter de fruit de lui-même, à moins qu’il ne demeure dans le cep, de même vous non plus vous ne le pouvez pas, à moins que vous ne demeuriez en moi.","q":["Cite les six images de la leçon.","Le sarment produit-il le fruit ? Que fait-il exactement ?","Quelles sont les trois qualités d'un vase utile au Maître (2 Timothée 2.21) ?","Quelle différence entre une source d'eau vive et une citerne crevassée (Jérémie 2.13) ?","Que m'apprend l'image de la lampe reliée au courant ?","En quoi le mariage est-il une image de la communion avec Christ ?"],"vf":["Une lampe débranchée peut briller si elle fait assez d'efforts.","Marcher dans la lumière, c'est ne rien cacher à Dieu et confesser aussitôt.","Une alliance conclue n'a plus besoin d'être entretenue.","Les six images disent toutes la même vérité : la vie vient de lui, je reste relié."],"vfKey":[false,true,false,true],"ex":[{"k":"C1","q":"Choisis l'image qui te parle le plus. Dessine-la et explique-la en cinq lignes à un enfant.","type":"text","rows":6,"hint":"En ligne : décris ou résume ton schéma avec tes mots (tu peux aussi le dessiner sur papier et le montrer à ton mentor)."},{"k":"C2","q":"Pour chaque image, écris ce qui la « coupe » dans ta vie (exemple : la lampe débranchée = …).","type":"text","rows":6}],"d":["Mes 15 minutes avec Dieu","Lire Jean 15.1-17, souligner et prier une phrase","Servir quelqu'un en secret","Nourrir ma communion (avec mon conjoint, si je suis marié)","Je répète mon verset"],"j":"Quelle image vais-je garder en tête pendant ma journée, et pourquoi ?","go":"Sarment, vase, source, lampe, lumière, alliance : six images, une seule vérité. Reste branché !"},"quiz":[{"type":"tf","q":"Une lampe débranchée peut briller si elle fait assez d'efforts.","a":false},{"type":"tf","q":"Marcher dans la lumière, c'est ne rien cacher à Dieu et confesser aussitôt.","a":true},{"type":"tf","q":"Une alliance conclue n'a plus besoin d'être entretenue.","a":false},{"type":"tf","q":"Les six images disent toutes la même vérité : la vie vient de lui, je reste relié.","a":true},{"type":"mcq","q":"Quel mot correspond à cette définition ? « Le pied de vigne : Jésus, la source de la vie. »","opts":["Cep","Miséricorde","Redevable","Émonder"],"a":0},{"type":"mcq","q":"Quel mot correspond à cette définition ? « La branche de la vigne : moi, relié à Jésus. »","opts":["Orgueil spirituel","Terre promise","Fruit artificiel","Sarment"],"a":3},{"type":"mcq","q":"Quel mot correspond à cette définition ? « Une source de satisfaction sans Dieu, qui ne retient rien. »","opts":["Affranchi","Parent spirituel","Citerne crevassée","Redevable"],"a":2},{"type":"mcq","q":"Quelle est la référence du verset de la semaine : « Demeurez en moi, et moi en vous. Comme le sarment ne peut pas porter de fruit de lui-même, à moins qu’il ne de… »","opts":["Jean 15.4","Philippiens 4.6-7","Jean 15.8","Job 1.21"],"a":0},{"type":"tf","q":"Une lampe débranchée peut briller si elle fait assez d'efforts.","a":false,"why":"Sans le courant, même une ampoule parfaite reste froide et sombre."},{"type":"tf","q":"Une fois l'alliance conclue, la relation n'a plus besoin d'être entretenue.","a":false,"why":"Toute relation se détériore si on ne la nourrit pas."}]},{"n":"1-11","ph":1,"etape":"Étape 3 · Demeurer","t":"Demeurer aujourd'hui","fil":"Libre du passé et de l'avenir","hook":"Ton passé et ton avenir pèsent-ils sur le pont d'aujourd'hui ?","lire":"Philippiens 4.4-9 ; Matthieu 5.23-24","sup":{"phrase":"Dieu veut me libérer du poids des questions non réglées du passé et des inquiétudes de l'avenir, pour porter son fruit aujourd'hui.","dec":["L'examen en trois questions : le présent, le passé, l'avenir.","Pardonner, demander pardon, aller vers l'autre, réparer.","La différence entre prévoir et s'inquiéter."],"pts":[["Le présent : est-ce que je demeure ?","Si non, pourquoi ? La cause est souvent liée aux autres, à une question personnelle avec Dieu, ou à l'avenir.",""],["Je ne peux pas être bien avec Dieu en négligeant les autres","Aimer est un choix : faire ce qui est le meilleur pour quelqu'un, même sans affection. « Haïr », ici, c'est l'absence d'amour.","1 Jean 2.9-11"],["Quatre démarches envers les autres","Pardonner (un choix de la volonté : je renonce à me venger et remets la dette à Dieu). Demander pardon. Aller vers celui qui m'a offensé. Réparer un tort. Dans chaque cas, c'est à moi de faire le premier pas. Je réponds de mon amour, non de celui des autres.","Marc 11.25 ; Matthieu 5.23-24 ; 18.15 ; Romains 12.18"],["C'est l'Esprit qui décide de quoi je suis redevable","Pas moi ! Comme un bon parent, il me forme selon mon âge spirituel : on ne gronde pas un bébé de six mois comme un enfant de six ans. Je deviens de plus en plus sensible à son murmure.","1 Jean 1.9"],["Vivre en harmonie sans penser pareil","Si un comportement me dérange alors que Dieu ne dit pas que c'est un péché, je dois peut-être examiner mon propre cœur.",""],["L'avenir : prévoir, oui ; s'inquiéter, non","Le souci peut glisser vers l'inquiétude, puis l'anxiété, puis la panique. « Ne soyez pas en souci » n'est pas une suggestion. L'inquiétude dit en silence : « Dieu ne sait pas, ne peut pas, ou ne veut pas. » Jésus répond : « Votre Père sait. »","Matthieu 6.31-34 ; Philippiens 4.6-7"],["Le suivre, plutôt que le conduire","Je fais des projets en disant « si le Seigneur le veut ». Je le laisse être impliqué dans tous mes projets d'avenir.","Proverbes 3.5-6 ; Jacques 4.13-17"]],"schema":{"type":"grid","titre":"Le schéma à retenir : l'examen du soir","cols":3,"items":[["Le passé","Dois-je pardonner, demander pardon, réparer, confesser ?"],["Le présent","Suis-je en communion avec le Seigneur en ce moment ?"],["L'avenir","Une inquiétude trouble-t-elle ma communion ?"]]},"table":{"titre":"Une pente glissante","head":["Le souci","L'inquiétude","L'anxiété","La panique"],"rows":[["Sage et prudent","Je commence à porter seul","Je ne me confie plus","Je suis submergé"]]},"piege":[["C'est à l'autre de faire le premier pas quand il m'a blessé.","Jésus dit : « va » (Matthieu 18.15). Le premier pas est toujours pour moi."],["Pardonner, c'est dire que l'autre avait raison.","Pardonner, c'est renoncer à me venger et remettre la dette à Dieu ; cela ne nie pas la blessure."]],"astuce":"Philippiens 4.6-7 suit un ordre : « ne vous inquiétez de rien », « exposez vos requêtes », « avec des actions de grâces », « la paix gardera ». Apprends-le en quatre étapes.","jesus":"Crucifié, il a prié : « Père, pardonne-leur » (Luc 23.34). Outragé, il ne rendait pas l'outrage, mais se remettait à celui qui juge justement (1 Pierre 2.23). Ni rancune, ni anxiété.","royaume":"Le pardon est une loi du Royaume (Matthieu 6.14-15). Le Roi répond du bien-être de ses citoyens : s'inquiéter, c'est oublier qui gouverne (Matthieu 6.25-33).","mediter":"Quel nom m'est venu à l'esprit pendant cette leçon ? Quel souci pour demain me vole la communion d'aujourd'hui ?","mots":[["Pardonner","Renoncer à mon droit de me venger et remettre la dette à Dieu."],["Réconciliation","La relation rétablie ; elle demande deux personnes, le pardon une seule."],["Redevable","Responsable devant Dieu de ce qu'il me montre."]]},"wb":{"but":"Être libre du passé et de l'avenir pour demeurer et porter du fruit aujourd'hui.","ref":"Philippiens 4.6-7","verse":"Ne vous inquiétez de rien, mais, en toutes choses, exposez vos requêtes à Dieu par des prières et des supplications avec des actions de grâces; et la paix de Dieu, laquelle surpasse toute intelligence, gardera vos cœurs et vos pensées dans le christ Jésus.","q":["Quelles sont les trois questions pour savoir si je demeure : le présent, le passé, l'avenir ?","Pourquoi ne puis-je pas être bien avec Dieu en négligeant les autres ?","Cite quatre démarches possibles envers une personne. Qui doit faire le premier pas ?","Qui décide de ce dont je suis redevable devant Dieu ? Pourquoi est-ce une bonne nouvelle ?","Quelle est la différence entre prévoir et s'inquiéter ?","Que signifie dire « si le Seigneur le veut » (Jacques 4.15) ?"],"vf":["Aimer les autres est un sentiment que j'attends d'avoir.","Faire des projets est contraire à la foi.","Le Saint-Esprit me forme selon mon âge spirituel.","C'est à l'autre de faire le premier pas quand il m'a blessé."],"vfKey":[false,false,true,false],"ex":[{"k":"C1","q":"Écris trois colonnes : « le passé », « aujourd'hui », « l'avenir ». Dans chacune, note ce qui t'empêche de demeurer.","type":"table","cols":["Le passé","Aujourd'hui","L'avenir"],"rows":5},{"k":"C2","q":"Transforme une inquiétude précise en prière selon Philippiens 4.6 : requête, supplication, action de grâces.","type":"text","rows":6}],"d":["Mes 15 minutes avec Dieu","Faire un pas concret vers une personne","Le soir : présent, passé, avenir","Dire « si le Seigneur le veut » pour mes projets","Je répète mon verset"],"j":"Quel poids du passé ou de l'avenir ai-je déposé cette semaine ?","go":"Hier est pardonné, demain est entre ses mains. Aujourd'hui est le jour où tu peux porter du fruit."},"quiz":[{"type":"tf","q":"Aimer les autres est un sentiment que j'attends d'avoir.","a":false},{"type":"tf","q":"Faire des projets est contraire à la foi.","a":false},{"type":"tf","q":"Le Saint-Esprit me forme selon mon âge spirituel.","a":true},{"type":"tf","q":"C'est à l'autre de faire le premier pas quand il m'a blessé.","a":false},{"type":"mcq","q":"Quel mot correspond à cette définition ? « Renoncer à mon droit de me venger et remettre la dette à Dieu. »","opts":["Ressources","Jourdain","Pardonner","Désert spirituel"],"a":2},{"type":"mcq","q":"Quel mot correspond à cette définition ? « La relation rétablie ; elle demande deux personnes, le pardon une seule. »","opts":["Sacrificature","Événement","Seigneurie","Réconciliation"],"a":3},{"type":"mcq","q":"Quel mot correspond à cette définition ? « Responsable devant Dieu de ce qu'il me montre. »","opts":["Fruit artificiel","Voile","Grâce","Redevable"],"a":3},{"type":"mcq","q":"Quelle est la référence du verset de la semaine : « Ne vous inquiétez de rien, mais, en toutes choses, exposez vos requêtes à Dieu par des prières et des supplica… »","opts":["1 Jean 2.6","Jean 15.8","Proverbes 3.5-6","Philippiens 4.6-7"],"a":3},{"type":"tf","q":"C'est à l'autre de faire le premier pas quand il m'a blessé.","a":false,"why":"Jésus dit : « va » (Matthieu 18.15). Le premier pas est toujours pour moi."},{"type":"tf","q":"Pardonner, c'est dire que l'autre avait raison.","a":false,"why":"Pardonner, c'est renoncer à me venger et remettre la dette à Dieu ; cela ne nie pas la blessure."}]},{"n":"1-12","ph":1,"etape":"Étape 3 · Demeurer","t":"Vivre dans la communion","fil":"Le désert ou la terre promise","hook":"Onze jours de marche… et ils ont mis quarante ans. Et toi ?","lire":"Nombres 13-14 ; Psaume 51","sup":{"phrase":"Après le salut, deux chemins s'ouvrent au croyant : le désert, où je dirige ma vie, ou la terre promise, où Christ est mon Maître.","dec":["Les trois délivrances du péché.","Les deux chemins, et le Jourdain qui les sépare.","Ce qui se passe quand je tombe, et ce qui sera récompensé."],"pts":[["Trois délivrances","À la croix, j'ai été délivré de la peine du péché. Pendant cette vie, je suis en train d'être délivré de sa puissance. À la mort, je serai délivré de sa présence.","Romains 6.6-7"],["Le chemin du désert","Un croyant qui n'a pas reconnu la seigneurie de Christ, souvent faute d'accompagnement : il imite les autres au lieu de suivre l'Esprit. Dieu est pour lui un « associé minoritaire » qu'on appelle quand on n'y arrive plus. Sauvé, mais étouffé par les soucis, les richesses et les plaisirs : sans fruit.","Luc 8.14"],["Le Jourdain : la décision de seigneurie","Ce n'est pas décider de « faire de mon mieux ». C'est abandonner ma volonté, prendre son joug, le laisser vivre sa vie à travers moi. Les eaux du Jourdain ne se sont arrêtées que lorsque les pieds ont touché l'eau : Dieu ouvre le chemin quand je fais le pas.","Matthieu 11.28-30 ; Galates 2.20 ; Josué 3"],["Le chemin de la terre promise","La vie chrétienne normale : demeurer constamment dans la communion. Tout chrétien y a droit. Les combats ne disparaissent pas, mais on ne combat plus de la même manière quand le Seigneur est le chef.",""],["Quand je tombe : l'exemple de David","David est resté environ neuf mois hors de la communion. Dès qu'il a confessé « J'ai péché contre l'Éternel », il a été pardonné et restauré, mais il a vécu avec les conséquences. Les ruptures arrivent ; elles doivent devenir l'exception, plus rares et plus courtes.","2 Samuel 12.13 ; Psaume 32.5 ; Psaume 51"],["Ma part : demeurer ; le fruit vient de lui","Je n'ai pas à m'efforcer de produire du fruit, ni à m'en inquiéter. La question n'est pas « ai-je du fruit ? » mais « d'où vient-il ? ».","Jean 15.5"],["Les récompenses","Seul ce que l'Esprit produit est éternel et sera récompensé. Une perte n'est pas une punition : à une remise de diplômes, celui qui n'a pas de prix n'est pas puni.","1 Corinthiens 3.10-15 ; 13.1-3 ; Matthieu 6.20-21"]],"schema":{"type":"table","titre":"Le schéma à retenir : les deux chemins","head":["","Le désert","La terre promise"],"rows":[["Dieu est pour moi","Un associé minoritaire","Le Maître qui dirige"],["Force dominante","La nature pécheresse","Le Saint-Esprit"],["Comment je décide","Mon intelligence, l'exemple des autres","La direction de l'Esprit"],["Le fruit","Temporel","Éternel, récompensé"],["Quand je tombe","Je m'installe","Je confesse aussitôt"]]},"table":null,"piege":[["Traverser le Jourdain, c'est faire de mon mieux pour Dieu.","C'est abandonner ma volonté et le laisser vivre à travers moi."],["Demeurer constamment, c'est irréaliste et réservé aux « super spirituels ».","C'est mon droit de naissance : il ne s'agit pas d'atteindre, mais de saisir par la foi."]],"astuce":"Galates 2.20 en trois temps : « crucifié avec Christ » / « Christ vit en moi » / « je vis dans la foi ».","jesus":"« Ma viande est de faire la volonté de celui qui m'a envoyé » (Jean 4.34). Faire la volonté du Père nourrissait Jésus. Il veut vivre cette vie en nous (Galates 2.20).","royaume":"Être citoyen ne suffit pas : il faut vivre selon les lois du Roi. « Ce ne sont pas tous ceux qui me disent : Seigneur, Seigneur… mais celui qui fait la volonté de mon Père » (Matthieu 7.21).","mediter":"Sur quel chemin suis-je ce mois-ci ? Combien de temps est-ce que je reste hors de la communion avant de confesser ?","mots":[["Désert spirituel","La vie d'un croyant sauvé qui dirige lui-même sa vie : sans fruit."],["Terre promise","La vie chrétienne normale, sous la direction de Christ."],["Jourdain","L'image de la décision de seigneurie."]]},"wb":{"but":"Choisir le chemin de la terre promise plutôt que celui du désert, et retrouver aussitôt la communion quand je tombe.","ref":"Galates 2.20","verse":"Je suis crucifié avec Christ; et je ne vis plus, moi, mais Christ vit en moi; – et ce que je vis maintenant dans la chair, je le vis dans la foi, la foi au Fils de Dieu, qui m’a aimé et qui s’est livré lui-même pour moi.","q":["De quoi suis-je déjà délivré, de quoi suis-je en train d'être délivré, et de quoi le serai-je bientôt ?","Décris les deux chemins qui s'ouvrent au croyant après le salut.","Que représente la traversée du Jourdain (Josué 3) ?","Quand la communion est rompue, comment est-elle rétablie ? Les conséquences disparaissent-elles toujours ?","Quelle est ma part, et quelle est la part de Dieu, dans le fruit ?","Qu'est-ce qui sera récompensé pour l'éternité ?"],"vf":["Traverser le Jourdain, c'est faire de mon mieux pour Dieu.","Un croyant peut être sauvé et vivre dans le désert pendant des années.","La confession rétablit la communion aussitôt.","Tout ce que je fais pour Dieu sera récompensé, même ce qui vient de la chair."],"vfKey":[false,true,true,false],"ex":[{"k":"C1","q":"Dessine les deux chemins côte à côte : le désert et la terre promise. Écris sur chacun trois signes qui le caractérisent.","type":"table","cols":["Le désert","La terre promise"],"rows":5},{"k":"C2","q":"Lis 2 Samuel 11 et 12. Note combien de temps David est resté hors de la communion, et ce qui l'a ramené.","type":"text","rows":5}],"d":["Mes 15 minutes avec Dieu","Lire Romains 8, puis 2 Samuel 11-12 et le Psaume 51","Confesser dans l'heure quand je tombe","Avant chaque décision : « Mon plan ou le tien ? »","Je répète mon verset"],"j":"Suis-je aujourd'hui au désert ou dans la terre promise ? Qu'est-ce qui le montre ?","go":"Le désert n'est pas ta destination. Traverse le Jourdain : Christ vit en toi, et la terre promise t'attend."},"quiz":[{"type":"tf","q":"Traverser le Jourdain, c'est faire de mon mieux pour Dieu.","a":false},{"type":"tf","q":"Un croyant peut être sauvé et vivre dans le désert pendant des années.","a":true},{"type":"tf","q":"La confession rétablit la communion aussitôt.","a":true},{"type":"tf","q":"Tout ce que je fais pour Dieu sera récompensé, même ce qui vient de la chair.","a":false},{"type":"mcq","q":"Quel mot correspond à cette définition ? « La vie d'un croyant sauvé qui dirige lui-même sa vie : sans fruit. »","opts":["Don spirituel","Trésor dans le ciel","Discerner","Désert spirituel"],"a":3},{"type":"mcq","q":"Quel mot correspond à cette définition ? « La vie chrétienne normale, sous la direction de Christ. »","opts":["Terre promise","Reproduction spirituelle","Émonder","Émonder"],"a":0},{"type":"mcq","q":"Quel mot correspond à cette définition ? « L'image de la décision de seigneurie. »","opts":["Jourdain","Intimité spirituelle","Seigneurie","Sarment"],"a":0},{"type":"mcq","q":"Quelle est la référence du verset de la semaine : « Je suis crucifié avec Christ; et je ne vis plus, moi, mais Christ vit en moi; – et ce que je vis maintenant da… »","opts":["1 Corinthiens 3.9","Galates 2.20","Matthieu 28.19-20","Éphésiens 2.8-9"],"a":1},{"type":"tf","q":"Traverser le Jourdain, c'est faire de mon mieux pour Dieu.","a":false,"why":"C'est abandonner ma volonté et le laisser vivre à travers moi."},{"type":"tf","q":"Demeurer constamment, c'est irréaliste et réservé aux « super spirituels ».","a":false,"why":"C'est mon droit de naissance : il ne s'agit pas d'atteindre, mais de saisir par la foi."}]},{"n":"1-13","ph":1,"etape":"Étape 4 · Grandir","t":"Le développement spirituel du chrétien normal","fil":"Quatre étapes, et l'histoire de Vera","hook":"Le fruit vient en dernier. Mais qu'est-ce qui vient avant ?","lire":"Jean 15.8 ; Galates 5.22-23","sup":{"phrase":"Deux décisions (le salut, la seigneurie), un processus (demeurer), un résultat (le fruit que Dieu produit à travers moi).","dec":["Les quatre étapes du développement spirituel.","Les six aspects du fruit.","L'histoire vraie de Vera, et comment « remonter la chaîne »."],"pts":[["Le salut : une décision, une certitude","Celui qui croit « a » la vie éternelle. Dieu veut que je le sache, pas que je l'espère vaguement.","Jean 5.24 ; 1 Jean 5.13"],["La seigneurie : une décision, un repos","Jésus offre un joug et promet le repos : l'abandon n'est pas un fardeau de plus, c'est la fin de porter seul. « Appliquons-nous à entrer dans ce repos. »","Matthieu 11.29-30 ; Hébreux 4.11"],["Demeurer : un processus","Le but : une communion continuelle, et être un vase utilisable.","Jean 15.1-5 ; 2 Timothée 2.21"],["Le fruit : Dieu le produit","Six aspects : l'Esprit produit son caractère en moi ; Dieu se glorifie ; il me fait mûrir ; il emploie mes dons ; il prépare des récompenses ; il attire d'autres personnes à lui à travers moi.","Galates 5.22-23 ; Jean 15.8"],["Pourquoi le fruit vient en dernier","Le fruit n'est pas un devoir de plus : c'est la conséquence d'une vie reliée. Chercher le fruit sans demeurer, c'est l'activité religieuse : beaucoup d'efforts, peu de vie.",""],["L'histoire de Vera","Sauvée jeune, elle a vécu des années de désert, sans scandale, simplement dirigée par elle-même. Un jour, elle a demandé à Jésus d'être le Seigneur de sa vie. Elle a réparé ses torts, a eu faim de la Parole, a prié chaque jour. Des années plus tard, sa vie encourageait beaucoup d'autres. Personne ne l'avait accompagnée au début : voilà pourquoi nous formons des disciples.",""]],"schema":{"type":"flow","titre":"Le schéma à retenir : quatre étapes","items":[["1","Le salut","une décision"],["2","La seigneurie","une décision"],["3","Demeurer","un processus"],["4","Le fruit","Dieu le produit"]]},"table":{"titre":"Si le fruit manque : je remonte la chaîne","head":["Je me demande…","Si non, je relis…"],"rows":[["Dieu produit-il du fruit à travers moi ?","Je continue de demeurer, et je rends gloire à Dieu"],["Est-ce que je demeure chaque jour ?","Les leçons 1-9 et 1-11"],["Ai-je pris la décision de seigneurie ?","La leçon 1-7"],["Suis-je certain d'avoir la vie éternelle ?","Les leçons 1-1 et 1-3"]]},"piege":[["Si le fruit manque, je dois redoubler d'efforts.","Je ne répare pas le fruit : je remonte la chaîne."],["Le désert annule le salut.","Vera était vraiment sauvée : le désert ne retire pas le salut, il retarde le fruit."]],"astuce":"Jean 15.8 est court : récite-le chaque fois que tu vois un arbre fruitier.","jesus":"« Je t'ai glorifié sur la terre, j'ai achevé l'œuvre que tu m'as donnée à faire » (Jean 17.4). Le Père est glorifié en nous de la même manière : par beaucoup de fruit (Jean 15.8).","royaume":"Le Royaume grandit comme une semence : d'abord l'herbe, puis l'épi, puis le blé bien formé (Marc 4.26-29). Le citoyen devient ambassadeur.","mediter":"Qui, près de moi, est un « Vera » au début de sa route, sans personne pour l'accompagner ?","mots":[["Fruit","Tout ce que le Saint-Esprit produit à travers ma vie."],["Vase utilisable","Un croyant disponible, que Dieu peut employer à tout moment."]]},"wb":{"but":"Situer ma vie sur les quatre étapes (salut, seigneurie, demeurer, fruit) et savoir quoi faire si le fruit manque.","ref":"Jean 15.8","verse":"En ceci mon Père est glorifié, que vous portiez beaucoup de fruit; et vous serez mes disciples.","q":["Quelles sont les deux décisions, le processus et le résultat du schéma ?","Pourquoi le salut est-il une certitude et non un espoir (Jean 5.24 ; 1 Jean 5.13) ?","Que veut dire « entrer dans son repos » pour la seigneurie (Matthieu 11.29-30 ; Hébreux 4.11) ?","Cite les six aspects du fruit que Dieu produit à travers moi.","Pourquoi le fruit vient-il en dernier ?","Raconte en quelques lignes l'histoire de Vera. Qu'est-ce qui lui a manqué au début ?"],"vf":["Le fruit est le point de départ de la vie chrétienne.","La décision de seigneurie est parfois prise des années après la conversion.","Si le fruit manque, il faut redoubler d'efforts pour le produire.","Le désert n'annule pas le salut, mais il retarde le fruit."],"vfKey":[false,true,false,true],"ex":[{"k":"C1","q":"Écris ton histoire en quatre courts paragraphes sous les titres : salut, seigneurie, demeurer, fruit.","type":"table","cols":["Mon salut","Ma seigneurie","Demeurer","Le fruit"],"rows":5},{"k":"C2","q":"Remonte la chaîne : Dieu produit-il du fruit ? Est-ce que je demeure ? Ai-je pris la décision de seigneurie ? Suis-je sûr d'avoir la vie éternelle ?","type":"text","rows":5}],"d":["Mes 15 minutes avec Dieu","Lire mon histoire à une personne","Prier pour un nouveau croyant à accompagner","Remercier Dieu pour un fruit qu'il a produit","Je répète mon verset"],"j":"À quelle étape suis-je vraiment, et quel est le prochain pas ?","go":"Ton histoire est en train de s'écrire. Comme Vera, tu peux devenir une source de vie pour beaucoup d'autres."},"quiz":[{"type":"tf","q":"Le fruit est le point de départ de la vie chrétienne.","a":false},{"type":"tf","q":"La décision de seigneurie est parfois prise des années après la conversion.","a":true},{"type":"tf","q":"Si le fruit manque, il faut redoubler d'efforts pour le produire.","a":false},{"type":"tf","q":"Le désert n'annule pas le salut, mais il retarde le fruit.","a":true},{"type":"mcq","q":"Quel mot correspond à cette définition ? « Tout ce que le Saint-Esprit produit à travers ma vie. »","opts":["Bêma","Nature humaine","Fruit","Souveraineté"],"a":2},{"type":"mcq","q":"Quel mot correspond à cette définition ? « Un croyant disponible, que Dieu peut employer à tout moment. »","opts":["Vase utilisable","Reproduction spirituelle","Restauration","Sarment"],"a":0},{"type":"mcq","q":"Quelle est la référence du verset de la semaine : « En ceci mon Père est glorifié, que vous portiez beaucoup de fruit; et vous serez mes disciples. »","opts":["Jean 15.9","1 Jean 2.28","Jean 5.24","Jean 15.8"],"a":3},{"type":"tf","q":"Si le fruit manque, je dois redoubler d'efforts.","a":false,"why":"Je ne répare pas le fruit : je remonte la chaîne."},{"type":"tf","q":"Le désert annule le salut.","a":false,"why":"Vera était vraiment sauvée : le désert ne retire pas le salut, il retarde le fruit."}]},{"n":"1-14","ph":1,"etape":"Étape 4 · Grandir","t":"Épreuves, souffrance et souveraineté de Dieu","fil":"Rien ne m'atteint sans passer par ses mains","hook":"Et si ton épreuve n'était que l'envers d'une magnifique broderie ?","lire":"Romains 8.28-29 ; Jérémie 18.1-6","sup":{"phrase":"Chaque circonstance, bonne ou mauvaise, passe par la volonté permissive de Dieu : il s'en sert pour faire de moi un vase saint et utile.","dec":["Deux manières de répondre à l'épreuve.","Les cinq raisons habituelles de la souffrance.","Jésus, Paul, Job et Joseph : quatre réponses, une même confiance."],"pts":[["Deux manières de répondre","Si je ne comprends pas sa souveraineté, je réponds par la plainte, le reproche, l'apitoiement, la colère, l'amertume. Si je la comprends, je lui dis que j'accepte ce qu'il permet, je cherche comment répondre d'une manière digne de lui, et quelles leçons il veut m'apprendre.",""],["Dieu maîtrise tout, et ne fait jamais le mal","Son œuvre est parfaite. Il maîtrise chaque détail de ma vie. Souverain ne veut pas dire auteur du mal : les frères de Joseph ont péché, Dieu non. Toutes choses ne sont pas bonnes, mais elles travaillent ensemble pour le bien : être rendu semblable à son Fils.","Deutéronome 32.4 ; Psaume 139 ; Romains 8.28-29 ; Genèse 50.20"],["L'épreuve fait partie de la vie normale","Elle n'est pas un signe de rejet, et la bénédiction n'est pas toujours une médaille. La veuve pauvre était riche devant Dieu ; Paul a souffert au centre de la volonté de Dieu.","Marc 12.41-44 ; 2 Corinthiens 11.23-27 ; Jean 16.33"],["Cinq raisons habituelles","a. Former mon caractère. b. Les conséquences de ma désobéissance, de ma négligence ou de mon imprudence. c. Me jeter sur le Seigneur, sans m'appuyer sur moi. d. Comprendre les besoins des autres. e. Briller davantage pour que d'autres voient Dieu. Seule la raison b appelle la repentance.","Romains 5.3-4 ; Hébreux 12.6-11 ; 2 Corinthiens 12.9 ; 1.3-5 ; Actes 16.22-34"],["La bonne question","Les disciples demandaient : « Qui a péché ? » Jésus déplace la question vers : « En vue de quoi ? » Prière utile : « Seigneur, que veux-tu former en moi, et à qui veux-tu que cela serve ? »","Jean 9.2-3"],["Dieu réordonne ce qui m'est cher","Il me demande parfois de lâcher mes idoles pour me donner ce qu'il a de meilleur. Ma foi éprouvée est plus précieuse que l'or.","1 Pierre 1.6-7"],["Quatre réponses, une même confiance","Jésus s'est remis à celui qui juge justement. Paul a reçu la grâce plutôt que la délivrance. Job a adoré avant de comprendre. Joseph a vu la main de Dieu derrière celle de ses frères : « Ce n'est pas vous, c'est Dieu. »","1 Pierre 2.23 ; 2 Corinthiens 12.9-10 ; Job 1.20-22 ; Genèse 45.5"]],"schema":{"type":"grid","titre":"Le schéma à retenir : cinq raisons de la souffrance","cols":5,"items":[["a","Former mon caractère"],["b","Conséquence de ma faute"],["c","Dépendre de lui"],["d","Comprendre les autres"],["e","Briller pour lui"]]},"table":null,"piege":[["Si je souffre, c'est que Dieu est fâché contre moi.","L'épreuve n'est pas un signe de son déplaisir : Paul a souffert en lui obéissant."],["Dieu est l'auteur du mal qu'on me fait.","Il le permet et le retourne pour le bien, mais il ne fait jamais le mal (Genèse 50.20)."]],"astuce":"Romains 8.28 : écris-le sur un papier que tu gardes dans ta poche. Relis-le chaque fois que quelque chose te contrarie.","jesus":"À Gethsémané : « non pas comme moi je veux, mais comme toi tu veux » (Matthieu 26.39). Il a enduré la croix à cause de la joie qui était devant lui (Hébreux 12.2).","royaume":"Le citoyen qui cherche d'abord le Royaume vit sous la responsabilité de son Roi (Matthieu 6.33). Les crises ne détrônent pas le Roi : elles montrent à qui j'appartiens.","mediter":"Quelle circonstance n'ai-je pas encore acceptée ? Que veut-il former en moi à travers elle ?","mots":[["Souveraineté","L'autorité absolue de Dieu sur toutes choses."],["Volonté permissive","Ce que Dieu permet sans toujours l'approuver."],["Épreuve","Tout ce que je trouve personnellement désagréable."]]},"wb":{"but":"Accepter que chaque circonstance passe par la volonté permissive de Dieu, et répondre aux épreuves avec confiance plutôt qu'avec plainte.","ref":"Romains 8.28","verse":"Nous savons que toutes choses travaillent ensemble pour le bien de ceux qui aiment Dieu, de ceux qui sont appelés selon son propos.","q":["Quelles sont les cinq réactions de celui qui ne comprend pas la souveraineté de Dieu, et les trois attitudes qui plaisent à Dieu ?","Pourquoi l'épreuve n'est-elle pas un signe du déplaisir de Dieu ? Cite un exemple biblique.","Donne les cinq raisons pour lesquelles Dieu permet habituellement la souffrance (a à e).","Laquelle de ces cinq raisons appelle la repentance ?","Que veut dire que Dieu « réordonne ce qui m'est cher » ? Donne l'exemple d'Abraham.","Qu'ont en commun les réponses de Jésus, Paul, Job et Joseph ?"],"vf":["Si je souffre, c'est que Dieu est fâché contre moi.","Les bénédictions matérielles prouvent toujours ma fidélité.","Dieu ne permet jamais une épreuve au-delà de mes forces (1 Corinthiens 10.13).","Dieu est l'auteur du mal que les frères de Joseph lui ont fait."],"vfKey":[false,false,true,false],"ex":[{"k":"C1","q":"Pense à une épreuve passée. Laquelle des cinq raisons y reconnais-tu aujourd'hui ? Qu'as-tu appris ?","type":"text","rows":6},{"k":"C2","q":"Transforme une plainte actuelle en prière d'acceptation : « Seigneur, j'accepte… Que veux-tu m'apprendre ? »","type":"text","rows":5}],"d":["Mes 15 minutes avec Dieu","Lire le Psaume 139 et noter ma réaction du jour","« J'accepte ce que tu permets. Que veux-tu m'apprendre ? »","Consoler une personne qui souffre","Je répète mon verset"],"j":"Quelle réaction a changé en moi cette semaine face à une difficulté ?","go":"Rien ne t'atteint sans passer par les mains d'un Père qui t'aime. Toutes choses travaillent pour ton bien."},"quiz":[{"type":"tf","q":"Si je souffre, c'est que Dieu est fâché contre moi.","a":false},{"type":"tf","q":"Les bénédictions matérielles prouvent toujours ma fidélité.","a":false},{"type":"tf","q":"Dieu ne permet jamais une épreuve au-delà de mes forces (1 Corinthiens 10.13).","a":true},{"type":"tf","q":"Dieu est l'auteur du mal que les frères de Joseph lui ont fait.","a":false},{"type":"mcq","q":"Quel mot correspond à cette définition ? « L'autorité absolue de Dieu sur toutes choses. »","opts":["Fondement","Vase utilisable","Souveraineté","Vieil homme"],"a":2},{"type":"mcq","q":"Quel mot correspond à cette définition ? « Ce que Dieu permet sans toujours l'approuver. »","opts":["Chair","Volonté permissive","Photocopie","Émonder"],"a":1},{"type":"mcq","q":"Quel mot correspond à cette définition ? « Tout ce que je trouve personnellement désagréable. »","opts":["Épreuve","Bêma","Vieil homme","Désert spirituel"],"a":0},{"type":"mcq","q":"Quelle est la référence du verset de la semaine : « Nous savons que toutes choses travaillent ensemble pour le bien de ceux qui aiment Dieu, de ceux qui sont appe… »","opts":["Jean 15.4","Matthieu 11.28-30","Galates 2.20","Romains 8.28"],"a":3},{"type":"tf","q":"Si je souffre, c'est que Dieu est fâché contre moi.","a":false,"why":"L'épreuve n'est pas un signe de son déplaisir : Paul a souffert en lui obéissant."},{"type":"tf","q":"Dieu est l'auteur du mal qu'on me fait.","a":false,"why":"Il le permet et le retourne pour le bien, mais il ne fait jamais le mal (Genèse 50.20)."}]},{"n":"1-15","ph":1,"etape":"Étape 4 · Grandir","t":"Discerner la volonté de Dieu","fil":"La pyramide des bons choix","hook":"Comment savoir ce que Dieu veut vraiment pour ta vie ?","lire":"Proverbes 3.5-6 ; 1 Rois 13.1-26","sup":{"phrase":"Dieu donne toujours le meilleur à ceux qui lui laissent le choix : la pyramide m'aide à décider avec lui, de la base jusqu'au sommet.","dec":["Les cinq niveaux de la pyramide, de bas en haut.","Les quatre critères : la Parole, la paix, les circonstances, le conseil.","Deux méthodes : active et passive."],"pts":[["Niveau 1 : les buts de Dieu pour moi","Que je l'aime et que je sois transformé à l'image de son Fils ; que je serve à atteindre les incroyants et à faire mûrir les croyants ; que je le laisse m'employer dans son plan. La plus grande partie de sa volonté est déjà connue.",""],["Niveau 2 : les conditions préalables","Croire que Dieu a un plan fait sur mesure pour moi ; qu'il veut me le faire connaître ; qu'il est souverain et capable de l'accomplir.","Psaume 139.16 ; Romains 12.1-2 ; Proverbes 19.21"],["Niveau 3 : une attitude abandonnée","Désirer sa volonté et la chercher dans la prière ; m'humilier et le laisser changer mes priorités ; accepter la part de risque de la foi ; accepter que l'obéissance ait un prix. Dieu demande un oui donné d'avance, non un examen de sa proposition.","Jacques 1.5-8 ; Psaume 32.8-9 ; Hébreux 11.6"],["Niveau 4 : quatre critères","La Parole : que dit la Bible ? La paix : la paix de Dieu agit-elle comme un arbitre dans mon cœur ? Les circonstances : Dieu les orchestre. Le conseil : un chrétien sage et pieux. La Parole juge les trois autres.","Psaume 119.105 ; Colossiens 3.15 ; Proverbes 12.15"],["Deux mises en garde","Les sentiments et les désirs peuvent tromper : « le cœur est trompeur ». Un péché non confessé peut m'empêcher de discerner. Et le conseil peut être faux : la femme de Job, ses amis.","Proverbes 28.26 ; Psaume 66.18 ; Job 2.9"],["Niveau 5 : deux méthodes","Active : j'avance prudemment dans la direction qui paraît la meilleure, et Dieu ouvre ou ferme les portes ; on ne dirige pas une voiture garée. Passive : j'attends que Dieu confirme. Attention : nous sommes souvent actifs pour ce que nous désirons, et passifs pour ce que nous redoutons.","Psaume 37.23-24 ; Psaume 27.14 ; Exode 14.14-15"],["Quand avancer ?","Quand les quatre critères s'accordent, j'avance. Quand un seul manque, j'attends et je prie. Quand la Parole dit non, la question est close.",""]],"schema":{"type":"pyramid","titre":"Le schéma à retenir : la pyramide (à lire de bas en haut)","items":[["5","Deux méthodes : active, passive"],["4","Quatre critères : Parole, paix, circonstances, conseil"],["3","Mon attitude abandonnée : désirer, m'humilier, croire, accepter le prix"],["2","Les conditions : il a un plan, il veut le montrer, il peut l'accomplir"],["1","Les buts de Dieu : l'aimer, lui ressembler, servir son plan"]]},"table":null,"piege":[["Une porte ouverte prouve toujours que c'est la volonté de Dieu.","Jonas a trouvé un bateau prêt pour Tarsis (Jonas 1.3) : une porte ouverte n'est pas une preuve."],["Dieu cache sa volonté pour que je la cherche longtemps.","Il veut que je la connaisse ; il donne assez de lumière pour avancer par la foi."]],"astuce":"Proverbes 3.5-6 a quatre verbes : « confie-toi », « ne t'appuie pas », « connais-le », « il dirigera ». Mets un geste sur chacun.","jesus":"« Je ne cherche pas ma volonté, mais la volonté de celui qui m'a envoyé » (Jean 5.30). Avant de choisir les douze, il a passé la nuit à prier (Luc 6.12-13).","royaume":"Jésus nous apprend à prier : « que ta volonté soit faite, comme dans le ciel, aussi sur la terre » (Matthieu 6.10). Le citoyen du Royaume applique la volonté de son Roi là où il vit.","mediter":"Y a-t-il une réponse de Dieu que j'ai décidé d'avance de ne pas accepter ?","mots":[["Discerner","Reconnaître ce qui vient de Dieu."],["Méthode active","Avancer prudemment en comptant sur Dieu pour ouvrir ou fermer les portes."],["Méthode passive","Attendre que Dieu confirme avant d'agir."]]},"wb":{"but":"Prendre une vraie décision avec Dieu en suivant la pyramide à cinq niveaux.","ref":"Proverbes 3.5-6","verse":"Confie-toi de tout ton cœur à l’ Éternel, et ne t’appuie pas sur ton intelligence; dans toutes tes voies connais-le, et il dirigera tes sentiers.","q":["Nomme les cinq niveaux de la pyramide, de bas en haut.","Quels sont les trois buts de Dieu pour ma vie (niveau 1) ?","Quelles sont les trois conditions préalables pour comprendre sa volonté (niveau 2) ?","Cite les quatre critères (niveau 4). Lequel juge les trois autres ?","Pourquoi les sentiments et les désirs peuvent-ils tromper ? Quelle question m'aide alors ?","Quelle est la différence entre la méthode active et la méthode passive ? Quel danger guette chacune ?"],"vf":["Dieu cache sa volonté pour que je la cherche longtemps.","Une porte ouverte prouve toujours que c'est la volonté de Dieu.","Le conseil d'un chrétien peut être faux.","Un péché non confessé peut m'empêcher de discerner la volonté de Dieu."],"vfKey":[false,false,true,true],"ex":[{"k":"C1","q":"Redessine la pyramide de mémoire, avec un verset par niveau.","type":"text","rows":6,"hint":"En ligne : décris ou résume ton schéma avec tes mots (tu peux aussi le dessiner sur papier et le montrer à ton mentor)."},{"k":"C2","q":"Écris une décision réelle que tu dois prendre. Passe-la par les quatre critères : la Parole, la paix, les circonstances, le conseil.","type":"table","cols":["La Parole","La paix","Les circonstances","Le conseil"],"rows":5}],"d":["Mes 15 minutes avec Dieu","Prier : « Seigneur, je dis oui d'avance »","Confesser, puis demander conseil à un chrétien mûr","Lire 1 Rois 13.1-26","Je répète mon verset"],"j":"À quel niveau de la pyramide étais-je bloqué, et qu'est-ce qui s'est débloqué ?","go":"Dieu donne toujours le meilleur à ceux qui lui laissent le choix. Confie-toi en lui : il dirigera tes sentiers."},"quiz":[{"type":"tf","q":"Dieu cache sa volonté pour que je la cherche longtemps.","a":false},{"type":"tf","q":"Une porte ouverte prouve toujours que c'est la volonté de Dieu.","a":false},{"type":"tf","q":"Le conseil d'un chrétien peut être faux.","a":true},{"type":"tf","q":"Un péché non confessé peut m'empêcher de discerner la volonté de Dieu.","a":true},{"type":"mcq","q":"Quel mot correspond à cette définition ? « Reconnaître ce qui vient de Dieu. »","opts":["Discerner","Vieil homme","Sacrificature","Premier amour"],"a":0},{"type":"mcq","q":"Quel mot correspond à cette définition ? « Avancer prudemment en comptant sur Dieu pour ouvrir ou fermer les portes. »","opts":["Méthode active","Romains 8","Épreuve","Jourdain"],"a":0},{"type":"mcq","q":"Quel mot correspond à cette définition ? « Attendre que Dieu confirme avant d'agir. »","opts":["Événement","Méthode passive","Le double","Jourdain"],"a":1},{"type":"mcq","q":"Quelle est la référence du verset de la semaine : « Confie-toi de tout ton cœur à l’ Éternel, et ne t’appuie pas sur ton intelligence; dans toutes tes voies conna… »","opts":["Galates 5.16","1 Corinthiens 3.6-7","Jean 15.4","Proverbes 3.5-6"],"a":3},{"type":"tf","q":"Une porte ouverte prouve toujours que c'est la volonté de Dieu.","a":false,"why":"Jonas a trouvé un bateau prêt pour Tarsis (Jonas 1.3) : une porte ouverte n'est pas une preuve."},{"type":"tf","q":"Dieu cache sa volonté pour que je la cherche longtemps.","a":false,"why":"Il veut que je la connaisse ; il donne assez de lumière pour avancer par la foi."}]},{"n":"1-16","ph":1,"etape":"Étape 4 · Grandir","t":"La maturité chrétienne","fil":"Du filet d'eau au fleuve","hook":"Chrétien depuis des années… mais encore au biberon ?","lire":"Hébreux 5.11-14 ; 2 Pierre 3.18","sup":{"phrase":"Ma maturité spirituelle, c'est le degré auquel la perspective de Dieu sur la vie est devenue la mienne.","dec":["La différence entre la communion (« si ») et la maturité (« combien »).","Pourquoi la maturité n'est pas une question de connaissances.","Pas de plateaux, seulement des haltes : grandir jusqu'au ciel."],"pts":[["Communion et maturité","La communion répond à la question « si » : sa vie peut-elle couler à travers moi en ce moment ? La maturité répond à « combien » : quelle quantité de sa vie peut couler à travers moi ?",""],["La maturité n'est pas la connaissance","Elle ne dit pas combien je sais de choses, mais combien j'ai laissé l'Esprit transformer ma manière de voir. Les années de vie chrétienne et la maturité ne sont pas la même chose. Test : devant une contrariété, ma première pensée ressemble-t-elle plus à celle de Dieu qu'il y a un an ?","Jérémie 9.23-24 ; Hébreux 5.12 ; 2 Pierre 3.18"],["Ne plus limiter Dieu","Je limite Dieu quand je dis : « J'ai toujours échoué là, j'échouerai toujours. » Mon regard doit passer de mes capacités aux siennes. Ce n'est pas la faiblesse qui fait obstacle à Dieu, mais une volonté qui résiste.","2 Corinthiens 12.9-10"],["Pas de plateaux, seulement des haltes","La croissance continue jusqu'à mon départ pour le ciel. Le piège : me croire arrivé. Même à la fin de sa vie, Paul courait encore vers le but.","Romains 5.3-5 ; Philippiens 3.12-14"],["Trois images de la maturation","Le filet d'eau qui devient ruisseau, puis fleuve. La brindille qui devient sarment et porte plus de fruit. Le nourrisson qui devient adolescent, puis adulte : d'abord centré sur lui-même, puis sur les autres, puis sur Dieu.","Jean 7.38-39 ; Jean 15.1-2 ; Psaume 73.25"],["Trois âges spirituels","Les petits enfants savent que leurs péchés sont pardonnés. Les jeunes gens sont forts parce que la Parole demeure en eux. Les pères connaissent « celui qui est dès le commencement ». Et le père engendre : il fait des disciples.","1 Jean 2.12-14"],["Une étape, non une arrivée","La phase 1 est un marchepied. Demande au Seigneur qui tu pourrais accompagner à ton tour dans ces seize leçons.","Matthieu 28.19-20"]],"schema":{"type":"grid","titre":"Le schéma à retenir : trois âges dans la foi","cols":3,"items":[["Petit enfant","Mes péchés sont pardonnés ; je connais le Père. Centré sur moi."],["Jeune homme","Fort, car la Parole demeure en moi. Centré sur les autres."],["Père","Je connais Dieu lui-même, et je forme d'autres disciples. Centré sur Dieu."]]},"table":{"titre":"Le chemin parcouru en seize leçons","head":["Leçons","L'étape","Ce que j'ai appris"],"rows":[["1 à 4","Les fondements","La vue d'ensemble, connaître Dieu, le salut, l'anatomie spirituelle"],["5 à 8","La vie nouvelle","La nature divine, le Saint-Esprit, la seigneurie, mes deux natures"],["9 à 12","Demeurer","Demeurer, six images, aujourd'hui, la communion"],["13 à 16","Grandir","Le développement, les épreuves, la volonté de Dieu, la maturité"]]},"piege":[["Plus j'ai d'années de vie chrétienne, plus je suis mûr.","Les Hébreux « vous devriez être des docteurs, vu le temps », et ne l'étaient pas (Hébreux 5.12)."],["Un jour, je n'aurai plus besoin de grandir.","Pas de plateaux, seulement des haltes : on grandit jusqu'au ciel."]],"astuce":"2 Pierre 3.18 : récite-le avec tous les versets des seize leçons, un par jour, comme une révision finale.","jesus":"Il « avançait en sagesse et en stature, et en faveur auprès de Dieu et des hommes » (Luc 2.52). Le but de cette école : « la mesure de la stature de la plénitude du Christ » (Éphésiens 4.13).","royaume":"Le Roi envoie ses citoyens faire des disciples de toutes les nations (Matthieu 28.19-20). Le citoyen mûr forme d'autres citoyens.","mediter":"Suis-je enfant, jeune homme ou père ? Sur qui mon regard se porte-t-il : moi, les autres, ou Dieu ? Qui vais-je accompagner ?","mots":[["Maturité","Le degré auquel la perspective de Dieu est devenue la mienne."],["Halte","Un temps de repos donné par Dieu, avant de reprendre la marche."],["Disciple","Un apprenti de Jésus, qui apprend à lui ressembler et en forme d'autres."]]},"wb":{"but":"Voir la vie comme Dieu la voit, ne plus limiter Dieu à mes capacités, et continuer à grandir jusqu'au ciel.","ref":"2 Pierre 3.18","verse":"Croissez dans la grâce et dans la connaissance de notre Seigneur et Sauveur Jésus Christ. À lui la gloire, et maintenant et jusqu’au jour d’éternité! Amen.","q":["Donne la définition de la maturité spirituelle vue dans la leçon.","Quelle est la différence entre la communion (« si ») et la maturité (« combien ») ?","Pourquoi la maturité ne se mesure-t-elle pas à la quantité de connaissance biblique ?","Selon la mise en garde du manuel, qu'est-ce qui fait obstacle à Dieu : la faiblesse, ou autre chose ?","Que veut dire : « pas de plateaux, seulement des haltes » ?","Quelles sont les trois illustrations de la maturation ? Décris les trois âges de 1 Jean 2.12-14."],"vf":["Plus j'ai d'années de vie chrétienne, plus je suis mûr.","Limiter la puissance de Dieu à mes capacités est une insulte envers lui.","On arrive un jour à un niveau où l'on n'a plus besoin de grandir.","Jésus lui-même a grandi en sagesse et en stature (Luc 2.52)."],"vfKey":[false,true,false,true],"ex":[{"k":"C1","q":"Écris une page : ce que Dieu a changé dans ta manière de voir la vie pendant ces seize leçons.","type":"text","rows":14},{"k":"C2","q":"Complète : « J'ai toujours échoué dans… », puis transforme cette phrase en demande à Dieu.","type":"text","rows":4}],"d":["Mes 15 minutes avec Dieu","Réciter tous mes versets à une personne","Proposer à quelqu'un de commencer la leçon 1-1","Partager au groupe ce que Dieu a changé","Je répète mon verset"],"j":"Suis-je enfant, jeune homme ou père dans la foi ? Sur qui mon regard se porte-t-il : moi, les autres, ou Dieu ?","go":"Ce n'est pas la fin, c'est un marchepied. Du filet au fleuve : continue de grandir, et forme d'autres disciples !"},"quiz":[{"type":"tf","q":"Plus j'ai d'années de vie chrétienne, plus je suis mûr.","a":false},{"type":"tf","q":"Limiter la puissance de Dieu à mes capacités est une insulte envers lui.","a":true},{"type":"tf","q":"On arrive un jour à un niveau où l'on n'a plus besoin de grandir.","a":false},{"type":"tf","q":"Jésus lui-même a grandi en sagesse et en stature (Luc 2.52).","a":true},{"type":"mcq","q":"Quel mot correspond à cette définition ? « Le degré auquel la perspective de Dieu est devenue la mienne. »","opts":["Maturité","Caleb","Enseignable","Temple"],"a":0},{"type":"mcq","q":"Quel mot correspond à cette définition ? « Un temps de repos donné par Dieu, avant de reprendre la marche. »","opts":["Souveraineté","Vision du monde","Halte","Abandon"],"a":2},{"type":"mcq","q":"Quel mot correspond à cette définition ? « Un apprenti de Jésus, qui apprend à lui ressembler et en forme d'autres. »","opts":["Pardon familial","Seigneurie","Disciple","Groupe cible"],"a":2},{"type":"mcq","q":"Quelle est la référence du verset de la semaine : « Croissez dans la grâce et dans la connaissance de notre Seigneur et Sauveur Jésus Christ. À lui la gloire, et … »","opts":["Jean 15.8","Jean 5.24","2 Pierre 3.18","Galates 5.16"],"a":2},{"type":"tf","q":"Plus j'ai d'années de vie chrétienne, plus je suis mûr.","a":false,"why":"Les Hébreux « vous devriez être des docteurs, vu le temps », et ne l'étaient pas (Hébreux 5.12)."},{"type":"tf","q":"Un jour, je n'aurai plus besoin de grandir.","a":false,"why":"Pas de plateaux, seulement des haltes : on grandit jusqu'au ciel."}]},{"n":"2-1","ph":2,"etape":"Formation des mentors","t":"Le discipulat : une suggestion ou un commandement ?","fil":"Le mandat que Jésus nous a laissé","hook":"Jésus a-t-il fait une suggestion… ou donné un ordre ?","lire":"Matthieu 28.18-20 ; 1 Thessaloniciens 2.1-13","sup":{"phrase":"Faire des disciples n'est pas une suggestion de Jésus, c'est son commandement : aider chaque croyant à devenir comme lui, et à en former d'autres.","dec":["La différence entre un converti et un disciple.","Le but, la méthode et les résultats du discipulat.","Le modèle de Paul : une mère, un père, la Parole au centre."],"pts":[["La grande mission","Avant de monter au ciel, Jésus a dit : « Allez donc, et faites disciples toutes les nations. » Si c'est un commandement, nous devons le prendre au sérieux. Et attention : tout disciple est un converti, mais tout converti n'est pas un disciple.","Matthieu 28.18-20"],["Le but du discipulat","Chacun naît avec une tendance à l'indépendance vis-à-vis de Dieu. Au salut, Dieu commence à transformer la personne de l'intérieur ; le rythme dépend de sa compréhension et de son ouverture. Le mentor l'aide à comprendre ce que Dieu fait en elle, pour accélérer ce processus. Mais c'est Dieu qui transforme, pas le mentor.","Romains 12.1-2 ; Colossiens 1.28-29"],["Qu'est-ce qu'un disciple ?","Un élève qui apprend et reçoit l'enseignement de son maître : une connaissance du cœur, pas seulement de la tête. Nous sommes tous disciples de quelque chose. Le discipulat vise la transformation de la vie, non la seule information. Selon Jésus, le disciple renonce à lui-même, demeure dans sa parole, aime les autres, porte du fruit.","Luc 9.23 ; Jean 8.31 ; 13.35 ; 15.8"],["Pourquoi un mentor ?","Donnez un gros manuel d'informatique à cent débutants : quelques-uns s'en sortiront, beaucoup abandonneront en disant « c'est trop difficile ». Beaucoup de chrétiens laissés seuls concluent la même chose de la vie chrétienne. Un mentor aide à apprendre exactement ce dont on a besoin.",""],["Le modèle de Paul","Paul, Silas et Timothée avaient un seul but : plaire à Dieu. Ils prenaient soin des croyants comme une mère, étaient des modèles à imiter, donnaient à chacun l'attention d'un père, et mettaient la Parole de Dieu au centre. Une mère sans père, ou un père sans mère, déforme.","1 Thessaloniciens 2.3-13"],["L'ingrédient manquant","Le discipulat personnel est souvent ce qui manque à l'Église pour une croissance saine. Et rappelle-toi : le disciple ne se souciera pas de ce que tu sais, tant qu'il ne saura pas combien tu te soucies de lui.","Marc 3.14"],["Les résultats attendus","La maturité (tout homme parfait en Christ), la fécondité (beaucoup de fruit) et la reproduction (des fidèles qui enseignent les autres). 2 Timothée 2.2 compte quatre générations : le discipulat n'est accompli que lorsqu'il se transmet.","Colossiens 1.28 ; Jean 15.8 ; 2 Timothée 2.2"]],"schema":{"type":"flow","titre":"Le schéma à retenir : quatre questions","items":[["1","Le but","aider à comprendre ce que Dieu fait"],["2","Le disciple","devenir comme Jésus"],["3","La méthode","un parent spirituel"],["4","Les résultats","maturité, fruit, reproduction"]]},"table":{"titre":"Le modèle de Paul (1 Thessaloniciens 2)","head":["Le trait","Les versets","Pour moi, mentor"],"rows":[["Un seul but : plaire à Dieu","v. 3-6","Je ne cherche pas à être admiré"],["Le soin d'une mère","v. 7-8","Douceur, tendresse, je donne ma vie"],["Un modèle à imiter","v. 9-10","Ma vie enseigne autant que mes paroles"],["L'attention d'un père","v. 11-12","J'exhorte et j'encourage chacun"],["La Parole au centre","v. 13","Je renvoie toujours à la Bible"]]},"piege":[["Tout converti est un disciple.","Tout disciple est un converti, mais tout converti n'est pas un disciple."],["C'est le mentor qui transforme le disciple.","C'est Dieu qui transforme (« soyez transformés ») ; le mentor aide à comprendre."]],"astuce":"Matthieu 28.19-20 : retiens les quatre verbes « Allez », « faites disciples », « baptisant », « enseignant », puis la promesse « je suis avec vous ».","jesus":"Il a prêché aux foules, mais il a formé douze hommes, « pour être avec lui » (Marc 3.14). Sa méthode pour atteindre le monde : quelques-uns, de près, longtemps.","royaume":"« Toute autorité m'a été donnée » : la mission part de l'autorité du Roi. Faire des disciples, c'est former des citoyens qui gardent tout ce que le Roi a commandé.","mediter":"Qui a été pour moi une mère ou un père spirituel ? Pour qui Dieu m'appelle-t-il à l'être ?","mots":[["Disciple","Un apprenti de Jésus, transformé par sa relation avec lui."],["Discipulat","Accompagner un croyant pour qu'il grandisse et devienne comme Jésus."],["Mentor","Celui qui accompagne : un parent spirituel."],["Reproduction spirituelle","Former des disciples qui en forment d'autres."]]},"wb":{"but":"Comprendre que faire des disciples est un commandement de Jésus, et connaître son but, sa méthode et ses résultats.","ref":"Matthieu 28.19-20","verse":"Allez donc, et faites disciples toutes les nations, les baptisant pour le nom du Père et du Fils et du Saint Esprit, leur enseignant à garder toutes les choses que je vous ai commandées. Et voici, moi je suis avec vous tous les jours, jusqu’à la consommation du siècle.","q":["Selon Matthieu 28.18-20, que commande Jésus ? Est-ce une suggestion ou un commandement ? Pourquoi ?","Quelle différence y a-t-il entre un converti et un disciple ?","Quel est le but du discipulat selon le manuel ?","Qu'est-ce qu'un disciple ? Quelle différence entre agir comme Jésus et être comme Jésus ?","Que montre l'analogie du manuel d'informatique ?","Cite les cinq traits du modèle de Paul en 1 Thessaloniciens 2.3-13.","Quels sont les trois résultats attendus du discipulat ?"],"vf":["Tout converti est un disciple.","C'est le mentor qui transforme le disciple.","Le disciple ne se souciera pas de ce que vous savez tant qu'il ne saura pas combien vous vous souciez de lui.","Faire des disciples est réservé aux pasteurs."],"vfKey":[false,false,true,false],"ex":[{"k":"C1","q":"Qui a été pour toi une mère ou un père spirituel ? Qu'a-t-il fait qui t'a aidé à grandir ?","type":"text","rows":5},{"k":"C2","q":"Note-toi de 1 à 5 sur les traits de 1 Thessaloniciens 2 (un seul but, le soin d'une mère, l'exemple, l'attention d'un père, la Parole au centre).","type":"table","cols":["Le trait","Ma note sur 5","Comment grandir"],"rows":5}],"d":["Mes 15 minutes avec Dieu","Prier pour ma liste de trois noms","Lire 1 Thessaloniciens 2.1-13","Remercier la personne qui m'a accompagné","Je répète mon verset"],"j":"Qui Dieu m'appelle-t-il à accompagner, et qu'est-ce qui me retient encore ?","go":"Tu n'es pas seulement un disciple : Jésus t'envoie faire des disciples. Et il est avec toi tous les jours."},"quiz":[{"type":"tf","q":"Tout converti est un disciple.","a":false},{"type":"tf","q":"C'est le mentor qui transforme le disciple.","a":false},{"type":"tf","q":"Le disciple ne se souciera pas de ce que vous savez tant qu'il ne saura pas combien vous vous souciez de lui.","a":true},{"type":"tf","q":"Faire des disciples est réservé aux pasteurs.","a":false},{"type":"mcq","q":"Quel mot correspond à cette définition ? « Un apprenti de Jésus, transformé par sa relation avec lui. »","opts":["Disciple","Pardon familial","Fruit artificiel","Jourdain"],"a":0},{"type":"mcq","q":"Quel mot correspond à cette définition ? « Accompagner un croyant pour qu'il grandisse et devienne comme Jésus. »","opts":["Citerne crevassée","Mentor","Discipulat","Nature divine"],"a":2},{"type":"mcq","q":"Quel mot correspond à cette définition ? « Celui qui accompagne : un parent spirituel. »","opts":["Mentor","Vallée d'Acor","Âme","Tribunal de Christ"],"a":0},{"type":"mcq","q":"Quelle est la référence du verset de la semaine : « Allez donc, et faites disciples toutes les nations, les baptisant pour le nom du Père et du Fils et du Saint E… »","opts":["Galates 5.22-23","2 Pierre 3.18","Jean 15.5","Matthieu 28.19-20"],"a":3},{"type":"tf","q":"Tout converti est un disciple.","a":false,"why":"Tout disciple est un converti, mais tout converti n'est pas un disciple."},{"type":"tf","q":"C'est le mentor qui transforme le disciple.","a":false,"why":"C'est Dieu qui transforme (« soyez transformés ») ; le mentor aide à comprendre."}]},{"n":"2-2","ph":2,"etape":"Formation des mentors","t":"L'aspect pratique de faire des disciples","fil":"Qui accompagner ?","hook":"Qui accompagner ? Le pêcheur sage regarde d'abord où l'eau bouge…","lire":"Luc 6.12-13 ; Jean 4.35","sup":{"phrase":"Je n'accompagne pas n'importe qui : je prie, je discerne ceux que Dieu attire déjà, et je les reçois de sa main.","dec":["Pourquoi prier avant de choisir.","Les quatre groupes cibles et les trois traits d'un futur disciple.","Deux manières de se rencontrer : personnelle et communautaire."],"pts":[["Prier d'abord","Jésus a passé toute la nuit à prier avant de choisir les douze. Je demande à Dieu qui il veut atteindre à travers mon temps, mon énergie et mes biens.","Luc 6.12-13"],["Ne forcer personne","Beaucoup de chrétiens « confortables » ne veulent pas être accompagnés. Insister mène à la frustration, et je néglige peut-être celui qui a faim. Le moment compte : celui qui ne veut pas aujourd'hui voudra peut-être demain. Jésus a aimé le jeune homme riche… et l'a laissé partir.","Marc 10.21-22 ; Jean 6.66-67"],["Groupe 1 : les nouveaux croyants","Des « bébés chrétiens » qui ont besoin de quelqu'un à leurs côtés. La période du « premier amour » est la meilleure fenêtre : ils ont faim et sont prêts à apprendre. Sinon, beaucoup imiteront le mode de vie des croyants plus anciens.",""],["Groupe 2 : les chrétiens au « désert »","Une vie de défaite, souvent pendant des années : manque de paix, souci, colère, critique… Dieu est là pour leurs plans, et ils s'appuient sur leur propre intelligence. Une crise permise par Dieu peut les humilier et les rendre prêts à reconnaître sa seigneurie.","Proverbes 3.5-6"],["Groupes 3 et 4 : ceux qui stagnent, ceux qui veulent être équipés","Les premiers ont reconnu sa seigneurie mais ne savent pas demeurer constamment en Christ. Les seconds ont faim d'aller plus loin et veulent apprendre à accompagner d'autres.",""],["Trois traits à chercher","La faim spirituelle : a-t-il soif de Dieu ? Un esprit enseignable : se voit-il comme un apprenti ? La fiabilité : la croissance est-elle une priorité pour lui ? Attention : c'est mauvais signe s'il pense me rendre service. La faim vient de Dieu : je cherche ceux qu'il attire déjà.","Matthieu 5.6 ; Jean 6.44 ; 2 Timothée 2.2"],["Deux méthodes de mise en relation","Personnelle : sous l'impulsion de l'Esprit, je crée moi-même la relation. Communautaire : le pasteur ou le coordinateur me signale une personne, je prie pour savoir si c'est la bonne, je prends contact, et j'informe le coordinateur. Dans les deux cas : la direction de l'Esprit. Astuce : un café pour faire connaissance, sans pression.",""]],"schema":{"type":"table","titre":"Le schéma à retenir : quatre groupes cibles","head":["Groupe","Qui ?","Leçons conseillées"],"rows":[["G1","Les nouveaux croyants","Toute la phase 1, dans l'ordre"],["G2","Les chrétiens au « désert »","1-7, 1-12, 1-14"],["G3","Ceux qui stagnent","Demeurer : 1-9 à 1-12"],["G4","Ceux qui veulent être équipés","La phase 2 (après la phase 1)"]]},"table":{"titre":"Trois traits d'un futur disciple","head":["Le trait","La question à me poser"],"rows":[["La faim spirituelle","A-t-il faim et soif de Dieu ? Le cherche-t-il ?"],["Un esprit enseignable","Est-il ouvert à Dieu et à un mentor ? Revient-il avec des questions ?"],["La fiabilité","Applique-t-il ce qu'il apprend ? La croissance est-elle une priorité ?"]]},"piege":[["Il faut convaincre tout le monde d'être accompagné.","Vouloir former quelqu'un qui n'est pas intéressé mène à la frustration ; je prie et je reste disponible."],["La méthode communautaire se passe de la direction de l'Esprit.","Les deux méthodes passent par la direction du Saint-Esprit : c'est essentiel."]],"astuce":"Luc 6.12-13 raconte une scène : la montagne, la nuit de prière, l'appel au matin. Récite-le en revoyant la scène dans ta tête.","jesus":"Il a passé la nuit à prier avant de choisir les douze (Luc 6.12-13). Puis il a appelé chacun par son nom : « Suis-moi. »","royaume":"Le Roi désigne ses ambassadeurs. Le mentor ne recrute pas pour lui-même : il discerne ceux que le Roi lui confie.","mediter":"Qui, autour de moi, a faim, est enseignable et fiable ? L'ai-je présenté à Dieu dans la prière ?","mots":[["Groupe cible","Une catégorie de croyants que Dieu peut me confier."],["Premier amour","La période de faim et d'ouverture qui suit la conversion."],["Enseignable","Ouvert à apprendre de Dieu et d'un mentor."]]},"wb":{"but":"Savoir qui accompagner : prier, reconnaître les quatre groupes cibles et les trois traits d'un futur disciple.","ref":"Luc 6.12-13","verse":"Or il arriva, en ces jours-là, qu’il s’en alla sur une montagne pour prier. Et il passa toute la nuit à prier Dieu. Et quand le jour fut venu, il appela ses disciples. Et en ayant choisi douze d’entre eux, lesquels il nomma aussi apôtres.","q":["Pourquoi prier avant de choisir la personne à accompagner (Luc 6.12-13) ?","Pourquoi ne pas insister avec une personne qui n'est pas intéressée ? Donne trois raisons.","Décris les quatre groupes cibles.","Pourquoi la période du « premier amour » est-elle la meilleure fenêtre pour accompagner un nouveau croyant ?","Quels symptômes peuvent montrer qu'un chrétien vit au « désert » ?","Quels sont les trois traits à chercher chez un futur disciple ?","Quelles sont les deux méthodes de mise en relation ? Qu'ont-elles en commun ?"],"vf":["Il faut convaincre tout le monde d'être accompagné.","Un nouveau croyant non accompagné imite souvent le mode de vie des croyants plus anciens.","C'est mauvais signe si la personne pense me rendre service.","La méthode communautaire n'a pas besoin de la direction du Saint-Esprit."],"vfKey":[false,true,true,false],"ex":[{"k":"C1","q":"Place les personnes de ta liste dans les quatre groupes cibles.","type":"table","cols":["G1 Nouveaux","G2 Désert","G3 Stagnation","G4 À équiper"],"rows":5},{"k":"C2","q":"Pour chaque personne de ta liste, réponds aux trois questions.","type":"table","cols":["Le nom","A-t-il faim ?","Est-il enseignable ?","Est-il fiable ?"],"rows":5}],"d":["Mes 15 minutes avec Dieu","Prier pour ma liste et demander un nom confirmé","Proposer un café si le Seigneur confirme","Parler au coordinateur du discipulat (s'il y en a un)","Je répète mon verset"],"j":"Quelle personne le Seigneur met-il sur mon cœur, et pourquoi elle ?","go":"Dieu prépare déjà des cœurs affamés. Ta part : prier, discerner, et te rendre disponible."},"quiz":[{"type":"tf","q":"Il faut convaincre tout le monde d'être accompagné.","a":false},{"type":"tf","q":"Un nouveau croyant non accompagné imite souvent le mode de vie des croyants plus anciens.","a":true},{"type":"tf","q":"C'est mauvais signe si la personne pense me rendre service.","a":true},{"type":"tf","q":"La méthode communautaire n'a pas besoin de la direction du Saint-Esprit.","a":false},{"type":"mcq","q":"Quel mot correspond à cette définition ? « Une catégorie de croyants que Dieu peut me confier. »","opts":["Épreuve","Obéissance partielle","Citerne crevassée","Groupe cible"],"a":3},{"type":"mcq","q":"Quel mot correspond à cette définition ? « La période de faim et d'ouverture qui suit la conversion. »","opts":["Premier amour","Corps","Intimité spirituelle","Disciple"],"a":0},{"type":"mcq","q":"Quel mot correspond à cette définition ? « Ouvert à apprendre de Dieu et d'un mentor. »","opts":["Enseignable","Faciliter","Esprit","Redevable"],"a":0},{"type":"mcq","q":"Quelle est la référence du verset de la semaine : « Or il arriva, en ces jours-là, qu’il s’en alla sur une montagne pour prier. Et il passa toute la nuit à prier … »","opts":["Jean 15.9","Luc 6.12-13","Galates 5.16","Deutéronome 6.23"],"a":1},{"type":"tf","q":"Il faut convaincre tout le monde d'être accompagné.","a":false,"why":"Vouloir former quelqu'un qui n'est pas intéressé mène à la frustration ; je prie et je reste disponible."},{"type":"tf","q":"La méthode communautaire se passe de la direction de l'Esprit.","a":false,"why":"Les deux méthodes passent par la direction du Saint-Esprit : c'est essentiel."}]},{"n":"2-3","ph":2,"etape":"Formation des mentors","t":"Directives pour accompagner une personne","fil":"Le mode d'emploi d'une rencontre","hook":"Le meilleur guide de montagne ? Celui dont tu n'as plus besoin.","lire":"Luc 24.13-35 ; 1 Corinthiens 3.6-7","sup":{"phrase":"J'accompagne la personne à son rythme, avec la prière, la Parole et des questions ouvertes, pour qu'elle dépende du Saint-Esprit, et non de moi.","dec":["L'organisation pratique : avec qui, quand, combien de temps, où.","Les cinq temps d'une rencontre et l'art des questions ouvertes.","Rester centré : ni simple amitié, ni séance de plaintes."],"pts":[["Le cœur, non le comportement","Le mentorat ne vise pas à « manipuler » le comportement, mais la relation avec le Seigneur : laisser Dieu transformer la pensée de l'intérieur. Pour les croyants de longue date, les leçons révèlent aussi les lacunes à combler.",""],["La logistique","Les hommes avec les hommes, les femmes avec les femmes, ou un couple avec un couple. Environ une fois par semaine, une heure et demie. Pour la phase 1, au moins trois à neuf mois. Dans un lieu calme : chez l'un de vous, un café à une heure creuse, l'église, un parc. Les leçons se suivent dans l'ordre.",""],["Le but final : qu'il dépende de l'Esprit, pas de moi","J'explique la Parole, je laisse la personne poser ses questions et partager ses luttes. Je transmets des principes de vie, pas seulement des connaissances. Jean-Baptiste disait : « Il faut que lui croisse, et que moi je diminue. »","Jean 3.30 ; 1 Corinthiens 2.5"],["Faciliter : poser des questions ouvertes","Faciliter, c'est poser des questions pour que la personne arrive elle-même à la conclusion. Cela laisse le Saint-Esprit agir, et révèle les lacunes de sa compréhension. Sur la route d'Emmaüs, Jésus a d'abord demandé : « Quels sont ces discours ? »","Luc 24.15-17, 27, 32"],["Au rythme de la personne","Pas besoin de finir une leçon par rencontre : ce qui compte, c'est la croissance, pas la vitesse. Trois astuces : la personne note où l'on s'est arrêté ; on n'impose pas de devoirs, on invite à méditer les versets ; si elle a lu en avance, on relit quand même ensemble.","1 Corinthiens 3.6-7 ; Jean 16.12"],["Rester centré","Construire la relation est important, mais elle ne doit pas devenir une simple amitié, ni une « séance de lamentations ». Quand la personne se plaint ou demande conseil, je demande : « As-tu prié à ce sujet ? » Je suis prudent avec mes opinions, et j'écoute attentivement.","Philippiens 4.6 ; Jacques 1.5"],["La Bible, et la relation dans la durée","Toujours une Bible : apprends-lui à lire chaque verset dans son chapitre et à demander à l'Esprit comment il s'applique. Sois disponible dans la semaine, envoie un verset, prie pour lui, et continue de suivre sa croissance après la fin du parcours.",""]],"schema":{"type":"flow","titre":"Le schéma à retenir : les cinq temps d'une rencontre","items":[["1","Prier","simple et bref"],["2","Lire","à tour de rôle, à voix haute"],["3","Discuter","avec des questions ouvertes"],["4","Partager","ce que Dieu fait en moi"],["5","Prier","pour lui, et avec lui"]]},"table":{"titre":"L'organisation pratique","head":["La question","La réponse du manuel"],"rows":[["Avec qui ?","Homme avec homme, femme avec femme, couple avec couple"],["À quel rythme ?","Environ une fois par semaine, une heure et demie"],["Combien de temps ?","Pour la phase 1, au moins trois à neuf mois"],["Où ?","Un lieu calme, avec peu de distractions"]]},"piege":[["Il faut terminer une leçon à chaque rencontre.","Ce n'est pas la vitesse qui compte, mais la croissance."],["On peut sauter un passage que la personne a déjà lu seule.","On le relit ensemble en lui demandant ce que Dieu lui a montré : l'Esprit fait souvent ressortir encore plus."]],"astuce":"1 Corinthiens 3.6-7 : trois personnages, trois verbes. « Moi, j'ai planté ; Apollos a arrosé ; Dieu a donné l'accroissement. »","jesus":"Il posait des questions : « Et vous, qui dites-vous que je suis ? » (Matthieu 16.15). Il marchait avec ses disciples, mangeait avec eux, priait devant eux.","royaume":"Un royaume se transmet par la culture plus que par les cours : on apprend à vivre en voyant vivre. Le mentor transmet la culture du Royaume par sa manière d'être.","mediter":"Est-ce que je parle plus que je n'écoute ? Est-ce que je donne des conseils, ou est-ce que je renvoie vers Dieu ?","mots":[["Faciliter","Poser des questions qui aident la personne à découvrir elle-même la vérité."],["Question ouverte","Une question qui ne se répond pas par oui ou non (« Qu'est-ce qui… ? », « Comment… ? »)."],["Manipulation du comportement","Changer l'extérieur sans transformation du cœur."]]},"wb":{"but":"Savoir organiser les rencontres et les conduire : prière, Parole, questions ouvertes, au rythme de la personne.","ref":"1 Corinthiens 3.6-7","verse":"Moi, j’ai planté, Apollos a arrosé; mais Dieu a donné l’accroissement. De sorte que ni celui qui plante n’est rien, ni celui qui arrose, mais Dieu qui donne l’accroissement.","q":["Sur quoi porte l'accent du mentorat, et quelle erreur évite-t-il ?","Logistique : avec qui, à quel rythme, pendant combien de temps et où se rencontrer ?","Quel est le but final du mentor : de quoi la personne doit-elle dépendre, et de quoi être indépendante ?","Qu'est-ce que faciliter ? Pourquoi poser des questions ouvertes ?","Quels sont les cinq temps d'une rencontre ?","Cite les trois astuces du manuel sur le rythme.","Que répondre quand la personne demande un conseil ou se plaint ?"],"vf":["Il faut terminer une leçon à chaque rencontre.","On peut sauter un passage que la personne a déjà lu seule.","Le mentor partage aussi ses propres sujets de prière.","Normalement, les hommes accompagnent des hommes et les femmes des femmes."],"vfKey":[false,false,true,true],"ex":[{"k":"C1","q":"Écris cinq questions ouvertes pour la leçon 1-1 (« Qu'est-ce qui… ? », « Comment… ? »).","type":"text","rows":6},{"k":"C2","q":"Transforme trois conseils que tu donnerais en questions qui renvoient vers Dieu.","type":"table","cols":["Le conseil que je donnerais","La question qui renvoie vers Dieu"],"rows":5}],"d":["Mes 15 minutes avec Dieu","Fixer le jour, l'heure et le lieu avec la personne","Préparer la leçon 1-1 (prière, questions, témoignage)","Lui envoyer un verset dans la semaine","Je répète mon verset"],"j":"Est-ce que je parle plus que je n'écoute ? Qu'est-ce que je veux changer ?","go":"Comme Jésus sur la route d'Emmaüs : marche à côté, pose des questions, ouvre les Écritures. Dieu fera croître."},"quiz":[{"type":"tf","q":"Il faut terminer une leçon à chaque rencontre.","a":false},{"type":"tf","q":"On peut sauter un passage que la personne a déjà lu seule.","a":false},{"type":"tf","q":"Le mentor partage aussi ses propres sujets de prière.","a":true},{"type":"tf","q":"Normalement, les hommes accompagnent des hommes et les femmes des femmes.","a":true},{"type":"mcq","q":"Quel mot correspond à cette définition ? « Poser des questions qui aident la personne à découvrir elle-même la vérité. »","opts":["Réconciliation","Faciliter","Romains 8","Jourdain"],"a":1},{"type":"mcq","q":"Quel mot correspond à cette définition ? « Une question qui ne se répond pas par oui ou non (« Qu'est-ce qui… ? », « Comment… ? »). »","opts":["Sceau","Sacrifice spirituel","Halte","Question ouverte"],"a":3},{"type":"mcq","q":"Quel mot correspond à cette définition ? « Changer l'extérieur sans transformation du cœur. »","opts":["Manipulation du comportement","Désert","Orgueil spirituel","Conforme à son image"],"a":0},{"type":"mcq","q":"Quelle est la référence du verset de la semaine : « Moi, j’ai planté, Apollos a arrosé; mais Dieu a donné l’accroissement. De sorte que ni celui qui plante n’est … »","opts":["Job 1.21","Jean 15.9","1 Jean 1.9","1 Corinthiens 3.6-7"],"a":3},{"type":"tf","q":"Il faut terminer une leçon à chaque rencontre.","a":false,"why":"Ce n'est pas la vitesse qui compte, mais la croissance."},{"type":"tf","q":"On peut sauter un passage que la personne a déjà lu seule.","a":false,"why":"On le relit ensemble en lui demandant ce que Dieu lui a montré : l'Esprit fait souvent ressortir encore plus."}]},{"n":"2-4","ph":2,"etape":"Formation des mentors","t":"L'essentiel pour faire des disciples","fil":"Trois rôles, trois obstacles","hook":"Un tabouret à trois pieds tient sur tous les sols. Quels sont les trois pieds du discipulat ?","lire":"Actes 8.26-39 ; 1 Corinthiens 3.9","sup":{"phrase":"Autour du disciple, trois acteurs travaillent ensemble : le Saint-Esprit fait ce que je ne peux pas faire, je fais ma part, et la Parole guide.","dec":["Ce que fait le Saint-Esprit, et ce que fait le mentor.","Le rôle du matériel : bâtir une maison dans l'ordre.","Les trois obstacles à la reproduction spirituelle, et leurs remèdes."],"pts":[["Le Saint-Esprit","Il orchestre les rencontres, crée la faim spirituelle, guide le processus, donne sagesse et discernement à la personne. Le mentor ne peut ni créer la faim, ni convaincre, ni transformer : il est libéré d'un poids qui n'est pas le sien.","Jean 6.44 ; Jean 16.13"],["Le mentor","Il prie et regarde au Seigneur avec attente ; il demeure en communion avec l'Esprit ; il étudie la Parole ; il se rend disponible ; il coopère avec l'Esprit, comme partenaire de son œuvre. « Nous sommes collaborateurs de Dieu. »","Jean 15.5 ; 2 Timothée 2.21 ; 1 Corinthiens 3.9"],["Un partenariat, non une délégation","L'Esprit ne fait pas mon travail à ma place, et je ne fais pas le sien. Philippe en Actes 8 : l'Esprit dit « Approche-toi », Philippe court, pose une question, puis annonce Jésus à partir du texte.","Actes 8.26-39"],["Le matériel","Il conduit la personne à regarder au Seigneur dans sa Parole ; il avance de façon progressive et ordonnée, comme on bâtit une maison ; il vise la relation avec Dieu, non le comportement extérieur. Il ne remplace jamais la Bible.","2 Timothée 3.16-17"],["Trois obstacles à la reproduction","Comme dans le domaine physique : l'immaturité (chrétien récent, ou qui n'a pas grandi), un problème de santé spirituelle (des questions non réglées avec le Seigneur, une compréhension faussée), un manque d'intimité (l'agitation qui vole le temps avec le Seigneur).","Hébreux 5.12"],["Les remèdes sont dans la phase 1","L'immaturité se soigne par la croissance (leçon 1-16). La santé, par la confession et la vérité (leçons 1-3, 1-8, 1-12). L'intimité, par le temps avec lui : demeurer (leçons 1-9 à 1-11). Le mentor examine d'abord ces trois obstacles en lui-même.","Luc 10.41-42"]],"schema":{"type":"grid","titre":"Le schéma à retenir : trois rôles autour du disciple","cols":3,"items":[["Le Saint-Esprit","Il orchestre, crée la faim, guide, donne la sagesse."],["Le mentor (moi)","Je prie, je demeure, j'étudie, je suis disponible, je coopère."],["Le matériel","Il conduit à la Parole, avance dans l'ordre, vise la relation."]]},"table":{"titre":"Trois obstacles et leurs remèdes","head":["L'obstacle","Dans ma vie spirituelle","Le remède"],"rows":[["L'immaturité","Chrétien récent, ou qui n'a pas grandi","Grandir (leçon 1-16)"],["La santé","Des questions non réglées, une compréhension faussée","Confesser, corriger (1-3, 1-8, 1-12)"],["L'intimité","L'agitation vole mon temps avec Dieu","Demeurer (1-9 à 1-11)"]]},"piege":[["Le mentor peut créer la faim spirituelle chez quelqu'un.","C'est le Père qui attire (Jean 6.44) ; je cherche ceux qu'il attire déjà."],["Le matériel remplace la Bible.","Le matériel conduit à la Parole : c'est elle qui transforme."]],"astuce":"1 Corinthiens 3.9 est court : dis-le avant chaque rencontre de mentorat, comme une prière.","jesus":"Lui-même dépendait de l'Esprit : « plein de l'Esprit Saint… il fut mené par l'Esprit » (Luc 4.1). Et il se retirait pour prier (Luc 5.16).","royaume":"Le Royaume fonctionne par délégation : le Roi donne à ses citoyens son Esprit, comme un gouverneur intérieur, et ses lois, la Parole. Le citoyen collabore.","mediter":"Est-ce que je compte vraiment sur l'Esprit, ou sur ma préparation ? Combien de temps ai-je passé seul avec le Seigneur cette semaine ?","mots":[["Collaborateur de Dieu","Celui qui travaille avec Dieu, dans son œuvre."],["Matériel","Les leçons qui guident l'accompagnement, toujours au service de la Bible."],["Intimité spirituelle","Le temps seul avec le Seigneur, sans agitation."]]},"wb":{"but":"Connaître le rôle du Saint-Esprit, du mentor et du matériel, et les trois obstacles à la reproduction spirituelle.","ref":"1 Corinthiens 3.9","verse":"Car nous sommes collaborateurs de Dieu; vous êtes le labourage de Dieu, l’édifice de Dieu.","q":["Quels sont les trois acteurs autour du disciple ?","Cite les quatre choses que le Saint-Esprit fait dans le discipulat.","Cite les cinq responsabilités du mentor.","Quels sont les trois rôles du matériel ? Pourquoi le manuel parle-t-il de bâtir une maison ?","Quels sont les trois obstacles à la reproduction physique, et leurs équivalents spirituels ?","Quel remède la phase 1 donne-t-elle pour chacun des trois obstacles ?"],"vf":["Le mentor peut créer lui-même la faim spirituelle chez quelqu'un.","Le mentor doit lui-même demeurer dans la communion avec le Saint-Esprit.","Le matériel remplace la Bible.","Le manque d'intimité avec le Seigneur peut empêcher la reproduction spirituelle."],"vfKey":[false,true,false,true],"ex":[{"k":"C1","q":"Redessine de mémoire le schéma des trois rôles autour du disciple.","type":"text","rows":6,"hint":"En ligne : décris ou résume ton schéma avec tes mots (tu peux aussi le dessiner sur papier et le montrer à ton mentor)."},{"k":"C2","q":"Note-toi sur les cinq responsabilités du mentor (prier, demeurer, étudier, être disponible, coopérer).","type":"table","cols":["La responsabilité","Ma note sur 5","Ce que je vais faire"],"rows":5}],"d":["Mes 15 minutes avec Dieu","Mon temps d'intimité quotidien, protégé","Avant chaque rencontre : « Saint-Esprit, fais ce que je ne peux pas faire »","Régler une question en suspens avec le Seigneur","Je répète mon verset"],"j":"Lequel des trois obstacles me menace le plus, et que vais-je faire cette semaine ?","go":"Tu n'es pas seul dans cette œuvre : l'Esprit fait ce que tu ne peux pas faire. Tu es collaborateur de Dieu !"},"quiz":[{"type":"tf","q":"Le mentor peut créer lui-même la faim spirituelle chez quelqu'un.","a":false},{"type":"tf","q":"Le mentor doit lui-même demeurer dans la communion avec le Saint-Esprit.","a":true},{"type":"tf","q":"Le matériel remplace la Bible.","a":false},{"type":"tf","q":"Le manque d'intimité avec le Seigneur peut empêcher la reproduction spirituelle.","a":true},{"type":"mcq","q":"Quel mot correspond à cette définition ? « Celui qui travaille avec Dieu, dans son œuvre. »","opts":["Émonder","Réconciliation","Collaborateur de Dieu","Sanctification"],"a":2},{"type":"mcq","q":"Quel mot correspond à cette définition ? « Les leçons qui guident l'accompagnement, toujours au service de la Bible. »","opts":["Cep","Matériel","Manipulation du comportement","Sanctification"],"a":1},{"type":"mcq","q":"Quel mot correspond à cette définition ? « Le temps seul avec le Seigneur, sans agitation. »","opts":["Pardonner","Intimité spirituelle","Romains 8","Corps"],"a":1},{"type":"mcq","q":"Quelle est la référence du verset de la semaine : « Car nous sommes collaborateurs de Dieu; vous êtes le labourage de Dieu, l’édifice de Dieu. »","opts":["1 Corinthiens 3.9","1 Corinthiens 3.6-7","Romains 12.1","Galates 2.20"],"a":0},{"type":"tf","q":"Le mentor peut créer la faim spirituelle chez quelqu'un.","a":false,"why":"C'est le Père qui attire (Jean 6.44) ; je cherche ceux qu'il attire déjà."},{"type":"tf","q":"Le matériel remplace la Bible.","a":false,"why":"Le matériel conduit à la Parole : c'est elle qui transforme."}]},{"n":"2-5","ph":2,"etape":"Formation des mentors","t":"Sujets de discussion","fil":"Examiner mon cœur, puis commencer","hook":"« Je ne suis pas prêt »… Et si Dieu n'attendait pas que tu le sois ?","lire":"Exode 4.10-12 ; 2 Timothée 2.2","sup":{"phrase":"Mes hésitations regardent à mes capacités ; la foi regarde à celles de Dieu. Les outils sont en place : qui vais-je accompagner ?","dec":["Pourquoi tant de chrétiens hésitent à accompagner, et ce que Dieu leur répond.","La force de l'exemple, et les crises que Dieu permet.","Le portrait d'un disciple biblique, et mes dons spirituels."],"pts":[["Pourquoi hésiter ?","« Je ne suis pas à la hauteur », « ce n'est pas mon don », « pas assez de connaissance », « je ne veux pas être hypocrite », « trop occupé »… Ces raisons regardent à nos capacités, non à celles de Dieu. Combien de parents auraient des enfants s'ils attendaient de se sentir prêts ?","Exode 4.10-12"],["Ce que Dieu répond","À Moïse : « Je serai avec toi. » Notre capacité vient de Dieu. Faire des disciples est un commandement donné à tous. On transmet d'abord ce qu'on a vécu. Un mentor n'est pas parfait : il est en chemin.","Exode 3.12 ; 2 Corinthiens 3.5 ; Philippiens 3.12"],["La force de l'exemple","Quel chrétien m'a aidé par sa manière de vivre ? Quel exemple m'a blessé ? Qu'apprendrait un nouveau croyant en regardant ma vie pendant une semaine ?","Philippiens 4.9"],["Les résultats d'un discipulat sain","Le nouveau croyant découvre les buts de Dieu et la manière dont il fait grandir. Chaque chrétien est unique : seul l'Esprit dirige la croissance. Notre intention : raccourcir le temps qu'il faut pour apprendre à coopérer avec lui.",""],["De la confiance en soi à la confiance en Dieu","Les chrétiens plus anciens qui n'ont pas reconnu sa seigneurie résistent souvent au changement. Dieu se sert de la persécution et des crises pour accélérer ce passage. Coordonner la crise est l'affaire de l'Esprit ; la mienne est d'être disponible.","Proverbes 3.5-6 ; Psaume 119.67"],["Un disciple biblique","Il renonce à lui-même, demeure dans la Parole, aime les autres, porte du fruit.","Luc 9.23 ; Jean 8.31 ; 13.35 ; 15.8"],["Mes dons spirituels","Lesquels ? Comment le sais-tu ? Pour qui Dieu t'emploie-t-il ? Quelqu'un l'a-t-il remarqué ? Chacun a reçu un don, pour servir les autres.","1 Pierre 4.10 ; 1 Corinthiens 12.7"]],"schema":{"type":"grid","titre":"Le schéma à retenir : le portrait du disciple selon Jésus","cols":4,"items":[["Luc 9.23","Il renonce à lui-même"],["Jean 8.31","Il demeure dans la Parole"],["Jean 13.35","Il aime les autres"],["Jean 15.8","Il porte du fruit"]]},"table":{"titre":"Mes raisons d'hésiter, et ce que Dieu répond","head":["Ce que je dis","Ce que Dieu répond"],"rows":[["« Je ne suis pas à la hauteur »","« Je serai avec toi » (Exode 3.12)"],["« Ce n'est pas mon don »","C'est un commandement pour tous (Matthieu 28.19)"],["« Pas assez de connaissance »","Transmets ce que tu as vécu (1 Jean 1.3)"],["« Je ne veux pas être hypocrite »","Personne n'est arrivé ; on est en chemin (Philippiens 3.12)"],["« Je suis trop occupé »","C'est une question de priorités"]]},"piege":[["Il faut se sentir parfaitement prêt avant d'accompagner quelqu'un.","Dieu envoie ceux qui doutent encore, avec sa présence (Matthieu 28.17-20)."],["C'est au mentor de provoquer des crises.","Les crises sont l'affaire du Saint-Esprit ; ma part est d'être disponible."]],"astuce":"2 Timothée 2.2 : compte les quatre générations sur tes doigts (Paul, Timothée, les hommes fidèles, les autres) en récitant le verset.","jesus":"Il a confié sa mission à onze hommes encore hésitants : « quelques-uns doutèrent » (Matthieu 28.17). Il les a envoyés quand même, avec sa présence.","royaume":"Le Royaume s'étend par multiplication : chaque citoyen formé en forme d'autres. Le Roi ne compte pas sur des experts, mais sur des citoyens fidèles (2 Timothée 2.2).","mediter":"Qu'est-ce qui m'empêche encore de commencer ? Quel nom Dieu a-t-il mis sur mon cœur pendant cette phase ?","mots":[["Envoi","Le moment où Jésus envoie ses disciples faire des disciples."],["Fidèle","Celui sur qui l'on peut compter : le critère de Paul pour choisir."]]},"wb":{"but":"Examiner mon cœur avant d'accompagner quelqu'un, puis commencer.","ref":"2 Timothée 2.2","verse":"Les choses que tu as entendues de moi devant plusieurs témoins, confie-les à des hommes fidèles qui soient capables d’instruire aussi les autres.","q":["Pourquoi certains chrétiens hésitent-ils à accompagner un nouveau croyant ? Sur quoi reposent ces raisons ?","Que montre la comparaison avec les parents qui attendraient de se sentir prêts ?","Comment l'exemple d'autres chrétiens t'a-t-il marqué, en bien ou en mal ?","Quels résultats spirituels attendre d'un discipulat sain ?","Comment Dieu se sert-il des crises ? Quelle est ma responsabilité ?","Comment décrirais-tu un disciple biblique (Luc 9.23 ; Jean 8.31 ; 13.35 ; 15.8) ?","Quels sont tes dons spirituels, et comment le sais-tu ?"],"vf":["Il faut se sentir parfaitement prêt avant d'accompagner quelqu'un.","Mon exemple enseigne autant que mes paroles.","C'est au mentor de provoquer des crises dans la vie des autres.","Chaque croyant est un faiseur de disciples potentiel."],"vfKey":[false,true,false,true],"ex":[{"k":"C1","q":"Écris ta propre raison d'hésiter, puis ce que Dieu te répond, avec un verset.","type":"table","cols":["Ma raison d'hésiter","Ce que Dieu me répond"],"rows":5},{"k":"C2","q":"Écris ta définition d'un disciple biblique en une phrase, puis le nom de la personne que tu vas accompagner et la date de votre premier rendez-vous.","type":"text","rows":5}],"d":["Mes 15 minutes avec Dieu","Tenir mon premier rendez-vous et commencer la leçon 1-1","Prier chaque jour pour la personne","Noter ce que Dieu m'apprend à moi","Je répète mon verset"],"j":"Maintenant que les outils sont en place, qui Dieu me conduit-il à accompagner ?","go":"Les outils sont en place. Allez donc, faites des disciples : Jésus est avec toi tous les jours !"},"quiz":[{"type":"tf","q":"Il faut se sentir parfaitement prêt avant d'accompagner quelqu'un.","a":false},{"type":"tf","q":"Mon exemple enseigne autant que mes paroles.","a":true},{"type":"tf","q":"C'est au mentor de provoquer des crises dans la vie des autres.","a":false},{"type":"tf","q":"Chaque croyant est un faiseur de disciples potentiel.","a":true},{"type":"mcq","q":"Quel mot correspond à cette définition ? « Le moment où Jésus envoie ses disciples faire des disciples. »","opts":["Valeur éternelle","Seigneur","Voile","Envoi"],"a":3},{"type":"mcq","q":"Quel mot correspond à cette définition ? « Celui sur qui l'on peut compter : le critère de Paul pour choisir. »","opts":["Homme nouveau","Interdit","Événement","Fidèle"],"a":3},{"type":"mcq","q":"Quelle est la référence du verset de la semaine : « Les choses que tu as entendues de moi devant plusieurs témoins, confie-les à des hommes fidèles qui soient cap… »","opts":["Galates 5.22-23","Matthieu 28.19-20","2 Timothée 2.2","Deutéronome 6.23"],"a":2},{"type":"tf","q":"Il faut se sentir parfaitement prêt avant d'accompagner quelqu'un.","a":false,"why":"Dieu envoie ceux qui doutent encore, avec sa présence (Matthieu 28.17-20)."},{"type":"tf","q":"C'est au mentor de provoquer des crises.","a":false,"why":"Les crises sont l'affaire du Saint-Esprit ; ma part est d'être disponible."}]},{"n":"3-1","ph":3,"etape":"Étape 1 · La vie chrétienne approfondie","t":"La vie chrétienne résumée","fil":"Toute la vie chrétienne en dix-sept points","hook":"Dieu est-il ton « numéro d'urgence »… ou ton Père de chaque jour ?","lire":"Jean 10.10 ; Galates 5.16-25","sup":{"phrase":"Le salut est un commencement : Dieu me donne son Esprit pour vivre avec lui une communion qui peut se rompre, mais qui se rétablit aussitôt par la confession.","dec":["Pourquoi l'homme sans Dieu ne produit qu'un fruit artificiel.","Mes deux natures, et l'Esprit qui ne me quittera jamais.","Les symptômes d'une communion rompue, et le chemin de la restauration."],"pts":[["Le salut, plus qu'échapper à l'enfer","Dieu a créé l'homme esprit, âme et corps, pour vivre en relation avec lui. Le salut ne me sauve pas seulement de l'enfer : il m'ouvre une vie abondante, ici et maintenant.","Jean 10.10 ; Genèse 2.7"],["La racine du problème","Satan présente Dieu comme quelqu'un en qui on ne peut pas avoir confiance. Adam et Ève l'ont cru et ont cherché le bonheur sans lui. Sans Dieu, l'homme peut faire de bonnes choses, mais le mauvais arbre ne produit pas de bon fruit : c'est un fruit artificiel.","Romains 5.12 ; Matthieu 7.17-18"],["Une vie nouvelle, une Personne","À la nouvelle naissance, je reçois le Saint-Esprit, une Personne et non une force. C'est un commencement, non une fin.","Jean 3.3-6 ; 1 Corinthiens 6.19"],["Deux nouvelles, deux bonnes et deux mauvaises","Bonne nouvelle : je participe à la nature divine, et l'Esprit ne me quittera jamais. Mauvaise nouvelle : ma vieille nature n'est « pas le moins du monde améliorée », et elle restera jusqu'à ma mort. La Loi révèle son caractère.","2 Pierre 1.4 ; Romains 7.18"],["Le reconnaître, puis demeurer","Jésus est déjà mon Seigneur : je le reconnais. Puis je demeure en lui comme un objet repose sur une main ouverte : sans effort pour ne pas tomber, simplement en choisissant de rester là. Le fruit vient de lui.","1 Corinthiens 6.19-20 ; Jean 15.4-5"],["Une communion « conditionnelle »","Je peux être sauvé et vivre non réconcilié avec le Saint-Esprit. Des symptômes me le montrent : perte de paix, de joie, irritation, anxiété… Souvent, je crois mieux savoir que Dieu ce qui me rendra heureux.","1 Jean 1.6-7 ; Éphésiens 4.30"],["Régler et être restauré","Des « questions non réglées » bloquent la communion : un pardon à donner, une réconciliation, une restitution, un péché à confesser. Quand je confesse ce que l'Esprit me montre, la restauration est immédiate.","Matthieu 5.23-24 ; 1 Jean 1.9"]],"schema":{"type":"flow","titre":"Le schéma à retenir : les quatre étapes des dix-sept points","items":[["1-4","Sans Dieu","le fruit artificiel"],["5-8","Le salut","l'Esprit, deux natures"],["9-13","Demeurer","reconnaître, se reposer"],["14-17","Restaurer","symptômes, confession"]]},"table":null,"piege":[["Après ma conversion, ma vieille nature s'améliore peu à peu.","Elle n'est « pas le moins du monde améliorée » : la victoire vient de l'Esprit, non d'une chair réformée."],["Si je pèche, le Saint-Esprit me quitte.","Il ne me quittera jamais ; c'est la communion qui est interrompue, et la confession la rétablit."]],"astuce":"Galates 5.16 a deux parties : un ordre (« Marchez par l'Esprit ») et une promesse (« vous n'accomplirez point »). Retiens l'ordre, et la promesse suivra.","jesus":"« Le Fils ne peut rien faire de lui-même, à moins qu'il ne le voie faire au Père » (Jean 5.19). Toute sa vie terrestre s'est vécue dans la communion.","royaume":"Dieu a créé l'homme pour gouverner la terre en son nom. La chute a fait perdre ce Royaume ; Jésus vient le rendre. Le salut ouvre la porte du Royaume, pas seulement celle du ciel.","mediter":"Ai-je une question non réglée : un pardon, une réconciliation, une restitution, un péché caché ?","mots":[["Fruit artificiel","Une bonne œuvre faite sans la vie de Dieu : belle à voir, sans vie."],["Communion","La relation vécue au quotidien avec le Saint-Esprit ; elle peut être interrompue."],["Question non réglée","Ce qui bloque la communion : un pardon, une réconciliation, une restitution, une confession."],["Restauration","Le retour immédiat à la communion quand je confesse."]]},"wb":{"but":"Revoir toute la vie chrétienne en dix-sept points, de la création à la restauration de la communion.","ref":"Galates 5.16","verse":"Marchez par l’Esprit, et vous n’accomplirez point la convoitise de la chair.","q":["Pourquoi le salut est-il « plus que d'être sauvé de l'enfer » (Jean 10.10) ?","Quel est le mensonge de Satan qui est à la racine du problème ? Comment le reconnaître aujourd'hui ?","Pourquoi le « mauvais arbre » ne peut-il pas produire de bon fruit, même quand l'incroyant fait de bonnes choses ?","Quelle est la bonne nouvelle et la mauvaise nouvelle des points 7 et 8 sur mes deux natures ?","Explique avec tes mots l'illustration de la main (demeurer, se reposer).","Pourquoi la communion est-elle « conditionnelle » ? Cite deux symptômes qui montrent que je l'ai quittée.","Quelles sont les « questions non réglées » qui empêchent la restauration ? Comment la restauration se fait-elle ?"],"vf":["Ma vieille nature s'améliore peu à peu après ma conversion.","Le Saint-Esprit peut me quitter si je pèche.","Je peux vivre sauvé, mais non réconcilié avec le Saint-Esprit.","La restauration de la communion est immédiate quand je confesse ce que l'Esprit me montre."],"vfKey":[false,false,true,true],"ex":[{"k":"C1","q":"Résume les dix-sept points en dix-sept mots-clés.","type":"table","cols":["Points 1 à 4","Points 5 à 8","Points 9 à 13","Points 14 à 17"],"rows":5},{"k":"C2","q":"Partenaire, « 911 divin » ou bonheur d'abord : quelle image de Dieu ai-je eue ? Qu'est-ce que la leçon change ?","type":"text","rows":5}],"d":["Mes 15 minutes avec Dieu","Prier le Psaume 139.23-24 et noter ce que l'Esprit montre","Régler une question non réglée (pardon, restitution…)","Expliquer l'illustration de la main à quelqu'un","Je répète mon verset"],"j":"Y a-t-il en moi une question non réglée qui m'empêche de demeurer dans la communion ?","go":"Tu as revu toute la carte de la vie chrétienne. La clé, c'est la communion : quand elle se rompt, elle se rétablit aussitôt par la confession."},"quiz":[{"type":"tf","q":"Ma vieille nature s'améliore peu à peu après ma conversion.","a":false},{"type":"tf","q":"Le Saint-Esprit peut me quitter si je pèche.","a":false},{"type":"tf","q":"Je peux vivre sauvé, mais non réconcilié avec le Saint-Esprit.","a":true},{"type":"tf","q":"La restauration de la communion est immédiate quand je confesse ce que l'Esprit me montre.","a":true},{"type":"mcq","q":"Quel mot correspond à cette définition ? « Une bonne œuvre faite sans la vie de Dieu : belle à voir, sans vie. »","opts":["Vallée d'Acor","Fruit artificiel","Abandon","Stéphanos"],"a":1},{"type":"mcq","q":"Quel mot correspond à cette définition ? « La relation vécue au quotidien avec le Saint-Esprit ; elle peut être interrompue. »","opts":["Comptes courts","Tribunal de Christ","Communion","Vieil homme"],"a":2},{"type":"mcq","q":"Quel mot correspond à cette définition ? « Ce qui bloque la communion : un pardon, une réconciliation, une restitution, une confession. »","opts":["Matériaux","Question non réglée","Maturité","Problème de volonté"],"a":1},{"type":"mcq","q":"Quelle est la référence du verset de la semaine : « Marchez par l’Esprit, et vous n’accomplirez point la convoitise de la chair. »","opts":["Luc 6.12-13","Galates 5.22-23","2 Corinthiens 3.18","Galates 5.16"],"a":3},{"type":"tf","q":"Après ma conversion, ma vieille nature s'améliore peu à peu.","a":false,"why":"Elle n'est « pas le moins du monde améliorée » : la victoire vient de l'Esprit, non d'une chair réformée."},{"type":"tf","q":"Si je pèche, le Saint-Esprit me quitte.","a":false,"why":"Il ne me quittera jamais ; c'est la communion qui est interrompue, et la confession la rétablit."}]},{"n":"3-2","ph":3,"etape":"Étape 1 · La vie chrétienne approfondie","t":"Les prédispositions de ma nature humaine","fil":"Connaître l'ennemi intérieur","hook":"Et si tu voyais le monde à travers des lunettes teintées, sans le savoir ?","lire":"Romains 12.2 ; Jérémie 9.23-24","sup":{"phrase":"J'ai apporté dans ma vie chrétienne une vision du monde et des tendances à l'indépendance ; c'est le Saint-Esprit, et non l'imitation des autres, qui les transforme.","dec":["Ce qu'est ma « vision du monde » et pourquoi elle doit changer.","Pourquoi copier les autres croyants est un piège.","Les trois domaines où je cherche le bonheur sans Dieu."],"pts":[["Ma vieille nature n'est pas morte","Beaucoup pensaient ne plus être tentés après leur conversion. Mais ma nature humaine n'est ni morte ni améliorée : Dieu m'a donné en plus sa nature divine.","Galates 5.17 ; 2 Pierre 1.4"],["Un tableau blanc rempli de « X »","À la naissance, mon esprit était comme un tableau blanc. Ma famille, ma culture et mes expériences y ont écrit une vision du monde : ce qui compte, ce qui rend heureux, qui décide. Le Saint-Esprit veut la transformer.","Romains 12.2"],["Dieu ne force jamais","Il transforme ceux qui le laissent faire. Ce processus s'appelle la sanctification, et il ne s'arrête jamais sur la terre.","Philippiens 1.6 ; 2 Corinthiens 3.18"],["C'est lui qui décide","Qui décide de ce qui doit changer, comment et dans quel ordre ? Le Saint-Esprit. La grande tentation est d'imiter les autres croyants : une photocopie de photocopie devient floue. Je grandis en le connaissant, lui.","Philippiens 2.13 ; Jean 16.13"],["Force, sagesse, richesse","Trois domaines où ma nature cherche le bonheur sans Dieu. Le seul vrai sujet de gloire : le connaître. Et le laisser choisir ce qui est le meilleur pour moi.","Jérémie 9.23-24"],["Un dictateur déchu","Les tendances restent, mais je ne suis plus esclave. Les Galates se fiaient à leur propre bonne conduite ; la nature pécheresse a été détrônée à la croix.","Romains 6.6-14 ; Galates 3.3"],["Transformé à son image","Je suis soumis soit à l'Esprit, soit à la nature pécheresse. En demeurant et en le contemplant, je suis transformé de gloire en gloire.","Romains 8.5-6 ; 2 Corinthiens 3.18"]],"schema":{"type":"flow","titre":"Le schéma à retenir : comment le monde, puis l'Esprit, façonnent ma pensée","items":[["1","Le tableau blanc","à la naissance"],["2","Les « X »","famille, culture, expériences"],["3","Ma vision du monde","ce qui rend heureux, qui décide"],["4","L'Esprit transforme","par la Parole, de l'intérieur"]]},"table":{"titre":"Les trois domaines de l'indépendance","head":["Le domaine","Ce que je cherche sans Dieu","Ce que Dieu dit"],"rows":[["La force","Mes capacités, ma santé, mon apparence","« Que le fort ne se glorifie pas dans sa force »"],["La sagesse","Mon intelligence, mes diplômes, mes plans","« Que le sage ne se glorifie pas dans sa sagesse »"],["La richesse","Mes biens, ma sécurité matérielle","« Que le riche ne se glorifie pas dans sa richesse »"],["Le vrai sujet","","« Qu'il me comprenne et me connaisse »"]]},"piege":[["Pour grandir, j'imite le chrétien le plus mûr que je connais.","Je grandis en connaissant le Seigneur ; c'est l'Esprit qui décide quoi changer et dans quel ordre."],["Si mes mauvais désirs reviennent, je ne suis peut-être pas sauvé.","Les tendances restent jusqu'au bout ; mais elles ne sont plus mon maître."]],"astuce":"2 Corinthiens 3.18 : « contemplant… transformés… de gloire en gloire ». Je regarde, il transforme.","jesus":"Tenté sur la force, la reconnaissance et la possession, il a répondu trois fois « Il est écrit » (Matthieu 4.1-11). Il voyait toujours la vie du point de vue du Père.","royaume":"Entrer dans le Royaume, c'est changer de culture. Le citoyen ne prend pas ses valeurs autour de lui, mais auprès de son Roi ; l'Esprit lui enseigne la culture du Royaume.","mediter":"Dans quel domaine (force, sagesse, richesse) est-ce que je cherche encore le bonheur sans Dieu ?","mots":[["Vision du monde","La façon de voir la vie que j'ai reçue de ma famille, de ma culture et de mes expériences."],["Sanctification","Le processus par lequel l'Esprit me transforme à l'image de Christ."],["Dictateur déchu","La nature pécheresse : toujours présente, mais détrônée à la croix."],["Photocopie","L'image de l'imitation des autres croyants : de plus en plus floue."]]},"wb":{"but":"Identifier ma vision du monde et mes tendances à l'indépendance, pour dépendre de moins en moins de moi-même.","ref":"2 Corinthiens 3.18","verse":"Or nous tous, contemplant à face découverte la gloire du Seigneur, nous sommes transformés en la même image, de gloire en gloire, comme par le Seigneur en Esprit.","q":["Ma vieille nature est-elle morte ? Pourquoi suis-je encore tenté ?","Qu'est-ce que la « vision du monde » que j'ai apportée dans ma vie chrétienne (le tableau blanc et les « X ») ?","Qui décide de ce qui doit changer en moi, comment, et dans quel ordre ?","Que montre l'illustration de la photocopie ? Pourquoi ne pas imiter les autres croyants ?","Quels sont les trois domaines où ma nature tend à l'indépendance (Jérémie 9.23-24) ?","Que signifie que la nature pécheresse est un « dictateur déchu » ?"],"vf":["Après la conversion, les mauvais désirs disparaissent pour toujours.","Dieu force les changements dans ma vie, que je le veuille ou non.","Imiter un chrétien mûr est la meilleure façon de grandir.","La sanctification est un processus qui ne s'arrête jamais sur la terre."],"vfKey":[false,false,false,true],"ex":[{"k":"C1","q":"Écris trois « X » de ta vision du monde, et ce que la Parole en dit.","type":"table","cols":["Ce que je pensais","Ce que dit la Parole","Le verset"],"rows":5},{"k":"C2","q":"Force, sagesse, richesse : dans lequel cherches-tu le plus le bonheur sans Dieu ? Donne un exemple.","type":"text","rows":5}],"d":["Mes 15 minutes avec Dieu","Demander : « Quelle pensée du monde veux-tu changer ? »","Avant une décision : « Si tu juges que c'est bon pour moi… »","Dire à ma vieille nature : « Tu es un dictateur déchu »","Je répète mon verset"],"j":"Est-ce que je copie les autres, ou est-ce que je laisse la Parole me transformer ?","go":"Tu connais mieux ton ennemi intérieur. Il n'est plus ton maître : l'Esprit te transforme de gloire en gloire."},"quiz":[{"type":"tf","q":"Après la conversion, les mauvais désirs disparaissent pour toujours.","a":false},{"type":"tf","q":"Dieu force les changements dans ma vie, que je le veuille ou non.","a":false},{"type":"tf","q":"Imiter un chrétien mûr est la meilleure façon de grandir.","a":false},{"type":"tf","q":"La sanctification est un processus qui ne s'arrête jamais sur la terre.","a":true},{"type":"mcq","q":"Quel mot correspond à cette définition ? « La façon de voir la vie que j'ai reçue de ma famille, de ma culture et de mes expériences. »","opts":["Problème de volonté","Pardonner","Vision du monde","Miséricorde"],"a":2},{"type":"mcq","q":"Quel mot correspond à cette définition ? « Le processus par lequel l'Esprit me transforme à l'image de Christ. »","opts":["Saint des saints","Redevable","Sanctification","Méditer"],"a":2},{"type":"mcq","q":"Quel mot correspond à cette définition ? « La nature pécheresse : toujours présente, mais détrônée à la croix. »","opts":["Ressources","Photocopie","Jourdain","Dictateur déchu"],"a":3},{"type":"mcq","q":"Quelle est la référence du verset de la semaine : « Or nous tous, contemplant à face découverte la gloire du Seigneur, nous sommes transformés en la même image, d… »","opts":["2 Pierre 3.18","2 Corinthiens 3.18","Jean 15.8","2 Corinthiens 5.10"],"a":1},{"type":"tf","q":"Pour grandir, j'imite le chrétien le plus mûr que je connais.","a":false,"why":"Je grandis en connaissant le Seigneur ; c'est l'Esprit qui décide quoi changer et dans quel ordre."},{"type":"tf","q":"Si mes mauvais désirs reviennent, je ne suis peut-être pas sauvé.","a":false,"why":"Les tendances restent jusqu'au bout ; mais elles ne sont plus mon maître."}]},{"n":"3-3","ph":3,"etape":"Étape 1 · La vie chrétienne approfondie","t":"Deux rois, deux types de croyants","fil":"Saül et David","hook":"Deux rois ont dit « J'ai péché ». Un seul a été pardonné. Pourquoi ?","lire":"1 Samuel 15 ; 2 Samuel 12.1-14","sup":{"phrase":"Saül avait un problème de volonté : il se justifiait et cherchait l'honneur des hommes. David avait un problème de conduite : il a confessé aussitôt et a été pardonné.","dec":["Neuf principes : un seul maître dans la vie du chrétien.","La différence entre un problème de volonté et un problème de conduite.","Deux confessions qui se ressemblent, et deux cœurs opposés."],"pts":[["Un seul maître","« Nul ne peut servir deux maîtres. » Reconnaître la seigneurie de Jésus est une décision consciente, puis un renouvellement quotidien. Je suis son serviteur : il n'est pas mon partenaire.","Matthieu 6.24 ; Romains 12.1"],["La volonté, ou la conduite","Le cœur de la leçon : un croyant peut avoir un problème de volonté (il ne veut pas se soumettre), ou un problème de conduite (il s'est soumis, mais il tombe). Le remède n'est pas le même.",""],["Saül : choisi, mais impatient","Choisi par Dieu, l'Esprit sur lui, une apparence très attirante. Mais il n'attend pas Samuel et offre lui-même l'holocauste : « je me suis fait violence ».","1 Samuel 10.1-10 ; 13.8-14"],["Saül : une obéissance partielle","Il épargne le meilleur d'Amalek, suit son propre raisonnement, cherche l'approbation du peuple. Confronté, il se défend, puis dit « j'ai péché », mais demande aussitôt : « honore-moi devant les anciens ».","1 Samuel 15.9-30"],["David : passionné pour Dieu","Choisi, préparé et béni par Dieu, David a soif du Seigneur. Pourtant il tombe avec Bath-Shéba, puis fait tuer Urie, et vit des mois hors de la communion.","Psaume 63.1 ; 2 Samuel 11"],["David : « J'ai péché contre l'Éternel »","Confronté par Nathan (« Tu es cet homme »), David accepte aussitôt tout le blâme. Le pardon de Dieu est complet, même si des conséquences demeurent.","2 Samuel 12.1-14 ; Psaume 51"]],"schema":{"type":"table","titre":"Le schéma à retenir : deux rois côte à côte","head":["","Saül","David"],"rows":[["Le problème","La volonté","La conduite"],["Confronté par","Samuel","Nathan"],["Sa réaction","Il se justifie, accuse le peuple","Il accepte tout le blâme"],["Ce qu'il cherche","L'honneur des hommes","La face de Dieu"],["Le résultat","Rejeté comme roi","Pardonné, restauré"]]},"table":null,"piege":[["J'ai obéi à presque tout ce que Dieu a dit : c'est déjà bien.","Une obéissance partielle est une désobéissance : « tu as rejeté la parole de l'Éternel »."],["Dire « j'ai péché » suffit.","Saül l'a dit aussi. La vraie confession ne cherche ni excuse ni honneur pour soi."]],"astuce":"1 Samuel 15.22 : deux comparaisons. « Écouter » est meilleur que « sacrifice » ; « prêter l'oreille » est meilleur que « la graisse des béliers ».","jesus":"« Je ne reçois pas de gloire des hommes » (Jean 5.41). Il a obéi jusqu'à la mort, sans rien garder pour lui (Philippiens 2.8).","royaume":"Un royaume n'a qu'un roi. Saül voulait régner sous Dieu tout en restant maître de ses choix ; David savait qu'il n'était qu'un intendant sur le trône de l'Éternel.","mediter":"Quand je suis repris, est-ce que je me justifie comme Saül, ou est-ce que je dis comme David : « J'ai péché contre l'Éternel » ?","mots":[["Seigneurie","Reconnaître Jésus comme le seul maître de ma vie."],["Problème de volonté","Refuser de se soumettre à Dieu."],["Problème de conduite","S'être soumis, mais tomber ; le remède est la confession."],["Obéissance partielle","Obéir à moitié : aux yeux de Dieu, c'est désobéir."]]},"wb":{"but":"Comparer Saül et David : un problème de volonté, ou un problème de conduite.","ref":"1 Samuel 15.22","verse":"L’Éternel prend-il plaisir aux holocaustes et aux sacrifices, comme à ce qu’on écoute la voix de l’Éternel? Voici, écouter est meilleur que sacrifice, prêter l’oreille, meilleur que la graisse des béliers.","q":["Selon Matthieu 6.24, combien de maîtres peut-on servir ? Pourquoi ?","Reconnaître la seigneurie : un choix unique ou un renouvellement quotidien ? Explique.","Quel était le problème de fond de Saül ? Donne deux exemples tirés de 1 Samuel 13 et 15.","Quel était le problème de David ? Comment a-t-il réagi quand Nathan l'a confronté ?","Compare les deux confessions : « J'ai péché » chez Saül et chez David. Quelle est la différence ?","Pourquoi une obéissance partielle est-elle une désobéissance ?"],"vf":["Saül et David ont tous deux été choisis par Dieu.","Saül a désobéi parce qu'il cherchait l'approbation des hommes.","David n'a jamais péché gravement.","Le pardon de Dieu envers David a été complet."],"vfKey":[true,true,false,true],"ex":[{"k":"C1","q":"Compare les deux rois.","type":"table","cols":["Saül (1 Samuel 15)","David (2 Samuel 12)"],"rows":5},{"k":"C2","q":"Y a-t-il un ordre de Dieu que j'ai obéi « à moitié » ? Qu'est-ce que je garde pour moi ?","type":"text","rows":5}],"d":["Mes 15 minutes avec Dieu","Lire 1 Samuel 15 et 2 Samuel 12","Faire une chose juste que seul Dieu verra","Quand je suis repris : répondre sans me justifier","Je répète mon verset"],"j":"Quand je suis repris, est-ce que je me justifie comme Saül, ou est-ce que je confesse comme David ?","go":"Dieu ne cherche pas un croyant parfait, mais un cœur qui ne se justifie pas. Écouter vaut mieux que sacrifier."},"quiz":[{"type":"tf","q":"Saül et David ont tous deux été choisis par Dieu.","a":true},{"type":"tf","q":"Saül a désobéi parce qu'il cherchait l'approbation des hommes.","a":true},{"type":"tf","q":"David n'a jamais péché gravement.","a":false},{"type":"tf","q":"Le pardon de Dieu envers David a été complet.","a":true},{"type":"mcq","q":"Quel mot correspond à cette définition ? « Reconnaître Jésus comme le seul maître de ma vie. »","opts":["Saint des saints","Sarment","Vase utilisable","Seigneurie"],"a":3},{"type":"mcq","q":"Quel mot correspond à cette définition ? « Refuser de se soumettre à Dieu. »","opts":["Demeurer","Problème de volonté","Esprit","Mentor"],"a":1},{"type":"mcq","q":"Quel mot correspond à cette définition ? « S'être soumis, mais tomber ; le remède est la confession. »","opts":["Problème de conduite","Fruit artificiel","Discipulat","Caleb"],"a":0},{"type":"mcq","q":"Quelle est la référence du verset de la semaine : « L’Éternel prend-il plaisir aux holocaustes et aux sacrifices, comme à ce qu’on écoute la voix de l’Éternel? Vo… »","opts":["1 Corinthiens 3.9","1 Samuel 15.22","Jean 15.4","Job 1.21"],"a":1},{"type":"tf","q":"J'ai obéi à presque tout ce que Dieu a dit : c'est déjà bien.","a":false,"why":"Une obéissance partielle est une désobéissance : « tu as rejeté la parole de l'Éternel »."},{"type":"tf","q":"Dire « j'ai péché » suffit.","a":false,"why":"Saül l'a dit aussi. La vraie confession ne cherche ni excuse ni honneur pour soi."}]},{"n":"3-4","ph":3,"etape":"Étape 1 · La vie chrétienne approfondie","t":"Le voyage des Israélites","fil":"Sortir, pour entrer","hook":"Sortir d'Égypte ne suffit pas. Qu'est-ce qui t'attend au Jourdain ?","lire":"Nombres 13-14 ; Josué 3-4","sup":{"phrase":"Dieu a fait sortir Israël d'Égypte pour le faire entrer en Canaan ; au Jourdain, tout dépendait d'une question : Dieu est-il digne de confiance ?","dec":["Les sept étapes du voyage d'Israël.","Deux groupes : l'un a erré, l'autre est entré.","Ce que représentent la Pâque, la mer Rouge, le Jourdain et la terre promise dans ma vie."],"pts":[["Un plan en deux étapes","Au buisson ardent, Dieu annonce : je vais les faire sortir d'Égypte, puis les faire monter dans un bon pays. Il ne fait pas sortir pour laisser errer.","Exode 3.7-8 ; Deutéronome 6.23"],["La Pâque, la mer Rouge, la Loi","Le sang sur les portes protège ; la mer Rouge s'ouvre et l'ennemi est englouti ; au Sinaï, Dieu donne la Loi.","Exode 12 ; 14 ; 20"],["Au Jourdain, deux raisonnements","Les dix espions voient des géants et concluent avec leur raisonnement humain. Josué et Caleb voient les mêmes géants, mais les mesurent à la taille de Dieu. Le peuple refuse : « Jusqu'à quand ne me croiront-ils pas ? »","Nombres 13-14"],["Quarante ans de désert","Un an pour chaque jour d'exploration. Dieu a pourvu (manne, eau, vêtements), mais ils ont perdu l'héritage. Puis ils ont voulu monter sans Dieu, et ont été battus.","Nombres 14.33-45 ; Hébreux 3.19"],["Le second groupe traverse","Les pieds des sacrificateurs dans l'eau, les pierres du souvenir, la circoncision et la Pâque à Guilgal, puis le chef de l'armée de l'Éternel. « Pas une bonne parole n'a failli. »","Josué 3-5 ; 21.43-45"],["Mon propre voyage","Avant Christ, l'esclavage ; la croix, ma Pâque ; le baptême, ma mer Rouge ; la Loi expose ma nature ; la seigneurie, mon Jourdain ; puis le désert, ou la terre promise.","1 Corinthiens 10.1-11"],["La vue, ou la foi","Le désert est une marche par la vue ; la terre promise, une marche par la foi, dans le repos qui reste pour le peuple de Dieu.","Hébreux 4.9-11 ; 2 Corinthiens 5.7"]],"schema":{"type":"table","titre":"Le schéma à retenir : le voyage d'Israël et le mien","head":["Israël","Moi"],"rows":[["L'Égypte","Ma vie sans Christ, l'esclavage"],["La Pâque","La croix"],["La mer Rouge","Le baptême"],["Le Sinaï","La Loi expose ma nature pécheresse"],["Le Jourdain","La seigneurie"],["Le désert","Une vie sauvée, mais marchant par la vue"],["La terre promise","La vie de communion, par la foi"]]},"table":null,"piege":[["Canaan est une image du ciel.","On y livre des batailles : c'est l'image d'une vie où Dieu règne et combat pour moi, ici et maintenant."],["Ceux du désert ont perdu leur salut.","Dieu a continué de pourvoir ; ils ont perdu l'héritage et le repos, comme le croyant « sauvé comme à travers le feu »."]],"astuce":"Deutéronome 6.23 tient en deux verbes : « faire sortir », « faire entrer ». Le salut, puis la seigneurie.","jesus":"Lui aussi est passé par le Jourdain et le désert. Mais au désert, il a fait confiance au Père et répondu par la Parole : là où Israël a échoué, il a vaincu.","royaume":"Le Royaume, c'est l'influence du gouvernement du Roi sur un territoire. Canaan, c'est la vie placée sous ce gouvernement.","mediter":"Quels « géants » m'empêchent de traverser ? Quelle promesse de Dieu ai-je oubliée ?","mots":[["Jourdain","L'image de la décision de seigneurie : traverser par la foi."],["Désert","Une vie chrétienne sauvée mais sans repos, marchant par la vue."],["Terre promise","La vie de communion, sous le règne de Dieu."],["Caleb","Celui qui « a pleinement suivi » : un homme entier."]]},"wb":{"but":"Voir dans le voyage d'Israël l'image de mon voyage chrétien : sortir, puis entrer par la foi.","ref":"Deutéronome 6.23","verse":"Il nous a fait sortir de là, pour nous faire entrer dans le pays qu’il avait promis par serment à nos pères, pour nous le donner.","q":["Quel était le plan de Dieu en deux étapes pour Israël ?","Que s'est-il passé au Jourdain ? Quelle question se posait vraiment ?","Compare l'argument des dix espions et celui de Josué et Caleb (Nombres 14).","Qu'est-ce que le premier groupe a perdu ? Qu'est-ce que Dieu a quand même fait pour lui ?","Qu'est-ce qui a permis au second groupe de traverser ?","Dans mon voyage, que représentent la Pâque, la mer Rouge, le Jourdain et la terre promise ?"],"vf":["Canaan est une image du ciel après la mort.","Les Israélites n'ont pas pu entrer à cause de l'incrédulité (Hébreux 3.19).","Le premier groupe a été abandonné par Dieu dans le désert.","Le désert est une marche par la vue ; la terre promise, une marche par la foi."],"vfKey":[false,true,false,true],"ex":[{"k":"C1","q":"Relie chaque étape d'Israël à son équivalent dans ma vie.","type":"table","cols":["Israël","Ma vie chrétienne","Où j'en suis"],"rows":5},{"k":"C2","q":"Quelle est ma « pierre de souvenir » (Josué 4) : le moment où j'ai reconnu Jésus comme Seigneur ?","type":"text","rows":5}],"d":["Mes 15 minutes avec Dieu","Lire Nombres 13-14 et Josué 3-5","Écrire une promesse de Dieu et la peur qui m'empêche de la croire","Lire Hébreux 3 et 4","Je répète mon verset"],"j":"Quels « géants » m'empêchent de traverser mon Jourdain ?","go":"Dieu ne t'a pas fait sortir pour te laisser errer : il t'a fait sortir pour te faire entrer."},"quiz":[{"type":"tf","q":"Canaan est une image du ciel après la mort.","a":false},{"type":"tf","q":"Les Israélites n'ont pas pu entrer à cause de l'incrédulité (Hébreux 3.19).","a":true},{"type":"tf","q":"Le premier groupe a été abandonné par Dieu dans le désert.","a":false},{"type":"tf","q":"Le désert est une marche par la vue ; la terre promise, une marche par la foi.","a":true},{"type":"mcq","q":"Quel mot correspond à cette définition ? « L'image de la décision de seigneurie : traverser par la foi. »","opts":["Saint des saints","Sacrifice spirituel","Jourdain","Esprit"],"a":2},{"type":"mcq","q":"Quel mot correspond à cette définition ? « Une vie chrétienne sauvée mais sans repos, marchant par la vue. »","opts":["Fondement","Pardonner","Désert","Terre promise"],"a":2},{"type":"mcq","q":"Quel mot correspond à cette définition ? « La vie de communion, sous le règne de Dieu. »","opts":["Intercéder","Substitution","Terre promise","Pardon légal"],"a":2},{"type":"mcq","q":"Quelle est la référence du verset de la semaine : « Il nous a fait sortir de là, pour nous faire entrer dans le pays qu’il avait promis par serment à nos pères, p… »","opts":["Job 1.21","Romains 12.2","Deutéronome 6.23","Galates 5.16"],"a":2},{"type":"tf","q":"Canaan est une image du ciel.","a":false,"why":"On y livre des batailles : c'est l'image d'une vie où Dieu règne et combat pour moi, ici et maintenant."},{"type":"tf","q":"Ceux du désert ont perdu leur salut.","a":false,"why":"Dieu a continué de pourvoir ; ils ont perdu l'héritage et le repos, comme le croyant « sauvé comme à travers le feu »."}]},{"n":"3-5","ph":3,"etape":"Étape 2 · La seigneurie","t":"La seigneurie : versets et principes","fil":"Il m'a créé, il m'a racheté","hook":"Jésus est-il au volant de ta vie… ou sur le siège passager ?","lire":"Luc 14.25-33 ; Romains 12.1-2","sup":{"phrase":"J'appartiens deux fois à Dieu, parce qu'il m'a créé et parce qu'il m'a racheté ; lui abandonner mes biens, mon corps et mon intelligence est le choix le plus raisonnable.","dec":["Pourquoi Jésus a le droit d'être mon Seigneur.","Le fondement et les deux maisons : qui est l'architecte ?","Cinq illustrations de l'abandon, et trois domaines à abandonner."],"pts":[["Créé et racheté","J'appartiens à Dieu parce qu'il m'a créé, et j'ai été acheté à un grand prix. Le salut ne répare pas ma vieille nature : il me donne une nature nouvelle.","Psaume 100.3 ; 1 Corinthiens 6.19-20"],["Un fondement, deux maisons","Jésus est le fondement. Sur lui, je peux laisser le Saint-Esprit bâtir avec mes matériaux (or, argent, pierres précieuses), ou bâtir moi-même (bois, foin, chaume). L'œuvre de chacun sera manifestée.","1 Corinthiens 3.10-15"],["Mon tableau blanc, pas une liste","Être disciple, c'est donner au Saint-Esprit accès à mon intelligence. Le piège : remplacer la relation par une liste « à faire, à ne pas faire ».","Romains 12.2"],["Mon Maître, son serviteur","« Seigneur » décrit une relation de maître à serviteur (esclave). Paul se dit esclave par amour. C'est une libération : celui qui me commande m'aime.","Luc 6.46 ; Romains 1.1"],["Plus important que ma vie","Ce à quoi je tiens doit être soumis à sa seigneurie. « Haïr » sa propre vie (Luc 14) exprime la priorité de l'amour : Dieu d'abord.","Luc 14.25-33 ; Matthieu 11.29"],["Cinq illustrations","Le mariage (renoncer à son indépendance), le repos d'Israël, le cheval sauvage qu'on dresse, la voiture (copilote ou aux commandes ?), et deux portes devant moi.",""],["Le caractère raisonnable de l'abandon","Dieu est totalement bon. Il sait tout, il peut tout, il m'aime : m'abandonner à lui est le plus logique. Paul savait ce qui l'attendait, et il est allé.","Romains 12.1 ; Actes 20.22-24"]],"schema":{"type":"flow","titre":"Le schéma à retenir : trois domaines de ma vie à abandonner","items":[["1","Mes biens","ce que je possède"],["2","Mon corps","ma santé, mon temps, mon énergie"],["3","Mon intelligence","mes pensées, mes plans"]]},"table":null,"piege":[["Être serviteur de Jésus me prive de ma liberté.","Celui qui me commande est totalement bon : sa seigneurie est une libération."],["La seigneurie, c'est suivre une liste de règles.","C'est donner à l'Esprit accès à mon intelligence, pour qu'il me transforme de l'intérieur."]],"astuce":"Romains 12.1 : « par les compassions de Dieu ». Je ne m'offre pas pour gagner son amour, mais parce que je l'ai déjà reçu.","jesus":"Au jardin, il a dit : « Que ce ne soit pas ma volonté, mais la tienne qui soit faite » (Luc 22.42). Le Seigneur lui-même a vécu sous l'autorité du Père.","royaume":"Dans un royaume, le roi est aussi propriétaire. Dire « Jésus est Seigneur », c'est reconnaître que tout lui appartient déjà : mon temps, mon corps, ma pensée.","mediter":"Qui tient le volant de ma vie ? Qu'est-ce qui me fait encore peur dans la seconde porte ?","mots":[["Seigneur","Le maître et propriétaire ; mon Seigneur est Jésus."],["Fondement","Jésus-Christ, sur qui ma vie est bâtie au salut."],["Matériaux","Mon temps, mon énergie et mes biens, avec lesquels on bâtit."],["Abandon","Remettre à Dieu le contrôle d'un domaine de ma vie."]]},"wb":{"but":"Comprendre pourquoi Jésus est mon Seigneur, et lui abandonner mes biens, mon corps et mon intelligence.","ref":"Romains 12.1","verse":"Je vous exhorte donc, frères, par les compassions de Dieu, à présenter vos corps en sacrifice vivant, saint, agréable à Dieu, ce qui est votre service intelligent.","q":["Pour quelles deux raisons est-ce que j'appartiens à Dieu ?","Explique le schéma du fondement et des deux maisons. Qui est l'architecte de ma vie ?","Pourquoi la liste « à faire, à ne pas faire » est-elle un piège ?","Que signifie que Jésus est mon Maître et que je suis son serviteur ? Est-ce un esclavage ou une libération ?","Que veut dire « haïr » sa propre vie en Luc 14 ?","Quelles sont les illustrations du point 12 (mariage, mustang, voiture, deux portes) ? Laquelle te parle le plus ?","Pourquoi l'abandon total est-il le choix le plus raisonnable ?"],"vf":["Le salut répare ma vieille nature.","Je reste libre de laisser ou non mes matériaux au Saint-Esprit.","Être serviteur de Jésus me prive de ma liberté.","Dieu est totalement bon : je peux lui confier toute ma vie."],"vfKey":[false,true,false,true],"ex":[{"k":"C1","q":"Les trois domaines : que vais-je lui abandonner concrètement ?","type":"table","cols":["Mes biens","Mon corps","Mon intelligence"],"rows":5},{"k":"C2","q":"Écris une prière d'abandon pour le domaine que tu gardes encore.","type":"text","rows":5}],"d":["Mes 15 minutes avec Dieu","Offrir un domaine par jour (biens, corps, intelligence)","Relire Luc 14.25-33","Laisser le Saint-Esprit « tenir le volant » d'une décision","Je répète mon verset"],"j":"Qui tient le volant de ma vie aujourd'hui ?","go":"Celui qui te demande tout t'a déjà tout donné. T'abandonner à lui, c'est le choix le plus logique."},"quiz":[{"type":"tf","q":"Le salut répare ma vieille nature.","a":false},{"type":"tf","q":"Je reste libre de laisser ou non mes matériaux au Saint-Esprit.","a":true},{"type":"tf","q":"Être serviteur de Jésus me prive de ma liberté.","a":false},{"type":"tf","q":"Dieu est totalement bon : je peux lui confier toute ma vie.","a":true},{"type":"mcq","q":"Quel mot correspond à cette définition ? « Le maître et propriétaire ; mon Seigneur est Jésus. »","opts":["Collaborateur de Dieu","Perte","Nature divine","Seigneur"],"a":3},{"type":"mcq","q":"Quel mot correspond à cette définition ? « Jésus-Christ, sur qui ma vie est bâtie au salut. »","opts":["Problème de volonté","Fondement","Intimité spirituelle","Volonté permissive"],"a":1},{"type":"mcq","q":"Quel mot correspond à cette définition ? « Mon temps, mon énergie et mes biens, avec lesquels on bâtit. »","opts":["Cep","Matériaux","Esprit","De moi-même"],"a":1},{"type":"mcq","q":"Quelle est la référence du verset de la semaine : « Je vous exhorte donc, frères, par les compassions de Dieu, à présenter vos corps en sacrifice vivant, saint, a… »","opts":["Romains 12.2","2 Pierre 3.18","Galates 5.16","Romains 12.1"],"a":3},{"type":"tf","q":"Être serviteur de Jésus me prive de ma liberté.","a":false,"why":"Celui qui me commande est totalement bon : sa seigneurie est une libération."},{"type":"tf","q":"La seigneurie, c'est suivre une liste de règles.","a":false,"why":"C'est donner à l'Esprit accès à mon intelligence, pour qu'il me transforme de l'intérieur."}]},{"n":"3-6","ph":3,"etape":"Étape 2 · La seigneurie","t":"Dieu à l'œuvre dans la vie de Job","fil":"Les biens, le corps, l'intelligence","hook":"Job a tout perdu… et il a béni Dieu. Quel était son secret ?","lire":"Job 1-2 ; Job 42.1-10","sup":{"phrase":"Rien ne passe la haie de Dieu sans sa permission ; il a façonné Job dans ses biens, son corps et surtout son intelligence, pour qu'il le connaisse vraiment.","dec":["La haie de Dieu autour de chaque croyant.","Pourquoi Job a pu bénir Dieu dans la perte.","Le vrai domaine que Dieu visait : l'orgueil spirituel de Job."],"pts":[["Un homme passionné et béni","Job craignait Dieu et se retirait du mal. Dieu l'avait richement béni.","Job 1.1-5"],["La haie de Dieu","Satan le reconnaît : « Ne l'as-tu pas entouré d'une haie ? » L'ennemi doit recevoir la permission de Dieu, et Dieu fixe chaque fois la limite. Il n'a jamais perdu le contrôle.","Job 1.10-12 ; 2.6"],["Les biens, puis le corps","Dieu permet de toucher les biens de Job, mais « sur lui n'étends pas ta main » ; puis son corps, mais « épargne sa vie ».","Job 1.13-19 ; 2.7-8"],["« L'Éternel a donné, l'Éternel a pris »","Job pleure et adore. Il avait reconnu la seigneurie de Dieu bien avant l'épreuve : l'épreuve a seulement montré ce qui était déjà décidé.","Job 1.20-22 ; 2.10"],["Élihu met le doigt sur l'orgueil","Après vingt-neuf chapitres de débats, Élihu montre que Job se justifiait lui-même plutôt que Dieu. Il le reprend avec douceur.","Job 32.2 ; Galates 6.1"],["Dieu parle, Job se repent","Dieu ne donne pas le « pourquoi » : il se révèle. Job répond : « Maintenant mon œil t'a vu », et se repent.","Job 38.1-4 ; 42.5-6"],["Restauré en priant pour ses amis","Dieu reprend les accusateurs et restaure Job au double quand il prie pour eux.","Job 42.7-10"]],"schema":{"type":"table","titre":"Le schéma à retenir : trois domaines, deux réponses","head":["Le domaine","Ève : l'indépendance (Genèse 3.6)","Jésus : la dépendance (Luc 4)"],"rows":[["L'âme (intelligence)","« Désirable pour rendre intelligent »","« Tu ne tenteras pas le Seigneur »"],["Le corps","« Bon à manger »","« L'homme ne vivra pas de pain seulement »"],["Les biens","« Un plaisir pour les yeux »","« Tu rendras hommage au Seigneur ton Dieu »"]]},"table":null,"piege":[["Satan peut faire ce qu'il veut dans la vie d'un croyant.","Il doit recevoir la permission de Dieu, qui fixe chaque fois la limite."],["Le livre de Job explique pourquoi les justes souffrent.","Dieu ne donne pas d'explication : il se révèle, et façonne son enfant."]],"astuce":"Job 1.21 : « donné… pris… béni ». Trois verbes pour une seule attitude : tout est à lui.","jesus":"Tenté dans les trois domaines, il a répondu : « Il est écrit. » Il n'a jamais agi indépendamment du Père (Jean 5.19).","royaume":"Un citoyen du Royaume ne vit pas pour ce qu'il a, mais sous l'autorité du Roi qui pourvoit. La haie de Dieu est la protection du Royaume sur ses enfants.","mediter":"Ai-je déjà décidé, avant l'épreuve, que Dieu est Seigneur de mes biens, de mon corps et de ma pensée ?","mots":[["La haie","La protection de Dieu autour du croyant : rien ne passe sans sa permission."],["Orgueil spirituel","Se justifier soi-même plutôt que Dieu."],["Élihu","Le jeune homme qui a repris Job avec douceur et vérité."],["Le double","Dieu rend à Job le double de tout ce qu'il avait, quand il prie pour ses amis."]]},"wb":{"but":"Voir comment Dieu a façonné Job dans les trois domaines : ses biens, son corps et son intelligence.","ref":"Job 1.21","verse":"Nu je suis sorti du sein de ma mère, et nu j’y retournerai; l’Éternel a donné, et l’Éternel a pris; que le nom de l’Éternel soit béni!","q":["Qu'est-ce que la « haie » de Dieu (Job 1.10) ? Que dit-elle de son contrôle ?","Quelles limites Dieu a-t-il fixées à Satan dans le domaine des biens, puis du corps ?","Pourquoi Job a-t-il pu répondre « L'Éternel a donné, et l'Éternel a pris » ?","Quel était le vrai problème de Job, mis en lumière par Élihu (Job 32.2) ?","Comment Dieu a-t-il corrigé Job ? Qu'a répondu Job (Job 42.5-6) ?","Compare Ève (Genèse 3.6) et Jésus (Luc 4.1-12) dans les trois domaines."],"vf":["Satan peut toucher un croyant sans la permission de Dieu.","Job a reconnu la seigneurie de Dieu bien avant l'épreuve.","Dieu a expliqué à Job pourquoi il souffrait.","La restauration de Job est venue quand il a prié pour ses amis."],"vfKey":[false,true,false,true],"ex":[{"k":"C1","q":"Un exemple de tentation dans chaque domaine, et ma réponse.","type":"table","cols":["Le domaine","La tentation","Ma réponse selon la Parole"],"rows":5},{"k":"C2","q":"Écris ton « Job 1.21 » : ce que tu remets à Dieu d'avance.","type":"text","rows":5}],"d":["Mes 15 minutes avec Dieu","Lire Job 1, 2, 38 et 42","Relever trois publicités et le domaine visé","Remettre à Dieu d'avance un domaine de ma vie","Je répète mon verset"],"j":"Ai-je déjà décidé, avant l'épreuve, que Dieu est Seigneur de tout ?","go":"Rien ne passe la haie sans sa permission. Ce que tu lui abandonnes aujourd'hui, personne ne pourra te le voler demain."},"quiz":[{"type":"tf","q":"Satan peut toucher un croyant sans la permission de Dieu.","a":false},{"type":"tf","q":"Job a reconnu la seigneurie de Dieu bien avant l'épreuve.","a":true},{"type":"tf","q":"Dieu a expliqué à Job pourquoi il souffrait.","a":false},{"type":"tf","q":"La restauration de Job est venue quand il a prié pour ses amis.","a":true},{"type":"mcq","q":"Quel mot correspond à cette définition ? « La protection de Dieu autour du croyant : rien ne passe sans sa permission. »","opts":["Fidèle","Chair","La haie","Vieil homme"],"a":2},{"type":"mcq","q":"Quel mot correspond à cette définition ? « Se justifier soi-même plutôt que Dieu. »","opts":["Orgueil spirituel","Conforme à son image","Caleb","Romains 8"],"a":0},{"type":"mcq","q":"Quel mot correspond à cette définition ? « Le jeune homme qui a repris Job avec douceur et vérité. »","opts":["Méthode active","Terre promise","Bêma","Élihu"],"a":3},{"type":"mcq","q":"Quelle est la référence du verset de la semaine : « Nu je suis sorti du sein de ma mère, et nu j’y retournerai; l’Éternel a donné, et l’Éternel a pris; que le nom… »","opts":["Romains 8.28","Deutéronome 6.23","Job 1.21","Galates 2.20"],"a":2},{"type":"tf","q":"Satan peut faire ce qu'il veut dans la vie d'un croyant.","a":false,"why":"Il doit recevoir la permission de Dieu, qui fixe chaque fois la limite."},{"type":"tf","q":"Le livre de Job explique pourquoi les justes souffrent.","a":false,"why":"Dieu ne donne pas d'explication : il se révèle, et façonne son enfant."}]},{"n":"3-7","ph":3,"etape":"Étape 2 · La seigneurie","t":"Mon vieil homme et mon homme nouveau","fil":"Marcher par l'Esprit","hook":"Couper les mauvaises herbes ne suffit pas. Que faut-il planter ?","lire":"Romains 7.15-8.4 ; Éphésiens 4.17-32","sup":{"phrase":"Éviter le mal ne suffit pas, et couper les mauvais fruits ne change pas la racine : je traverse Romains 7, mais je réside en Romains 8, en marchant par l'Esprit.","dec":["Pourquoi le comportement n'est que le symptôme.","Le vieil homme et l'homme nouveau d'Éphésiens 4 et 5.","Traverser Romains 7 pour résider en Romains 8."],"pts":[["Pas une lutte à endurer","La vie chrétienne n'est pas une lutte à endurer jusqu'au ciel. Chasser les ténèbres ne suffit pas : il faut la lumière. Le but : la stature de Christ.","Éphésiens 4.13 ; 2 Pierre 1.3"],["La racine, pas les fruits","Ma nature humaine est pécheresse, indépendante, irréparable. Mon comportement n'est que le fruit ; couper les fruits ne change pas la source.","Matthieu 7.17-18 ; Jérémie 17.9"],["Le panneau près de la source salée","La Loi est comme un panneau « eau salée, ne pas boire » : elle montre le problème, mais ne rend pas l'eau douce.","Romains 3.20 ; 7.7"],["Ne pas seulement éviter : être béni et bénir","Éphésiens 4 et 5 associe chaque « vieil homme » à un « homme nouveau » : ne plus mentir, mais dire la vérité ; ne plus voler, mais travailler pour donner. La clé : ne pas attrister l'Esprit.","Éphésiens 4.22-32 ; 5.18"],["Romains 7 : « Misérable homme »","La Loi montre combien ma nature est inacceptable. Ce que je veux, je ne le fais pas. Dans ce passage, « je » revient sans cesse ; l'Esprit n'y est jamais nommé.","Romains 7.15-24"],["Romains 8 : la solution","Une nature nouvelle, et marcher selon l'Esprit. « Je rends grâces à Dieu par Jésus Christ. » Paul a traversé Romains 7, mais il résidait en Romains 8.","Romains 7.25 ; 8.1-4"]],"schema":{"type":"flow","titre":"Le schéma à retenir : l'arbre","items":[["1","Les fruits","mon comportement"],["2","Le tronc","mon cœur, mes désirs"],["3","La racine","ma nature humaine"],["4","La solution","une vie nouvelle : l'Esprit"]]},"table":{"titre":"Éphésiens 4 et 5 : dépouiller et revêtir","head":["Le vieil homme","Mais…","Le verset"],"rows":[["Le mensonge","dire la vérité","4.25"],["Le vol","travailler pour donner","4.28"],["Les paroles mauvaises","ce qui édifie et donne grâce","4.29"],["L'amertume, la colère","la bonté, le pardon","4.31-32"],["L'ivresse","être rempli de l'Esprit","5.18"]]},"piege":[["Pour changer, je dois couper mes mauvaises habitudes.","Couper les fruits ne change pas la racine ; il me faut la vie de l'Esprit."],["Paul vivait toujours en Romains 7, moi aussi.","Paul l'a traversé, mais il résidait en Romains 8 : Dieu a fait la même provision pour moi."]],"astuce":"Galates 5.16 : « Marchez » est un verbe de chaque pas. On ne marche pas par l'Esprit une fois pour toutes, mais pas après pas.","jesus":"Il n'a pas seulement évité le mal : il « allait de lieu en lieu faisant du bien » (Actes 10.38), oint du Saint-Esprit. Sa sainteté était pleine, pas vide.","royaume":"Le Saint-Esprit est le « gouverneur » du Royaume en moi ; il reproduit sur terre la culture du Roi. L'homme nouveau, c'est le citoyen gouverné par l'Esprit.","mediter":"Quel « vieil homme » est-ce que j'essaie d'arrêter par mes forces ? Quel « homme nouveau » l'Esprit veut-il revêtir à sa place ?","mots":[["Vieil homme","Ma manière de vivre selon la nature humaine."],["Homme nouveau","La vie produite en moi par l'Esprit."],["Romains 7","L'expérience de celui qui lutte avec ses forces sous la Loi."],["Romains 8","La vie selon l'Esprit, sans condamnation."]]},"wb":{"but":"Comprendre que la victoire ne vient pas d'une chair réformée, mais d'une marche par l'Esprit.","ref":"Galates 5.16","verse":"Marchez par l’Esprit, et vous n’accomplirez point la convoitise de la chair.","q":["Pourquoi éviter le mal ne suffit-il pas ? Que dit l'image des ténèbres et de la lumière ?","Pourquoi le comportement n'est-il que le symptôme ? Où est la racine ?","Explique l'illustration du panneau près de la source salée.","Dans Éphésiens 4 et 5, que représentent le « vieil homme » et « l'homme nouveau » ? Quelle est la clé du tableau ?","Que montre Romains 7 ? Quelle est l'issue (Romains 7.25 ; 8.1-4) ?","Paul résidait-il en Romains 7 ? Et moi ?"],"vf":["La vie chrétienne est une lutte à endurer jusqu'au ciel.","Couper les mauvais fruits change la source.","La Loi montre le problème, mais ne le résout pas.","Si je marche par l'Esprit, je n'accomplirai pas la convoitise de la chair."],"vfKey":[false,false,true,true],"ex":[{"k":"C1","q":"Dessine l'arbre : les fruits, le cœur, la racine. Explique pourquoi couper les fruits ne suffit pas.","type":"text","rows":6,"hint":"En ligne : décris ou résume ton schéma avec tes mots (tu peux aussi le dessiner sur papier et le montrer à ton mentor)."},{"k":"C2","q":"Choisis une ligne d'Éphésiens 4-5 : quel « mais » l'Esprit veut-il produire en toi ?","type":"table","cols":["Ce que je dépouille","Ce que l'Esprit revêt en moi"],"rows":5}],"d":["Mes 15 minutes avec Dieu","Lire Éphésiens 4.17 à 5.21","Choisir un « mais » d'Éphésiens chaque matin","Lire Romains 7 et 8","Je répète mon verset"],"j":"Quel « vieil homme » est-ce que j'essaie d'arrêter par mes propres forces ?","go":"Tu n'es pas appelé à réparer le vieil homme, mais à revêtir le nouveau. Marche par l'Esprit."},"quiz":[{"type":"tf","q":"La vie chrétienne est une lutte à endurer jusqu'au ciel.","a":false},{"type":"tf","q":"Couper les mauvais fruits change la source.","a":false},{"type":"tf","q":"La Loi montre le problème, mais ne le résout pas.","a":true},{"type":"tf","q":"Si je marche par l'Esprit, je n'accomplirai pas la convoitise de la chair.","a":true},{"type":"mcq","q":"Quel mot correspond à cette définition ? « Ma manière de vivre selon la nature humaine. »","opts":["Corps","Terre promise","Vieil homme","Premier amour"],"a":2},{"type":"mcq","q":"Quel mot correspond à cette définition ? « La vie produite en moi par l'Esprit. »","opts":["Problème de conduite","Premier amour","Homme nouveau","Esprit"],"a":2},{"type":"mcq","q":"Quel mot correspond à cette définition ? « L'expérience de celui qui lutte avec ses forces sous la Loi. »","opts":["Redevable","Homme nouveau","Romains 7","Esprit"],"a":2},{"type":"mcq","q":"Quelle est la référence du verset de la semaine : « Marchez par l’Esprit, et vous n’accomplirez point la convoitise de la chair. »","opts":["Jean 15.8","1 Corinthiens 3.6-7","1 Thessaloniciens 5.23","Galates 5.16"],"a":3},{"type":"tf","q":"Pour changer, je dois couper mes mauvaises habitudes.","a":false,"why":"Couper les fruits ne change pas la racine ; il me faut la vie de l'Esprit."},{"type":"tf","q":"Paul vivait toujours en Romains 7, moi aussi.","a":false,"why":"Paul l'a traversé, mais il résidait en Romains 8 : Dieu a fait la même provision pour moi."}]},{"n":"3-8","ph":3,"etape":"Étape 2 · La seigneurie","t":"Salut, deux natures et seigneurie","fil":"Une discussion en dix sujets","hook":"Un « oui » d'un jour, et une vie entière pour le vivre…","lire":"1 Corinthiens 6.19-20 ; Romains 12.1-2","sup":{"phrase":"Le salut est par substitution, ma nature humaine n'est pas améliorée, et Christ me possède déjà : la seigneurie est une décision de la volonté, puis un chemin.","dec":["La différence entre mérite et substitution.","Le Saint-Esprit : une Personne, pas un numéro d'urgence.","La seigneurie : un événement, puis un processus."],"pts":[["Substitution, non mérite","Je ne suis pas sauvé parce que je le mérite, mais parce que Jésus a pris ma place. Le salut n'est ni gagné ni gardé par mes efforts.","Éphésiens 2.8-9 ; 2 Corinthiens 5.21"],["Le premier pas","La nouvelle naissance n'est que le premier pas d'une vie de croissance.","1 Pierre 2.2"],["Est-il digne de confiance ?","Tout dépend de ce que je crois du caractère de Dieu. Celui qui doute de sa bonté ne s'abandonnera jamais.","Psaume 34.8 ; Romains 8.32"],["Deux natures, une Personne","Deux natures opposées vivent en moi. Ma victoire n'est pas une nature réparée, mais le Saint-Esprit, une Personne. Pour beaucoup, il n'est qu'un « numéro d'urgence ».","Galates 5.17 ; Jean 14.16-17"],["Tout est déjà à lui","Je ne lui donne rien : il me possède déjà. Je reconnais ce qui est vrai.","1 Corinthiens 6.19-20"],["Un événement, puis un processus","Une décision de la volonté (Oswald Chambers parle d'une crise de la volonté, résumée ici), puis un chemin quotidien. La seigneurie n'est pas un abandon de chaque comportement en un jour, mais de la volonté.","Romains 12.1-2 ; Galates 5.24-25"],["Quel groupe d'Israélites ?","Désert ou terre promise : ma vie reflète l'un des deux groupes de la leçon 3-4, selon ma confiance en son caractère.","Hébreux 3.19 ; 4.9-11"]],"schema":{"type":"flow","titre":"Le schéma à retenir : événement, puis processus","items":[["1","L'événement","je soumets ma volonté"],["2","Le processus","l'Esprit taille, domaine après domaine"],["3","Le fruit","devenir comme Jésus"]]},"table":{"titre":"Événement puis processus, dans l'Écriture","head":["Passage","L'événement","Le processus"],"rows":[["Romains 12.1-2","« Présenter vos corps »","« Soyez transformés »"],["Galates 5.24-25","« Ont crucifié la chair »","« Marchons aussi par l'Esprit »"],["Jésus","Le baptême au Jourdain","Le désert, puis trois ans de ministère"]]},"piege":[["Je garde mon salut par mes bonnes œuvres.","Il est par substitution : ni gagné ni gardé par mes efforts."],["La seigneurie, c'est corriger tout mon comportement d'un coup.","C'est soumettre ma volonté ; puis l'Esprit transforme mon comportement peu à peu."]],"astuce":"1 Corinthiens 6.19-20 : une question (« Ne savez-vous pas ? »), deux faits (temple, acheté), un ordre (« Glorifiez donc Dieu »).","jesus":"Il vivait en communion constante avec l'Esprit et le Père (Luc 4.1 ; Jean 5.19). Pour lui, l'Esprit n'était pas un numéro d'urgence, mais la vie de chaque jour.","royaume":"La citoyenneté du Royaume est donnée à la nouvelle naissance ; apprendre la culture du Royaume prend toute la vie.","mediter":"Quand ai-je soumis ma volonté ? Si c'est fait, quel domaine l'Esprit veut-il tailler maintenant ?","mots":[["Substitution","Jésus a pris ma place et payé pour moi."],["Événement","La décision de soumettre ma volonté."],["Processus","Le chemin quotidien où l'Esprit me transforme."],["Numéro d'urgence","L'erreur de n'appeler l'Esprit qu'en cas de crise."]]},"wb":{"but":"Discuter dix sujets qui relient le salut, mes deux natures et la seigneurie.","ref":"1 Corinthiens 6.19-20","verse":"Ne savez-vous pas que votre corps est le temple du Saint Esprit qui est en vous, et que vous avez de Dieu? Et vous n’êtes pas à vous-mêmes; car vous avez été achetés à prix. Glorifiez donc Dieu dans votre corps.","q":["Quelle est la différence entre un salut « au mérite » et un salut « par substitution » ?","Pourquoi la nouvelle naissance n'est-elle que le premier pas ?","Pourquoi le caractère de Dieu est-il au cœur de la seigneurie ?","Le Saint-Esprit est-il une force ou une Personne ? Qu'est-ce que cela change ?","« Je ne lui donne rien : tout est déjà à lui. » Explique.","Pourquoi la seigneurie est-elle à la fois un événement et un processus ?","Quel groupe d'Israélites ma vie reflète-t-elle aujourd'hui ?"],"vf":["Je garde mon salut par mes bonnes œuvres.","Ma nature humaine est améliorée par le Saint-Esprit.","La seigneurie, c'est d'abord une décision de la volonté.","Le Saint-Esprit est un « numéro d'urgence » pour les moments difficiles."],"vfKey":[false,false,true,false],"ex":[{"k":"C1","q":"Choisis trois des dix sujets et écris ta réponse.","type":"text","rows":7},{"k":"C2","q":"Dessine le schéma « événement puis processus » avec un exemple de ta vie.","type":"text","rows":6,"hint":"En ligne : décris ou résume ton schéma avec tes mots (tu peux aussi le dessiner sur papier et le montrer à ton mentor)."}],"d":["Mes 15 minutes avec Dieu","Parler au Saint-Esprit avant chaque décision","Écrire ma réponse à trois sujets","Relire les leçons 1-7 et 3-4","Je répète mon verset"],"j":"Quand ai-je soumis ma volonté ? Et quel domaine l'Esprit veut-il tailler maintenant ?","go":"Tu n'es pas à toi-même : tu as été acheté à prix. C'est la meilleure nouvelle qui soit."},"quiz":[{"type":"tf","q":"Je garde mon salut par mes bonnes œuvres.","a":false},{"type":"tf","q":"Ma nature humaine est améliorée par le Saint-Esprit.","a":false},{"type":"tf","q":"La seigneurie, c'est d'abord une décision de la volonté.","a":true},{"type":"tf","q":"Le Saint-Esprit est un « numéro d'urgence » pour les moments difficiles.","a":false},{"type":"mcq","q":"Quel mot correspond à cette définition ? « Jésus a pris ma place et payé pour moi. »","opts":["De moi-même","Perte","Seigneurie","Substitution"],"a":3},{"type":"mcq","q":"Quel mot correspond à cette définition ? « La décision de soumettre ma volonté. »","opts":["Problème de conduite","Événement","Fruit de l'Esprit","Saint des saints"],"a":1},{"type":"mcq","q":"Quel mot correspond à cette définition ? « Le chemin quotidien où l'Esprit me transforme. »","opts":["Processus","Vase utilisable","Conforme à son image","Pardon familial"],"a":0},{"type":"mcq","q":"Quelle est la référence du verset de la semaine : « Ne savez-vous pas que votre corps est le temple du Saint Esprit qui est en vous, et que vous avez de Dieu? Et … »","opts":["1 Corinthiens 6.19-20","Romains 8.28","1 Samuel 15.22","Romains 12.1"],"a":0},{"type":"tf","q":"Je garde mon salut par mes bonnes œuvres.","a":false,"why":"Il est par substitution : ni gagné ni gardé par mes efforts."},{"type":"tf","q":"La seigneurie, c'est corriger tout mon comportement d'un coup.","a":false,"why":"C'est soumettre ma volonté ; puis l'Esprit transforme mon comportement peu à peu."}]},{"n":"3-9","ph":3,"etape":"Étape 3 · Demeurer en Christ","t":"Josué 7 : demeurer, confesser, être restauré","fil":"Aï, Acan et la porte d'espérance","hook":"Une armée entière battue… à cause d'un seul objet caché sous une tente.","lire":"Josué 7 ; 1 Jean 1.9","sup":{"phrase":"Un seul péché non réglé suffit à rompre la communion ; la défaite n'est que le symptôme, et la confession sincère rétablit aussitôt les promesses de Dieu.","dec":["Pourquoi la victoire promise était conditionnelle.","La différence entre le symptôme (Aï) et le problème (Acan).","Ce que veut dire confesser : sortir l'objet de la tente."],"pts":[["Une victoire assurée, mais conditionnelle","Israël est dans la terre promise. Dieu promet la victoire, à condition de demeurer dans l'obéissance. À Jéricho, les instructions étaient claires : tout l'interdit appartenait à l'Éternel.","Josué 1.5-9 ; 6.18-19"],["Un peu de levain","Acan prend en secret une partie de l'interdit. Un peu de levain fait lever toute la pâte : tout Israël est touché.","Josué 7.1 ; 1 Corinthiens 5.6"],["Sans consulter Dieu","« Ils sont peu nombreux » : Josué attaque Aï sans demander l'Éternel. Défaite, désarroi : « Pourquoi as-tu fait passer le Jourdain à ce peuple ? »","Josué 7.2-9"],["Aï, le symptôme ; Acan, le problème","Dieu diagnostique : « Israël a péché. » Un pour cent non réglé, et c'est cent pour cent hors de la communion. « Je ne serai plus avec vous si… » Être dans la terre promise ne suffit pas.","Josué 7.10-13"],["La confession","« Mon fils… ne me le cache pas. » Acan confesse : « J'ai vu, j'ai convoité, j'ai pris, j'ai caché. » Confesser, c'est aussi se repentir : sortir l'objet de la tente et le déposer devant l'Éternel.","Josué 7.19-23"],["La restauration","« Ne crains point, et ne t'effraie point » : Dieu rétablit les mêmes promesses qu'au début. Et le butin interdit à Jéricho est permis à Aï : une bonne chose au mauvais moment peut déplaire à Dieu.","Josué 8.1-2"],["La sanctification, peu à peu","Dieu ne montre pas tout à la fois. Il met en lumière ce qu'il veut traiter, et j'y réponds aussitôt.","Deutéronome 7.22 ; 1 Jean 1.7"]],"schema":{"type":"flow","titre":"Le schéma à retenir : les quatre verbes d'Acan","items":[["1","J'ai vu","le regard"],["2","J'ai convoité","le désir"],["3","J'ai pris","l'acte"],["4","J'ai caché","la communion rompue"]]},"table":null,"piege":[["Un petit péché caché n'a pas d'importance.","Un peu de levain fait lever toute la pâte : 1 % non réglé suffit à rompre la communion."],["Confesser, c'est juste dire « j'ai péché ».","C'est aussi se repentir : sortir l'objet de la tente et le déposer devant Dieu."]],"astuce":"1 Jean 1.9 : je confesse, et il est « fidèle » (il tient sa promesse) et « juste » (le sang a payé). Deux raisons d'être sûr du pardon.","jesus":"« Le chef du monde vient, et il n'a rien en moi » (Jean 14.30). Rien de non réglé sous sa tente : l'ennemi n'avait aucune prise sur lui.","royaume":"La protection du Roi accompagne ceux qui vivent selon ses lois. La victoire n'est pas une question de nombre de soldats, mais d'alignement sur le gouvernement du Roi.","mediter":"Quelle est mon « Aï » en ce moment ? Ai-je demandé à Dieu s'il y a un « Acan » ?","mots":[["Interdit","Ce que Dieu s'est réservé ; y toucher rompt la communion."],["Symptôme","La défaite visible (Aï) qui révèle un problème caché."],["Confession","Être d'accord avec Dieu sur mon péché, et m'en séparer."],["Vallée d'Acor","« Vallée du trouble », devenue « porte d'espérance » (Osée 2)."]]},"wb":{"but":"Apprendre de la défaite d'Aï que 1 % non réglé suffit à rompre la communion, et que la confession restaure.","ref":"1 Jean 1.9","verse":"Si nous confessons nos péchés, il est fidèle et juste pour nous pardonner nos péchés et nous purifier de toute iniquité.","q":["Quelle était la condition de la victoire promise à Josué ?","Quelle a été la désobéissance d'Acan ? Pourquoi tout Israël en a-t-il été touché ?","Pourquoi Aï était-il le symptôme, et Acan le problème ?","Quels sont les quatre verbes de la confession d'Acan (Josué 7.21) ?","Confesser, est-ce seulement dire « j'ai péché » ? Que signifie « sortir l'objet de la tente » ?","Que montrent Josué 6.18 et 8.2 sur le bon moment ?"],"vf":["Être dans la terre promise suffit pour avoir la victoire.","Josué a attaqué Aï sans consulter Dieu.","Après la confession, Dieu a rétabli les mêmes promesses qu'au début.","Un petit péché non réglé n'a pas d'importance."],"vfKey":[false,true,true,false],"ex":[{"k":"C1","q":"Mon « Aï » : une défaite qui revient. Puis demande à Dieu s'il y a une cause cachée.","type":"table","cols":["Mon « Aï » (le symptôme)","Ce que Dieu me montre (la cause)"],"rows":5},{"k":"C2","q":"Écris une bonne chose qui serait faite au mauvais moment. Comment discerner le bon moment ?","type":"text","rows":5}],"d":["Mes 15 minutes avec Dieu","Lire Josué 7 et 8.1-2","Chaque soir : « Y a-t-il quelque chose de caché sous ma tente ? »","Régler une chose que je jugeais insignifiante","Je répète mon verset"],"j":"Qu'est-ce que je juge « insignifiant » et que Dieu juge important ?","go":"La vallée du trouble devient une porte d'espérance. Confesse, et la communion est rétablie."},"quiz":[{"type":"tf","q":"Être dans la terre promise suffit pour avoir la victoire.","a":false},{"type":"tf","q":"Josué a attaqué Aï sans consulter Dieu.","a":true},{"type":"tf","q":"Après la confession, Dieu a rétabli les mêmes promesses qu'au début.","a":true},{"type":"tf","q":"Un petit péché non réglé n'a pas d'importance.","a":false},{"type":"mcq","q":"Quel mot correspond à cette définition ? « Ce que Dieu s'est réservé ; y toucher rompt la communion. »","opts":["Germe","Temple","Abandon","Interdit"],"a":3},{"type":"mcq","q":"Quel mot correspond à cette définition ? « La défaite visible (Aï) qui révèle un problème caché. »","opts":["Disciple","Symptôme","Sacrificature","Ressources"],"a":1},{"type":"mcq","q":"Quel mot correspond à cette définition ? « Être d'accord avec Dieu sur mon péché, et m'en séparer. »","opts":["Émonder","Confession","Manipulation du comportement","Numéro d'urgence"],"a":1},{"type":"mcq","q":"Quelle est la référence du verset de la semaine : « Si nous confessons nos péchés, il est fidèle et juste pour nous pardonner nos péchés et nous purifier de toute… »","opts":["Romains 8.28","Proverbes 3.5-6","Galates 2.20","1 Jean 1.9"],"a":3},{"type":"tf","q":"Un petit péché caché n'a pas d'importance.","a":false,"why":"Un peu de levain fait lever toute la pâte : 1 % non réglé suffit à rompre la communion."},{"type":"tf","q":"Confesser, c'est juste dire « j'ai péché ».","a":false,"why":"C'est aussi se repentir : sortir l'objet de la tente et le déposer devant Dieu."}]},{"n":"3-10","ph":3,"etape":"Étape 3 · Demeurer en Christ","t":"Jean 15 : le cep et les sarments","fil":"Demeurer, verset par verset","hook":"Pourquoi le vigneron coupe-t-il les beaux sarments verts ?","lire":"Jean 15.1-17 ; Jean 13.1-10","sup":{"phrase":"Le Père cultive, Jésus est le vrai cep, je suis un sarment : uni à lui par le salut, je demeure en communion avec lui, et le fruit vient naturellement de sa vie.","dec":["La différence entre l'union et la communion.","Pourquoi le Père émonde le sarment qui porte du fruit.","Le chemin : demeurer, porter du fruit, glorifier le Père, goûter sa joie."],"pts":[["Trois personnages","Le Père est le cultivateur, Jésus le vrai cep, et moi un sarment. Le sarment ne produit rien de lui-même : il reçoit la sève du cep.","Jean 15.1, 5"],["Ôté, ou nettoyé","Le Père émonde le sarment qui porte du fruit : il enlève ce qui fait obstacle, pour qu'il en porte davantage.","Jean 15.2 ; Hébreux 12.10-11"],["L'union et la communion","« Vous êtes déjà nets » (v. 3) : c'est l'union, le salut, une fois pour toutes. « Demeurez en moi » (v. 4) : c'est la communion, sans conflit non réglé. Comme les pieds lavés de Jean 13 : je suis lavé, mais mes pieds ont besoin de l'être chaque jour.","Jean 15.3-4 ; 13.10"],["La main ouverte","Comme un objet posé sur une main ouverte, je demeure en choisissant de rester. Je marche dans la lumière que j'ai, selon mon âge spirituel.","1 Jean 1.7"],["Beaucoup de fruit, ou rien","« Séparés de moi, vous ne pouvez rien faire. » Le sarment sec perd son témoignage. Quand je demeure, mes désirs changent et ressemblent aux siens.","Jean 15.5-7"],["Obéir, aimer, la joie","Comment demeurer ? En gardant ses commandements, comme lui a gardé ceux du Père. Le commandement : aimer comme il a aimé. Le résultat : sa joie, pleinement.","Jean 15.9-12"],["Non plus esclaves, mais amis","Il nous appelle amis, nous fait connaître ses affaires, et nous a choisis pour porter un fruit qui demeure.","Jean 15.13-17"]],"schema":{"type":"flow","titre":"Le schéma à retenir : le chemin de Jean 15","items":[["v. 4","Demeurer","en communion"],["v. 5","Porter du fruit","beaucoup de fruit"],["v. 8","Glorifier","le Père"],["v. 11","La joie","sa joie, pleinement"]]},"table":{"titre":"Union et communion","head":["","L'union","La communion"],"rows":[["Le verset","« Vous êtes déjà nets » (v. 3)","« Demeurez en moi » (v. 4)"],["Ce que c'est","Mon salut, ma place dans la famille","Ma relation vécue chaque jour"],["Peut-elle se perdre ?","Non","Oui, quand un conflit n'est pas réglé"],["L'image","Être lavé tout entier","Avoir les pieds lavés"]]},"piege":[["Je dois produire du fruit par mes efforts.","Jésus ne commande jamais de produire du fruit : il commande de demeurer, et le fruit est promis."],["Mon fruit doit ressembler à celui des autres.","Chaque sarment porte le fruit que le cep produit en lui : je ne me compare pas."]],"astuce":"Jean 15.9 : un amour en cascade. Le Père → Jésus → moi. Ma part : « demeurez ».","jesus":"« Comme moi j'ai gardé les commandements de mon Père, et je demeure dans son amour » (v. 10). Il nous demande de vivre avec lui ce qu'il vivait avec le Père.","royaume":"Le Royaume se reproduit comme la vie, par semence et par fruit, non par la force. Un sarment relié au Roi porte le fruit du Royaume là où il est planté.","mediter":"Mes pieds ont-ils besoin d'être lavés aujourd'hui ? Qui goûte mon fruit ?","mots":[["Cep","Le pied de vigne : Jésus, la source de vie."],["Sarment","La branche : moi, qui reçois la vie du cep."],["Émonder","Tailler ce qui fait obstacle, pour plus de fruit."],["Union / communion","Mon salut (définitif) / ma relation de chaque jour (qui peut s'interrompre)."]]},"wb":{"but":"Étudier Jean 15.1-17 verset par verset : l'union, la communion, l'émondage et le fruit.","ref":"Jean 15.9","verse":"Comme le Père m’a aimé, moi aussi je vous ai aimés; demeurez dans mon amour.","q":["Qui sont les trois personnages de Jean 15.1-5 ?","Quelle est la différence entre l'union (v. 3) et la communion (v. 4) ?","Pourquoi le Père émonde-t-il le sarment qui porte du fruit ?","Explique l'illustration de la main ouverte.","Selon le verset 10, comment demeurer dans son amour ?","Jésus commande-t-il de produire du fruit ? Que commande-t-il ?","Quel est le chemin des versets 4, 5, 8 et 11 ?"],"vf":["Je dois produire du fruit par mes efforts.","Être « net » (v. 3) parle du salut.","L'émondage enlève ce qui fait obstacle à plus de fruit.","Je dois comparer mon fruit à celui des autres."],"vfKey":[false,true,true,false],"ex":[{"k":"C1","q":"Relève dans Jean 15.1-17 ce que fait chacun.","type":"table","cols":["Le Père","Jésus","Ce qui m'est demandé"],"rows":5},{"k":"C2","q":"Lis les résultats d'une communion continuelle. Lequel vois-tu dans ta vie ? Lequel manque ?","type":"text","rows":5}],"d":["Mes 15 minutes avec Dieu","Lire deux ou trois versets de Jean 15","Chaque soir : « Mes pieds ont-ils besoin d'être lavés ? »","Faire un acte d'amour concret (v. 12)","Je répète mon verset"],"j":"Mes désirs ressemblent-ils davantage aux siens qu'il y a un mois ?","go":"Le sarment ne force pas : il demeure. Le fruit viendra, et le Père sera glorifié."},"quiz":[{"type":"tf","q":"Je dois produire du fruit par mes efforts.","a":false},{"type":"tf","q":"Être « net » (v. 3) parle du salut.","a":true},{"type":"tf","q":"L'émondage enlève ce qui fait obstacle à plus de fruit.","a":true},{"type":"tf","q":"Je dois comparer mon fruit à celui des autres.","a":false},{"type":"mcq","q":"Quel mot correspond à cette définition ? « Le pied de vigne : Jésus, la source de vie. »","opts":["Matériel","Cep","Désert spirituel","Discipulat"],"a":1},{"type":"mcq","q":"Quel mot correspond à cette définition ? « La branche : moi, qui reçois la vie du cep. »","opts":["Méditer","Temple","Épreuve","Sarment"],"a":3},{"type":"mcq","q":"Quel mot correspond à cette définition ? « Tailler ce qui fait obstacle, pour plus de fruit. »","opts":["Émonder","Discerner","Manipulation du comportement","Union / communion"],"a":0},{"type":"mcq","q":"Quelle est la référence du verset de la semaine : « Comme le Père m’a aimé, moi aussi je vous ai aimés; demeurez dans mon amour. »","opts":["1 Corinthiens 3.9","Jean 15.9","2 Timothée 2.2","1 Pierre 2.5"],"a":1},{"type":"tf","q":"Je dois produire du fruit par mes efforts.","a":false,"why":"Jésus ne commande jamais de produire du fruit : il commande de demeurer, et le fruit est promis."},{"type":"tf","q":"Mon fruit doit ressembler à celui des autres.","a":false,"why":"Chaque sarment porte le fruit que le cep produit en lui : je ne me compare pas."}]},{"n":"3-11","ph":3,"etape":"Étape 3 · Demeurer en Christ","t":"Jésus, notre modèle pour demeurer","fil":"Marcher comme lui a marché","hook":"Le gant ne bouge pas tout seul. Et toi ?","lire":"Jean 5.19-30 ; 1 Jean 2.6","sup":{"phrase":"Sur la terre, le Fils n'était pas la source : il disait et faisait ce qu'il recevait du Père ; Dieu veut que je demeure et que je marche comme lui.","dec":["Pourquoi Jésus a pu être notre modèle.","Ce que signifie « je ne fais rien de moi-même ».","Le petit mot « comme »."],"pts":[["Le Germe","Les prophètes annoncent le « Germe » : le Fils, le sarment parfait de Dieu.","Ésaïe 11.1 ; Zacharie 6.12"],["Un vase disponible","Il n'était pas la source : il était disponible. « Je ne fais rien de moi-même » ; « comme le Père m'a dit, ainsi je parle ».","Jean 5.19, 30 ; 12.49-50"],["Dieu rendu visible","« Celui qui m'a vu a vu le Père. » Il est l'image du Dieu invisible.","Jean 14.9-10 ; Colossiens 1.15"],["Plaire au Père","Il ne recevait pas de gloire des hommes ; c'est son Père qui le glorifiait. À Gethsémané : « que ta volonté soit faite ».","Jean 5.41 ; 8.29, 54 ; Matthieu 26.39"],["Une confiance totale","Il s'est entièrement remis aux soins du Père, obéissant jusqu'à la mort de la croix.","1 Pierre 2.23 ; Philippiens 2.8"],["Pour moi : « comme »","« Comme le Père m'a envoyé, moi aussi je vous envoie. » Dieu veut que je demeure comme Jésus, pour être rendu conforme à son image.","1 Jean 2.6 ; Jean 20.21 ; Romains 8.29"]],"schema":{"type":"grid","titre":"Le schéma à retenir : six vérités sur le Fils, notre modèle","cols":3,"items":[["Le Germe","le sarment parfait"],["Disponible","il recevait du Père"],["Dieu visible","qui l'a vu a vu le Père"],["Plaire au Père","non aux hommes"],["Confiance","jusqu'à la croix"],["Pour moi","marcher « comme » lui"]]},"table":null,"piege":[["Jésus vivait par sa propre divinité, je ne peux donc pas l'imiter.","Il vivait en dépendant du Père : « je ne fais rien de moi-même ». C'est pourquoi il est notre modèle."],["Chercher l'approbation des autres est normal.","Jésus ne recevait pas de gloire des hommes : il cherchait seulement à plaire au Père."]],"astuce":"1 Jean 2.6 : « celui qui dit… doit… comme ». Dire, devoir, comme : mes paroles doivent rejoindre ma marche.","jesus":"« Je fais toujours les choses qui lui plaisent » (Jean 8.29). Toute sa vie tient dans cette phrase : écouter le Père, et faire ce qui lui plaît.","royaume":"L'ambassadeur ne parle pas de lui-même : il dit ce que son roi lui a confié. Jésus, puis ses disciples, sont envoyés « comme » des ambassadeurs (Jean 20.21).","mediter":"De qui ai-je cherché l'approbation cette semaine ? Qu'ai-je dit ou fait « de moi-même » ?","mots":[["Germe","Titre messianique : le rejeton annoncé par les prophètes."],["De moi-même","Agir par ma propre initiative, sans dépendre du Père."],["Conforme à son image","Le but de Dieu : que je ressemble à son Fils."],["Comme","Le mot qui fait de la vie de Jésus le modèle de la mienne."]]},"wb":{"but":"Regarder comment le Fils a demeuré dans le Père, pour marcher comme lui a marché.","ref":"1 Jean 2.6","verse":"Celui qui dit demeurer en lui, doit lui-même aussi marcher comme lui a marché.","q":["Pourquoi le Fils est-il appelé le « Germe » ?","« Je ne fais rien de moi-même » : que nous apprend cette parole sur la façon dont Jésus vivait ?","Que signifie « celui qui m'a vu a vu le Père » ?","Jésus cherchait-il la gloire des hommes ? Qui le glorifiait ?","Comment Jésus s'est-il confié au Père à Gethsémané ?","Que veut dire le petit mot « comme » dans 1 Jean 2.6 et Jean 20.21 ?"],"vf":["Jésus a vécu sur la terre en puisant dans sa propre divinité.","Jésus disait ce qu'il entendait du Père.","Jésus cherchait l'approbation des foules.","Dieu veut que je demeure comme Jésus demeurait dans le Père."],"vfKey":[false,true,false,true],"ex":[{"k":"C1","q":"Relève dans l'Évangile de Jean les phrases où Jésus dit « de moi-même ».","type":"table","cols":["La référence","Ce que Jésus dit","Ce que j'apprends"],"rows":5},{"k":"C2","q":"Écris ton « comme » : comment marcher cette semaine comme lui a marché ?","type":"text","rows":5}],"d":["Mes 15 minutes avec Dieu","Lire Jean 5, 8 et 17","Avant chaque décision : « Père, qu'est-ce qui te plaît ? »","Faire une bonne action en secret","Je répète mon verset"],"j":"De qui ai-je cherché l'approbation cette semaine ?","go":"Jésus n'est pas seulement ton Sauveur : il est ton modèle. Ce qu'il a vécu avec le Père, il veut le vivre en toi."},"quiz":[{"type":"tf","q":"Jésus a vécu sur la terre en puisant dans sa propre divinité.","a":false},{"type":"tf","q":"Jésus disait ce qu'il entendait du Père.","a":true},{"type":"tf","q":"Jésus cherchait l'approbation des foules.","a":false},{"type":"tf","q":"Dieu veut que je demeure comme Jésus demeurait dans le Père.","a":true},{"type":"mcq","q":"Quel mot correspond à cette définition ? « Titre messianique : le rejeton annoncé par les prophètes. »","opts":["Être / faire","Restauration","Germe","Comptes courts"],"a":2},{"type":"mcq","q":"Quel mot correspond à cette définition ? « Agir par ma propre initiative, sans dépendre du Père. »","opts":["De moi-même","Converti / disciple","Nature humaine","Chair"],"a":0},{"type":"mcq","q":"Quel mot correspond à cette définition ? « Le but de Dieu : que je ressemble à son Fils. »","opts":["Union / communion","Volonté permissive","Enseignable","Conforme à son image"],"a":3},{"type":"mcq","q":"Quelle est la référence du verset de la semaine : « Celui qui dit demeurer en lui, doit lui-même aussi marcher comme lui a marché. »","opts":["Éphésiens 2.8-9","Romains 12.2","Galates 5.22-23","1 Jean 2.6"],"a":3},{"type":"tf","q":"Jésus vivait par sa propre divinité, je ne peux donc pas l'imiter.","a":false,"why":"Il vivait en dépendant du Père : « je ne fais rien de moi-même ». C'est pourquoi il est notre modèle."},{"type":"tf","q":"Chercher l'approbation des autres est normal.","a":false,"why":"Jésus ne recevait pas de gloire des hommes : il cherchait seulement à plaire au Père."}]},{"n":"3-12","ph":3,"etape":"Étape 3 · Demeurer en Christ","t":"Demeurer : l'illustration du temple","fil":"Mon corps, son temple","hook":"Ton corps est un temple. Mais qu'est-ce qui brouille le reflet du ciel ?","lire":"1 Corinthiens 6.19-20 ; Hébreux 10.19-22","sup":{"phrase":"Mon corps est le temple du Saint-Esprit : quand je demeure, sa vie traverse le voile et remplit mon âme ; un péché non confessé fait écran.","dec":["Le temple : saint des saints, lieu saint, parvis.","Ce qui se passe quand je demeure, et quand je ne demeure pas.","Le voile déchiré et les sacrifices spirituels."],"pts":[["Trois parties","Le saint des saints correspond à mon esprit, où habite le Saint-Esprit ; le lieu saint, à mon âme ; le parvis, à mon corps. Jésus parlait du « temple de son corps ».","1 Corinthiens 3.16 ; 6.19-20 ; Jean 2.19-21"],["Quand je demeure","Rien ne fait obstacle : l'Esprit remplit mon âme de paix, de joie, de repos, de lumière, de fécondité. Dans le parvis, la nature humaine est là, mais la chaîne est brisée ; j'ai présenté mon corps sur l'autel.","Romains 8.6 ; 14.17 ; Galates 5.22-23 ; Romains 12.1"],["Quand je ne demeure pas","Un péché non confessé fait écran entre l'Esprit et mon âme. Je m'appuie sur ma propre sagesse, la nature humaine règne : je ne peux attendre que du bois, du foin et du chaume.","1 Jean 1.5-10 ; Romains 8.5-8"],["Le lac et le verre d'eau","Un lac calme reflète le ciel ; le péché est un caillou qui brouille le reflet, ou une saleté dans un verre d'eau pure. Le péché, c'est « tout ce qui déplaît à Dieu ».",""],["Le voile déchiré","Autrefois, seul le souverain sacrificateur entrait, une fois par an. Le voile s'est déchiré de haut en bas : chaque croyant, comme sacrificateur, peut entrer avec assurance.","Matthieu 27.51 ; Hébreux 10.19-22"],["Fruit, lumière, eau vive","Une sainte sacrificature offre des sacrifices spirituels. La lumière de Dieu doit briller à travers moi, son eau vive couler à travers moi. Et dans la cité céleste, le Seigneur et l'Agneau seront le temple.","1 Pierre 2.5 ; Matthieu 5.16 ; Jean 7.38 ; Apocalypse 21.22"]],"schema":{"type":"table","titre":"Le schéma à retenir : le temple et moi","head":["Le temple","En moi","Quand je demeure"],"rows":[["Le saint des saints","Mon esprit","Le Saint-Esprit y habite"],["Le voile","","Rien ne fait écran"],["Le lieu saint","Mon âme","Paix, joie, repos, lumière"],["Le parvis","Mon corps","Présenté sur l'autel"]]},"table":null,"piege":[["Seuls les pasteurs ont accès à la présence de Dieu.","Le voile est déchiré : chaque croyant est sacrificateur et peut entrer avec assurance."],["Un « petit » péché ne change rien.","Une goutte d'encre suffit à troubler un verre d'eau : je confesse aussitôt."]],"astuce":"1 Pierre 2.5 : des « pierres vivantes » qui forment une maison, et une « sacrificature » qui offre. Je suis à la fois temple et prêtre.","jesus":"Il parlait du « temple de son corps » (Jean 2.21). En lui, Dieu habitait pleinement, et sa vie entière était un culte rendu au Père.","royaume":"Le temple était le lieu où le Roi habitait au milieu de son peuple. Aujourd'hui, le Roi habite en ses citoyens : chacun est une ambassade du ciel sur la terre.","mediter":"Y a-t-il un « écran noir » entre lui et mon âme ? Quel sacrifice de louange puis-je offrir aujourd'hui ?","mots":[["Saint des saints","La partie la plus intime du temple : mon esprit, où habite l'Esprit."],["Voile","Le rideau qui séparait de la présence de Dieu ; déchiré à la croix."],["Sacrificature","Le service des prêtres ; chaque croyant en fait partie."],["Sacrifice spirituel","La louange, le bien et le partage offerts à Dieu."]]},"wb":{"but":"Comprendre, avec l'image du temple, ce qui se passe quand je demeure et quand je ne demeure pas.","ref":"1 Pierre 2.5","verse":"Vous-mêmes aussi, comme des pierres vivantes, êtes édifiés une maison spirituelle, une sainte sacrificature, pour offrir des sacrifices spirituels, agréables à Dieu par Jésus Christ.","q":["À quelles parties du temple correspondent mon esprit, mon âme et mon corps ?","Que se passe-t-il quand je demeure (moitié gauche du schéma) ?","Que se passe-t-il quand un péché non confessé fait écran (moitié droite) ?","Que montrent les illustrations du lac et du verre d'eau ?","Qu'a changé le voile déchiré (Matthieu 27.51 ; Hébreux 10.19-22) ?","Quels sont les « sacrifices spirituels » que je peux offrir (Hébreux 13.15-16 ; 1 Pierre 2.5) ?"],"vf":["Seuls les pasteurs peuvent entrer dans la présence de Dieu.","Un péché non confessé fait écran entre l'Esprit et mon âme.","Quand je ne demeure pas, je m'appuie sur ma propre sagesse.","Dans la cité céleste, il y aura un grand temple."],"vfKey":[false,true,true,false],"ex":[{"k":"C1","q":"Redessine de mémoire les deux temples du schéma.","type":"text","rows":6,"hint":"En ligne : décris ou résume ton schéma avec tes mots (tu peux aussi le dessiner sur papier et le montrer à ton mentor)."},{"k":"C2","q":"Écris un sacrifice spirituel que tu offriras à Dieu cette semaine.","type":"text","rows":4}],"d":["Mes 15 minutes avec Dieu","Chaque matin : « Seigneur, mon corps est ton temple »","Quand le reflet se brouille, chercher le caillou et confesser","Offrir un sacrifice de louange ou un bienfait","Je répète mon verset"],"j":"Y a-t-il un « écran noir » entre l'Esprit et mon âme en ce moment ?","go":"Le voile est déchiré : tu peux entrer dans sa présence à tout moment. Ton corps est son temple."},"quiz":[{"type":"tf","q":"Seuls les pasteurs peuvent entrer dans la présence de Dieu.","a":false},{"type":"tf","q":"Un péché non confessé fait écran entre l'Esprit et mon âme.","a":true},{"type":"tf","q":"Quand je ne demeure pas, je m'appuie sur ma propre sagesse.","a":true},{"type":"tf","q":"Dans la cité céleste, il y aura un grand temple.","a":false},{"type":"mcq","q":"Quel mot correspond à cette définition ? « La partie la plus intime du temple : mon esprit, où habite l'Esprit. »","opts":["Désert","Saint des saints","Substitution","Méditer"],"a":1},{"type":"mcq","q":"Quel mot correspond à cette définition ? « Le rideau qui séparait de la présence de Dieu ; déchiré à la croix. »","opts":["Confession","Voile","Fidèle","Abandon"],"a":1},{"type":"mcq","q":"Quel mot correspond à cette définition ? « Le service des prêtres ; chaque croyant en fait partie. »","opts":["Converti / disciple","Désert spirituel","Sacrificature","Jourdain"],"a":2},{"type":"mcq","q":"Quelle est la référence du verset de la semaine : « Vous-mêmes aussi, comme des pierres vivantes, êtes édifiés une maison spirituelle, une sainte sacrificature, p… »","opts":["2 Timothée 2.2","1 Pierre 2.5","Galates 5.16","Éphésiens 2.8-9"],"a":1},{"type":"tf","q":"Seuls les pasteurs ont accès à la présence de Dieu.","a":false,"why":"Le voile est déchiré : chaque croyant est sacrificateur et peut entrer avec assurance."},{"type":"tf","q":"Un « petit » péché ne change rien.","a":false,"why":"Une goutte d'encre suffit à troubler un verre d'eau : je confesse aussitôt."}]},{"n":"3-13","ph":3,"etape":"Étape 4 · Le tribunal de Christ","t":"Le tribunal de Christ","fil":"La cérémonie des récompenses","hook":"Que restera-t-il de ta vie quand le feu l'éprouvera ?","lire":"1 Corinthiens 3.8-15 ; Matthieu 6.1-21","sup":{"phrase":"Le tribunal de Christ n'a rien à voir avec le salut ni avec la punition : mes récompenses dépendront du fruit que j'ai laissé l'Esprit produire à travers ma vie.","dec":["Ce que le tribunal n'est pas, et ce qu'il est.","La différence entre perdre une récompense et être puni.","Ce que Dieu récompense, et ce que deviennent mes ressources."],"pts":[["Pas le salut, pas mes exploits","Le salut et la punition ont été réglés à la croix. Dieu n'a besoin de rien de ce que je peux faire pour lui. Mais si Dieu dit que c'est important, ça l'est !","2 Corinthiens 5.9-10"],["Tous, à son retour","Chaque chrétien comparaîtra, même Paul. Cela aura lieu au retour du Seigneur, à la résurrection des justes.","Romains 14.10-12 ; Luc 14.14 ; Apocalypse 22.12"],["Le feu éprouvera l'œuvre","Sur le fondement qu'est Jésus, on bâtit avec de l'or, de l'argent, des pierres précieuses, ou du bois, du foin, du chaume. Ce qui demeure est récompensé ; ce qui brûle est perdu, « mais lui-même sera sauvé ».","1 Corinthiens 3.8-15 ; 4.5"],["Perte, et non punition","« Aucune condamnation » pour le croyant. La « perte », c'est manquer les récompenses que Dieu avait prévues pour moi. Un athlète battu n'est pas jeté en prison : il repart sans la couronne.","Romains 8.1 ; 2 Jean 8"],["Ce que Dieu récompense","La fidélité, la grâce envers le pauvre, supporter l'injure pour lui, aimer ses ennemis, un verre d'eau froide, tout quitter pour lui, servir comme pour le Seigneur, les personnes aidées, endurer l'épreuve. « Amassez-vous des trésors dans le ciel » n'est pas une suggestion.","Matthieu 6.20 ; 10.42 ; Colossiens 3.23-24"],["Des récompenses éternelles","Je cherche la récompense du Père qui voit dans le secret, non la gloire des hommes. Seul ce qui est motivé par l'Esprit, par amour, a une valeur éternelle.","Matthieu 6.1-21 ; 1 Corinthiens 13.1-3"],["Mes trois ressources","Mon temps, mon énergie et mes biens : confiés à l'Esprit, il bâtit pour moi avec de l'or ; refusés, je bâtis du chaume.","1 Corinthiens 3.12"]],"schema":{"type":"table","titre":"Le schéma à retenir : le feu éprouvera l'œuvre","head":["","Or, argent, pierres précieuses","Bois, foin, chaume"],"rows":[["L'origine","Ce que l'Esprit a produit","Ce que j'ai fait par moi-même"],["Le motif","L'amour, le Père qui voit","Être vu des hommes"],["Au feu","Cela demeure","Cela brûle"],["Le résultat","Une récompense","La perte, mais je suis sauvé"]]},"table":{"titre":"Cinq couronnes du Nouveau Testament","head":["La couronne","Pour qui ?","Le verset"],"rows":[["Incorruptible","Celui qui court avec maîtrise de soi","1 Corinthiens 9.25"],["De joie","Les personnes amenées et aidées","1 Thessaloniciens 2.19"],["De justice","Ceux qui aiment son apparition","2 Timothée 4.8"],["De vie","Celui qui endure l'épreuve","Jacques 1.12"],["De gloire","Les bergers fidèles","1 Pierre 5.4"]]},"piege":[["Au tribunal, Dieu décidera si je vais au ciel.","Il concerne des croyants déjà sauvés : « lui-même sera sauvé »."],["Chercher une récompense, c'est égoïste.","C'est Jésus qui l'ordonne : « Amassez-vous des trésors dans le ciel »."]],"astuce":"2 Corinthiens 5.10 : « tous », « manifestés », « chacun », « reçoive ». Personne n'est oublié, rien n'est caché, chacun reçoit.","jesus":"« À cause de la joie qui était devant lui, il a enduré la croix » (Hébreux 12.2). Il regardait au-delà de la souffrance, vers la récompense.","royaume":"Le Roi confie ses ressources à des intendants. Il ne les juge pas sur leur rang, mais sur leur fidélité : « sois établi sur dix villes » (Luc 19.17).","mediter":"Que deviendrait mon agenda de cette semaine passé au feu ?","mots":[["Tribunal de Christ","La cérémonie où les croyants recevront ou perdront des récompenses."],["Perte","Manquer les récompenses que Dieu avait prévues ; ce n'est pas une punition."],["Trésor dans le ciel","Ce qui a une valeur éternelle aux yeux de Dieu."],["Ressources","Mon temps, mon énergie, mes biens."]]},"wb":{"but":"Comprendre la cérémonie des récompenses : ce qu'elle n'est pas, ce qu'elle est, et ce qui y sera récompensé.","ref":"2 Corinthiens 5.10","verse":"Car il faut que nous soyons tous manifestés devant le tribunal du Christ, afin que chacun reçoive les choses accomplies dans le corps, selon ce qu’il aura fait, soit bien, soit mal.","q":["Le tribunal de Christ a-t-il à voir avec le salut ou la punition ? Sur quoi les récompenses seront-elles basées ?","Qui comparaîtra devant le tribunal de Christ ? Quand aura-t-il lieu ?","Que montre 1 Corinthiens 3.12-15 sur la nature du tribunal ? Que signifie « subir une perte » ?","Quelle est la différence entre perdre une récompense et être puni ?","Cite quatre choses pour lesquelles les croyants seront récompensés.","Pourquoi seul ce qui est motivé par le Saint-Esprit sera-t-il récompensé ?","Que deviennent mon temps, mon énergie et mes biens selon que je les confie ou non à l'Esprit ?"],"vf":["Au tribunal de Christ, le croyant risque de perdre son salut.","« Amassez-vous des trésors dans le ciel » n'est qu'une suggestion.","Un verre d'eau froide donné par amour ne perdra pas sa récompense.","Les croyants de l'Ancien Testament seront aussi récompensés."],"vfKey":[false,false,true,true],"ex":[{"k":"C1","q":"Où vont mon temps, mon énergie et mes biens ?","type":"table","cols":["Ma ressource","Ce que j'en fais","Or ou chaume ?"],"rows":5},{"k":"C2","q":"Choisis une des dix récompenses du point 6 et écris comment la vivre cette semaine.","type":"text","rows":5}],"d":["Mes 15 minutes avec Dieu","Faire un bien dans le secret (Matthieu 6.3-4)","Chaque soir : « Qu'est-ce qui résistera au feu ? »","Confier une ressource précise à l'Esprit","Je répète mon verset"],"j":"Que deviendrait mon agenda de cette semaine passé au feu ?","go":"Si Dieu dit que c'est important, ça l'est ! Ce que l'Esprit produit en toi demeure pour l'éternité."},"quiz":[{"type":"tf","q":"Au tribunal de Christ, le croyant risque de perdre son salut.","a":false},{"type":"tf","q":"« Amassez-vous des trésors dans le ciel » n'est qu'une suggestion.","a":false},{"type":"tf","q":"Un verre d'eau froide donné par amour ne perdra pas sa récompense.","a":true},{"type":"tf","q":"Les croyants de l'Ancien Testament seront aussi récompensés.","a":true},{"type":"mcq","q":"Quel mot correspond à cette définition ? « La cérémonie où les croyants recevront ou perdront des récompenses. »","opts":["Tribunal de Christ","Romains 8","Abandon","Intimité spirituelle"],"a":0},{"type":"mcq","q":"Quel mot correspond à cette définition ? « Manquer les récompenses que Dieu avait prévues ; ce n'est pas une punition. »","opts":["Processus","Perte","Orgueil spirituel","Don spirituel"],"a":1},{"type":"mcq","q":"Quel mot correspond à cette définition ? « Ce qui a une valeur éternelle aux yeux de Dieu. »","opts":["Mentor","Parent spirituel","Nature humaine","Trésor dans le ciel"],"a":3},{"type":"mcq","q":"Quelle est la référence du verset de la semaine : « Car il faut que nous soyons tous manifestés devant le tribunal du Christ, afin que chacun reçoive les choses a… »","opts":["2 Corinthiens 5.10","Jean 15.9","Galates 5.22-23","Romains 8.28"],"a":0},{"type":"tf","q":"Au tribunal, Dieu décidera si je vais au ciel.","a":false,"why":"Il concerne des croyants déjà sauvés : « lui-même sera sauvé »."},{"type":"tf","q":"Chercher une récompense, c'est égoïste.","a":false,"why":"C'est Jésus qui l'ordonne : « Amassez-vous des trésors dans le ciel »."}]},{"n":"3-14","ph":3,"etape":"Étape 4 · Le tribunal de Christ","t":"Le bêma : une étude théologique","fil":"Une estrade, pas un banc des accusés","hook":"« Tribunal » : un banc des accusés… ou une estrade de vainqueurs ?","lire":"1 Corinthiens 9.24-27 ; 1 Jean 2.28","sup":{"phrase":"Le bêma est l'estrade où le juge couronnait les vainqueurs : Jésus, qui est mort pour moi, y examinera mes œuvres, non pour me punir, mais pour récompenser ce que l'Esprit a produit.","dec":["Le sens du mot bêma et l'ordre des événements.","Pourquoi le croyant ne sera pas puni, et pourquoi confesser quand même.","La honte passagère, la joie dominante, et les couronnes."],"pts":[["Le mot « bêma »","Dans les Évangiles, l'estrade d'un magistrat romain. Chez Paul, l'estrade des jeux isthmiques, où le juge couronnait le vainqueur. « Le juge récompensait les vainqueurs ; il ne fouettait pas les perdants » (Samuel Hoyt).","Romains 14.10 ; 1 Corinthiens 9.24-25 ; 2 Timothée 2.5"],["Quand, où, qui","Juste après l'enlèvement de l'Église, dans les lieux célestes, devant Jésus. Tous les croyants, quel que soit leur état spirituel, y comparaîtront.","1 Thessaloniciens 4.16-17 ; 5.9-10 ; Apocalypse 19.7-8"],["Trois vues","Un lieu de terreur où les péchés sont exposés ; une simple fête sans aucune honte ; ou un examen sérieux, avec éloges et sans punition. L'étude retient la troisième.",""],["Le péché a des conséquences présentes","Perte de la communion, discipline du Père, perte de puissance, d'occasions, de désir de servir, relations brisées, parfois la santé, et la perte des récompenses.","Psaume 32.3-4 ; Hébreux 12.5-11"],["Pas punitif","Punir le croyant pour des péchés déjà payés, ce serait exiger deux paiements. Mes péchés sont effacés, éloignés, jetés au fond de la mer.","Hébreux 10.14, 17-18 ; Michée 7.19"],["Pourquoi confesser alors ?","Le pardon légal m'a été donné une fois pour toutes ; le pardon familial garde la communion chaque jour. Le jugement de cette vie est la discipline d'un Père.","Amos 3.3 ; 1 Corinthiens 11.31-32"],["Honte passagère, joie dominante","Il pourra y avoir un regret au moment où nos œuvres seront manifestées (1 Jean 2.28), mais Dieu essuiera toute larme. Les récompenses : couronnes, trésor, éloges, responsabilités. Et nous jetterons nos couronnes à ses pieds.","Apocalypse 4.10-11 ; 21.4 ; Luc 19.17"]],"schema":{"type":"flow","titre":"Le schéma à retenir : l'ordre des événements","items":[["1","L'enlèvement","corps glorifié"],["2","L'élévation","dans les cieux"],["3","L'examen","devant le bêma"],["4","Les récompenses","ou leur perte"]]},"table":{"titre":"Pardon légal et pardon familial","head":["","Le pardon légal","Le pardon familial"],"rows":[["Quand ?","Une fois, quand j'ai cru","Chaque jour, quand je confesse"],["Ce qu'il touche","Ma position devant Dieu","Ma communion avec lui"],["Peut-il se perdre ?","Non","La communion s'interrompt, puis se rétablit"],["Le jugement","Porté par Christ","La discipline d'un Père"]]},"piege":[["Au bêma, mes péchés seront étalés devant tous.","Dieu ne se souvient plus de mes péchés (Hébreux 10.17) : c'est l'œuvre qui est éprouvée."],["Puisque je ne serai pas puni, le péché n'est pas grave.","Le péché a des conséquences présentes sérieuses, et il me coûte des récompenses."]],"astuce":"1 Jean 2.28 : « demeurez » (ma part), « quand il sera manifesté » (son retour), « assurance » (le résultat).","jesus":"Obéissant jusqu'à la mort, « c'est pourquoi aussi Dieu l'a haut élevé » (Philippiens 2.8-9). Le Fils lui-même a été honoré par le Père.","royaume":"Dieu a créé l'homme pour dominer (Genèse 1.26). En Christ, cette mission est rétablie : les récompenses sont des responsabilités dans le gouvernement du Roi (Apocalypse 5.10).","mediter":"Est-ce que j'attends le bêma avec crainte, ou avec assurance ?","mots":[["Bêma","L'estrade où le juge des jeux couronnait les vainqueurs."],["Stéphanos","La couronne du vainqueur promise aux croyants fidèles."],["Pardon légal","Le pardon de tous mes péchés, reçu une fois pour toutes."],["Pardon familial","Le pardon quotidien qui garde la communion."]]},"wb":{"but":"Approfondir la doctrine des récompenses : le mot bêma, le moment, le but, la honte et les couronnes.","ref":"1 Jean 2.28","verse":"Maintenant, enfants, demeurez en lui, afin que, quand il sera manifesté, nous ayons de l’assurance et que nous ne soyons pas couverts de honte, de par lui, à sa venue.","q":["D'où vient le mot « bêma » ? Pourquoi n'est-ce pas un banc des accusés ?","Quel est l'ordre des événements selon l'étude (enlèvement, élévation, examen, récompenses) ?","Quelles sont les trois vues du bêma ? Laquelle s'accorde avec l'Écriture, et pourquoi ?","Cite quatre conséquences présentes du péché dans la vie du croyant.","Pourquoi Dieu ne punira-t-il pas au bêma les péchés du croyant ?","Pardon légal et pardon familial : quelle différence ? Pourquoi confesser alors ?","Nomme trois couronnes et ce pour quoi elles sont données."],"vf":["Le juge du bêma récompensait les vainqueurs et ne fouettait pas les perdants.","Seuls les croyants spirituels seront enlevés.","Chercher une récompense est toujours un motif égoïste.","Nous jetterons nos couronnes devant le trône, car lui seul est digne."],"vfKey":[true,false,false,true],"ex":[{"k":"C1","q":"Associe chaque couronne à sa raison.","type":"table","cols":["La couronne","Le verset","Pour quoi ?"],"rows":5},{"k":"C2","q":"Laquelle des huit conséquences présentes du péché vois-tu dans ta vie ? Qu'en fais-tu ?","type":"text","rows":5}],"d":["Mes 15 minutes avec Dieu","Régler avec le Seigneur une conséquence du péché qu'il me montre","Remercier pour un péché « jeté au fond de la mer »","Expliquer pardon légal et pardon familial à quelqu'un","Je répète mon verset"],"j":"Est-ce que j'attends le bêma avec crainte, ou avec assurance ?","go":"Celui qui te jugera est celui qui est mort pour toi. Demeure en lui, et tu auras de l'assurance à sa venue."},"quiz":[{"type":"tf","q":"Le juge du bêma récompensait les vainqueurs et ne fouettait pas les perdants.","a":true},{"type":"tf","q":"Seuls les croyants spirituels seront enlevés.","a":false},{"type":"tf","q":"Chercher une récompense est toujours un motif égoïste.","a":false},{"type":"tf","q":"Nous jetterons nos couronnes devant le trône, car lui seul est digne.","a":true},{"type":"mcq","q":"Quel mot correspond à cette définition ? « L'estrade où le juge des jeux couronnait les vainqueurs. »","opts":["Discipulat","Bêma","Communion","Comptes courts"],"a":1},{"type":"mcq","q":"Quel mot correspond à cette définition ? « La couronne du vainqueur promise aux croyants fidèles. »","opts":["Enseignable","Stéphanos","Discerner","Esprit"],"a":1},{"type":"mcq","q":"Quel mot correspond à cette définition ? « Le pardon de tous mes péchés, reçu une fois pour toutes. »","opts":["Sanctification","Pardon légal","Converti / disciple","Ressources"],"a":1},{"type":"mcq","q":"Quelle est la référence du verset de la semaine : « Maintenant, enfants, demeurez en lui, afin que, quand il sera manifesté, nous ayons de l’assurance et que nous… »","opts":["Luc 6.12-13","1 Jean 1.9","1 Samuel 15.22","1 Jean 2.28"],"a":3},{"type":"tf","q":"Au bêma, mes péchés seront étalés devant tous.","a":false,"why":"Dieu ne se souvient plus de mes péchés (Hébreux 10.17) : c'est l'œuvre qui est éprouvée."},{"type":"tf","q":"Puisque je ne serai pas puni, le péché n'est pas grave.","a":false,"why":"Le péché a des conséquences présentes sérieuses, et il me coûte des récompenses."}]},{"n":"3-15","ph":3,"etape":"Étape 4 · Le tribunal de Christ","t":"Demeurer et le tribunal de Christ","fil":"Cinq sujets, puis l'envoi","hook":"Une course de relais se gagne… en transmettant le témoin.","lire":"Jean 15.1-8 ; Matthieu 28.18-20","sup":{"phrase":"Demeurer est mon droit de naissance ; ce que l'Esprit produit en moi a une valeur éternelle ; et le dernier commandement de Jésus m'envoie faire des disciples.","dec":["Mon « faire » découle de mon « être ».","Chercher les récompenses éternelles : un commandement, pas un mauvais motif.","L'envoi : qui vais-je accompagner ?"],"pts":[["Demeurer, un droit de naissance","La communion avec l'Esprit n'est pas gagnée par l'obéissance : elle m'est donnée. Le péché l'interrompt, et c'est pourquoi Dieu s'en soucie. L'obéissance me garde dans la lumière ; le fruit naît de la relation.","Galates 5.22-23 ; 1 Jean 1.7"],["Romains 7 ou Romains 8","Chaque chrétien doit reconnaître que sa nature humaine est sans espoir : c'est le rôle de la Loi en Romains 7. Paul l'a traversé, mais il résidait en Romains 8. L'Esprit en moi est plus puissant que ma nature humaine.","Romains 7.24-25 ; 8.1-2"],["Chercher ses récompenses","Si je désirais les biens, la louange et les plaisirs de ce monde, pourquoi ne pas désirer les récompenses éternelles ? Je ne peux pas plus les imaginer qu'un aveugle de naissance la couleur. Dieu est celui qui récompense.","Matthieu 6.20, 33 ; Hébreux 11.6"],["Étranger sur la terre","Poursuivre le confort, les plaisirs et les biens peut m'empêcher de mûrir : ils étouffent la Parole.","Luc 8.14 ; Colossiens 3.1-3"],["Dieu n'a besoin de rien","Il ne tient pas une liste de ce que je fais pour lui. La question : ce que je fais a-t-il sa vie ? Venu de l'Esprit, cela a une valeur éternelle ; venu de moi, une valeur temporelle.","Jean 6.63 ; 1 Corinthiens 13.1-3"],["Mes ressources","Temps, énergie, biens : je les laisse à l'Esprit (or, argent, pierres précieuses) ou je les lui refuse (bois, foin, chaume). N'est-il pas dans mon intérêt de comprendre cela tôt ?","1 Corinthiens 3.10-15"],["L'envoi","« Allez donc, et faites disciples » : une suggestion ou un commandement ? Tout disciple est un converti, mais tout converti n'est pas un disciple. Si tu as suivi ce parcours, tu es équipé.","Matthieu 28.18-20 ; Colossiens 1.28 ; 2 Timothée 2.2"]],"schema":{"type":"flow","titre":"Le schéma à retenir : de l'être au fruit","items":[["1","Être","demeurer en lui"],["2","Sa vie","elle coule en moi"],["3","Faire","son fruit, naturellement"],["4","Reproduire","faire des disciples"]]},"table":{"titre":"Le but du mentorat spirituel","head":["Le verset","Le but","Le mot-clé"],"rows":[["Colossiens 1.28","Présenter tout homme parfait en Christ","La maturité"],["Jean 15.8","Porter beaucoup de fruit","La fécondité"],["2 Timothée 2.2","Des fidèles qui en instruisent d'autres","La reproduction"]]},"piege":[["L'obéissance est le but de la vie chrétienne.","Le but est la relation ; l'obéissance me garde dans la lumière, et le fruit en découle."],["Faire des disciples, c'est pour les pasteurs.","C'est le dernier commandement de Jésus, donné à tous ses disciples."]],"astuce":"Jean 15.8 : « En ceci » renvoie au fruit. Le Père est glorifié, et c'est ainsi qu'on reconnaît ses disciples.","jesus":"Il demeurait dans le Père, et de là venaient ses œuvres (Jean 14.10). Puis il a formé des disciples et les a envoyés en faire d'autres.","royaume":"Le Royaume ne s'étend pas par des foules de convertis, mais par des citoyens formés qui en forment d'autres. Le Roi récompense les intendants fidèles de sa mission.","mediter":"Qui le Seigneur met-il sur mon cœur pour que je l'accompagne ?","mots":[["Droit de naissance","Ce que j'ai reçu en naissant de nouveau : la communion avec l'Esprit."],["Être / faire","Ma relation avec lui, d'où découlent mes actions."],["Valeur éternelle","Ce qui vient de la vie de l'Esprit et demeure."],["Converti / disciple","Celui qui a cru / celui qui suit Jésus et apprend de lui."]]},"wb":{"but":"Relier « demeurer » et « le tribunal de Christ » en cinq sujets, puis répondre à l'appel à faire des disciples.","ref":"Jean 15.8","verse":"En ceci mon Père est glorifié, que vous portiez beaucoup de fruit; et vous serez mes disciples.","q":["Pourquoi demeurer est-il un « droit de naissance » et non une communion gagnée par l'obéissance ?","Que veut dire : mon « faire » découle de mon « être » ?","Que signifie traverser Romains 7, mais résider en Romains 8 ?","Pourquoi chercher des récompenses éternelles n'est-il pas un mauvais motif ?","Dieu a-t-il besoin de ce que je fais pour lui ? Alors qu'est-ce qui a une valeur éternelle ?","Quel est le dernier commandement de Jésus ? Est-ce une suggestion ou un commandement ?"],"vf":["L'obéissance est le but de la vie chrétienne.","Tout converti est un disciple de Jésus-Christ.","Ce qui vient de mon intelligence humaine n'a qu'une valeur temporelle.","Si j'ai suivi ce parcours, je suis équipé pour accompagner un croyant plus jeune."],"vfKey":[false,false,true,true],"ex":[{"k":"C1","q":"Complète : « Je traverse Romains 7, mais je réside en Romains 8 parce que… »","type":"text","rows":4},{"k":"C2","q":"Le nom de la personne que je vais accompagner, et la date du premier rendez-vous.","type":"table","cols":["Le nom","Comment Dieu me l'a montré","La date"],"rows":5}],"d":["Mes 15 minutes avec Dieu","Chaque matin : « Je demeure en toi ; produis ton fruit »","Confier une ressource à l'Esprit","Préparer mon premier rendez-vous de discipulat","Je répète mon verset"],"j":"Qui le Seigneur met-il sur mon cœur pour que je l'accompagne ?","go":"Tu as achevé la phase 3. Demeure en lui, porte beaucoup de fruit, et va faire des disciples : c'est ainsi que le Père est glorifié."},"quiz":[{"type":"tf","q":"L'obéissance est le but de la vie chrétienne.","a":false},{"type":"tf","q":"Tout converti est un disciple de Jésus-Christ.","a":false},{"type":"tf","q":"Ce qui vient de mon intelligence humaine n'a qu'une valeur temporelle.","a":true},{"type":"tf","q":"Si j'ai suivi ce parcours, je suis équipé pour accompagner un croyant plus jeune.","a":true},{"type":"mcq","q":"Quel mot correspond à cette définition ? « Ce que j'ai reçu en naissant de nouveau : la communion avec l'Esprit. »","opts":["Voile","Nature divine","Cep","Droit de naissance"],"a":3},{"type":"mcq","q":"Quel mot correspond à cette définition ? « Ma relation avec lui, d'où découlent mes actions. »","opts":["Envoi","Être / faire","Méthode passive","Photocopie"],"a":1},{"type":"mcq","q":"Quel mot correspond à cette définition ? « Ce qui vient de la vie de l'Esprit et demeure. »","opts":["Valeur éternelle","Tribunal de Christ","Fondement","Perte"],"a":0},{"type":"mcq","q":"Quelle est la référence du verset de la semaine : « En ceci mon Père est glorifié, que vous portiez beaucoup de fruit; et vous serez mes disciples. »","opts":["Romains 12.1","1 Jean 2.28","Jean 15.5","Jean 15.8"],"a":3},{"type":"tf","q":"L'obéissance est le but de la vie chrétienne.","a":false,"why":"Le but est la relation ; l'obéissance me garde dans la lumière, et le fruit en découle."},{"type":"tf","q":"Faire des disciples, c'est pour les pasteurs.","a":false,"why":"C'est le dernier commandement de Jésus, donné à tous ses disciples."}]}];
